window.__D("text/torat-shmuel/c001",{"p":[[2000560196,"הדבר, כך הענין כאן שהלב בעת התלהבותו יונק מעט שכל רק הארה וכו', וזהו האהבה הטבעיות בחי' מוחין דקטנות. אבל כשמתבונן בגדלות הבורא מאד ומאד עד שהלב מתפעלת מעצמה אינו מרגיש הלב כלל מחמת גודל התקשרותו בשכלו והאהבה אינה תופסת מקום כלל מחמת שהיא כלולה בשכלו, שזה ידוע שבחי' האהבה אינה מהות השכל וכשהיא אצל השכל אזי מבוטלת היא אצל השכל ואינה תופסת מקום כלל, וכשהאהבה בפ\"ע רק שהיא יונקת מעט מהשכל אזי היא תופסת וכו', אבל כשהיא בהתכללות בשכלו אזי היא אינה תופסת מקום כלל, וגם האהבה בוערת יותר כשהיא אינה בפ\"ע שהשכל נותן חיות להאהבה לחזק האהבה וכשהיא בהתכללות שכלו והיא תמיד אצל השכל אזי היא בודאי יותר חזק מאד ובוערת בהתכללות בשכלו מאד, (וכמו זיו השמש בשמש עצמו שהוא בחוזק יותר מכמו שמאיר לארץ ולדרים עלי', הגם כי הזיו בשמש הוא בטל ואינו עולה בשם כלל, וע' בד\"ה נפתלי אילה שלוחה). והמשל לזה כשהאדם עוסק במו\"מ בתקיעת דעתו בזה הוא יומם ולילה יהגה בזה ממש שזה חיותו והוא אינו מרגיש החשק שיש לו מחמת טרדתו בשכלו מאד זהו בחי' מוחין כו'. וזהו נק' בחי' מוחין דגדלות.\n<b>והחילוק</b> שבין בחי' יניקה שהוא בחי' מוחי' דקטנות ובחי' מוחי' דגדלות, שכשהוא בבחי' קטנות אזי האהבה לה' הוא עיקר ולא השכל, והאהבה היא מלובשת ג\"כ באהבה אחרת לאהוב דבר יש ודבר בפ\"ע אכן תוכל ג\"כ לשלוט אהבה אחרת ר\"ל, וז\"ש ה' איש מלחמה ה' שהוא בחי' ז\"א איש מלחמה, אבל כשהאהבה בהתכללות שכלו והשכל מבין ורואה על בוריו שהעיקר הוא אלקות והכל אין ממש אזי אין התגברות מעשיו בא מצדו כ\"כ, וזהו בחכמה אתברירו שעיקר ההתבררות הוא בשכלו וכו', שהמדות בעצם אין להם שכל וזהו בחי' בהמה לכן תוכל להיות לגרמי' וכו', אבל בשכל כו' והבן.\n<b>(הג\"ה</b>, ואפ\"ל שבחי' זו דמוחין זהו ענין שם מ\"ב שהם ז' מדות הכלולים מששה לפי שהם בבחי' ביטול בהמוחין כמ\"ש בביאור דאלה מסעי ד\"ה לבאר ענין המסעות (אולי אפ\"ל שמ\"ש כאן ששם מ\"ב היינו ז\"מ הכלולים מששה, הוא ט\"ס וצ\"ל ו\"מ הכלולי' מז', כי הראה מקום לד\"ה לבאר ענין המסעות, ושם נת' ו' מדות כ\"א כלולה מז', והוא שם מ\"ב דהויות, כמ\"ש בד\"ה הנה גבי המסעות ספ\"א מפרע\"ח"],[2000560197,"שער הקדישי' רפ\"ב, והו\"ע ג' ידות יד הגדולה כו', ג\"פ יד עולה מ\"ב יעו\"ש), ולכן איתא ג\"כ ששם מ\"ב הוא ברישא היינו בכח\"ב כי הוא המשכת מוחין במדות כו' אזי המדות בבחי' אין וענין עיבור עיין בתניא ח\"א פט\"ז, עכ\"ה).\n<b>והנה</b> גלות מצרים נק' בחי' עיבור, כי מצרים הוא בחי' מיצר הגרון ששם בחי' שר המשקים שר האופים שהם כל מיני תאוות גשמיות דאכילה ושתיה, ושט אותיות שטו העם ולקטו כו' ועי\"ז מונעים התפשטות אור השכל במדות, שהגם שבשכלו מבין שהשכל מראה להמדות איך ומה שצריך להיות האהוי\"ר רק אליו ית', ובאמת שבשכל נכללו האהוי\"ר ונק' זה עיבור, אבל עכ\"ז לא בא כן בגילוי במדות ממש להיות לו כח המושך בפועל ממש לאהבת ה' ושיהי' פחד ה' בלבו, רק מ\"מ מחשבה טובה זו מצרפה למעשה דהיינו שמזה נמשך עכ\"פ להיות קיום המעשה בפועל ממש בסור מרע ועשה טוב כיון שמבין כן בשכלו אף שלבו בל עמו וכו'. וע\"ז נאמר במצרים בעבודה קשה להתחזק בעבודה בקשיות נגד המונעים כו'.\n<b>אך</b> יצ\"מ נק' לידה שהוא בחי' שהמדות מתפעלים ממש באהבת ה' ויראתו, ועז\"נ אם הבנים שמחה שכיון שנעשית אם הבנים בבחי' לידת המדות אז היא בחי' שמחה ואהבה בתענוגים ולא עבודה קשה כו'. ועז\"נ וארא אל אברהם כו' באל שדי מלשון ברכת שדים ורחם דהיינו כי אחר הלידה מיד נמשך בחי' חלב דאימא להגדיל המדות שהן בחי' אברהם יצחק ויעקב כו'. וע\"י חלב זה משתעשע הולד ומתענג בשדי אמו כך הוא ענין אם הבנים שמחה. ומ\"מ ושמי הוי' לא נודעתי להם הוא בחי' מוחין דגדלות שהוא בחי' התורה שלמעלה מבחי' השכל השייך להגדלת המדות שהוא בחי' יניקה, עד\"מ באדם השכל השייך למדות הוא כלא חשיב לגבי עצם השכל שבנפש המשכלת, וכך התורה היא ח\"ע שעז\"נ מאד עמקו מחשבותיך שהן בחי' עומק העליון משא\"כ המדות הם בחי' אתגליא כו', הנה בחי' זו לא נודעתי להם כ\"א ע\"י התורה מתגלה בחי' זו ג\"כ, וע\"י גילוי זה ממילא מזדככים המדות ג\"כ בעילוי גדול יותר כי הם בטלים בשכל זה. וזהו ענין התפילין וכמ\"ש כי שם הוי' נקרא עליך אלו תפילין שבראש הרי דמה שנאמר גבי אבות ושמי הוי' לא נודעתי להם נמשך ע\"י מצות תפילין, וגם תפילין לשון חיבור שיהי' שם הוי' בבחי' נודעתי ממש כמ\"ש וידעתם כי אני הוי' כו'."],[2000560198,"<b>וז\"ש</b> והי' לאות כו' למען תהי' תורת ה' בפיך, כי התורה נק' לחם לכו לחמו בלחמי והיינו אחר היניקה, וכנודע מענין שתי הלחם שבשבועות שבאין אחר ז' שבועות דספה\"ע שהם בחי' יניקה הגדלת המדות כו', והתורה נתלבשה בגשמיות לברר בירורים להבדיל בין הטהור כו', ועי\"ז מתגדלים המוחין וכמו התינוק אינו יודע לקרות אבא עד שיטעום טעם דגן ואז מרחיקים מצואתו (כמ\"ש בשו\"ע או\"ח רס\"י פ\"א מהגמ' סוכה מ\"ב), כי אז שייך בירורים שנבדל הרע מהטוב ונדחה הפסולת לחוץ ומהמובחר יודע לקרות אבא כו', וכך עיקר התורה קיום המעשה סומוע\"ט שהוא בירורים ולכן הוקשה כל התורה לתפילין שהוא בחי' המשכת המוחין.\n<b>והנה</b> ענין ד' פרשיות דתש\"י ותש\"ר, כי תש\"י המוחין שיש בהעולמות (שז\"ע מארז\"ל חגיגה י\"ב א' הובא לעיל בעשרה דברים נבה\"ע בחכמה בתבונה ובדעת כו'), ותש\"ר המשכת מוחין מלמעלה ופי' כמשנ\"ת ע\"פ כי אל דעות שיש ב' דעות, מלמטה למעלה אנו אומרים יש מאין וזהו מוחין דתש\"י בחי' הדעת בממכ\"ע, כי תש\"י כנגד הלב לבא פליג לכל שייפין ממכ\"ע, אבל מלמעלה למטה למעלה היש ולמטה אין, וזהו בחי' וידעת היום וכו' בחי' ד\"ע בסוכ\"ע איך אני ה' לא שניתי, עמ\"ש בד\"ה וידעת היום כו' תקס\"ה (הוא וידעת הא' שבלק\"ת), ואח\"כ והשבות אל לבבך להמשיך ע\"י רצועות דתליין על לבא וכו', ולכן תש\"י לך לאות כי ואתה מחי' ע\"י התלבשות כנשמה בהגוף (כמארז\"ל ברכות ד\"י ע\"א מה הקב\"ה מלא כל העולם אף נשמה מלאה את כל הגוף), אבל תש\"ר בולט כי שם הוי' נקרא עליך ש' הוי' שמהוה שלא ע\"י התלבשות כלל אלא סוכ\"ע צוה ונבראו ממילא, ולזכרון בין עיניך כי יש ב' עינים ב' השגחות הנ\"ל ב' דעות הנ\"ל ושיהי' שוה מלמטלמ\"ע כמו מלמעלמ\"ט.\n<b>והנה</b> מתש\"י נמשך ק\"ש ומתש\"ר תפלה מעומד, והענין דהנה כתיב ויצוונו את כל החוקים ליראה היינו בחי' יראה עילאה שהיא תכלית כל המצות והתורה נק' אצלה תרעא לדרתא, וענין דרתא כמ\"ש איזה בית אשר תבנו לי שהוא בחי' שלמעלה מאתעדל\"ת כי אתעדל\"ת דתומ\"צ הוא המשכת בחי' אדם שעל הכסא רמ\"ח אברין דמלכא, אבל בחי' כי לא אדם הוא זהו מקיף עליון ונק' בית הסובב לבחי' אדם, ובחי' זו ע\"י ואל זה אביט אל עני כו', ואתחנן חנם כו' מאחר דכולא קמי' כל\"ח, ובחי' או\"מ זהו יראה עילאה הנ\"ל. וזהו בחי' תפלה שנק' בית תפלה כי תפלה לשון חיבור"],[2000560199,"שבהיכל ק\"ק היא בריאה לאחדים עם אצי' ולא התלבשות כשומע שכל חבירו כ\"א גילוי שם הוי' וזה נמשך ע\"י תש\"ר, וגם תפלה היחוד שנק' ג\"כ בית ויהי ביתך כבית פרץ, ויחוד זה נמשך ע\"י המשכת המוחין תחלה שהקטן אינו יכול להוליד כו', וזהו ענין תפלה כנגד קרבנות כי קרבנות אין נוהגין רק בזמן הבית לפי שהן גילוי בפועל ממש אש שלמעלה יורד כו' ושיהי' הגילוי למטה הוא ע\"י השראת מקיף עליון בחי' בית כמ\"ש ארוממך כו' ועי\"ז ואברכה שמך כו', וכן במזמור שיר חנוכת הבית ארוממך ועי\"ז דיליתני לידה וגילוי, ותפלה ג\"כ יש בה גילוי בפועל ממש רופא חולים כו' אך היינו ע\"י בית תפלה [ביטול] יר\"ע הנק' דרתא, וז\"ש בגמ' פ\"ג דברכות רב יהודה כי הוה שליף כו' שלהיות הגילוי בפועל ממש דוקא ע\"י יר\"ע מס\"נ, דהוי מסרי נפשייהו כמבואר שם ד\"ך ע\"א (ובסנהדרין דק\"ו ב' א\"ר גבי דואג ואחיתופל ג\"כ מארז\"ל הנ\"ל ומסיים אלא הקב\"ה ליבא בעי דכתי' וה' יראה ללבב (שמואל א' ו') והיינו בחי' רעו\"ד בחי' קוש\"י שבנפש, וזהו הדרתא), וכן בהמ\"ק בירושלים יראה שלם להשתחוות בבית כו'. וזהו תפילין דמארי עלמא מה כתיב בהו כי מי גוי גדול, פי' גדול המשכת המוחין דגדלות בהמדות שהם ג' נמשך לשם היו\"ד ע\"י הוא\"ו.\n<b>והנה</b> ענין הקב\"ה מניח תפילין בגמ' פ\"ק דברכות ד\"ו סע\"א, ובלקוטי הש\"ס מהאריז\"ל כ' הם תמיד נה\"י שעל ראש הז\"א הנק' סתם קוב\"ה, והתפילין דרש\"י הם הנה\"י דאימא שעל הז\"א, ותפילין דר\"ת הם הנה\"י דאבא שעל ראש ז\"א, ותפילין דשימושא רבא הם הנה\"י דאריך שעל ראש הז\"א וע\"ש בשער הכללים מע\"ח עכ\"ל. וקשה הא עכ\"פ אין חיוב על האדם רק זוג א' של תפילין למר כדאית לי' כו', ולפ\"ד האריז\"ל הרי הם באמת ג' מדרגות. ונראה דאף שתפילין שבאדם צריך להיות זוג א' והם התפילין דנה\"י דאימא לרש\"י, עכ\"ז ע\"י נמשכו ממילא ג\"כ נה\"י דאבא ונה\"י דא\"א, וא\"כ אין נפ\"מ למעשה ע\"ז למטה, וכה\"ג מבואר ע\"פ תספרו חמשים יום והרי אין סופרים רק מ\"ט ימים אלא שעי\"ז נמשך ממילא שער החמשים כמ\"ש בביאור ע\"פ אני ישנה כו', וכה\"ג נת' עוד בענין תפלת ערבית רשות בביאורי הזהר ס\"פ חיי שרה. ועיין מענין הקב\"ה מניח תפילין בת\"א פ' מקץ בביאור ע\"פ כי עמך"],[2000560200,"מקו\"ח דלפי' הב' קאי הקב\"ה על ז\"א ומניח תפילין היינו כנ\"ל, ולפי' הראשון הקב\"ה קאי על א\"א וא\"ס ומניח תפילין היינו שנמשך בחכמה ובינה כו'.\n<b>והנה</b> לפי פי' הראשון דשם מ\"ש בגמרא ומי משתבח הקב\"ה בישראל אין דכתי' את ה' האמרת כו', הענין יובן ע\"ד מ\"ש בד\"ה כי עמך מקו\"ח בענין השקיפה ממעון קדשך מן השמים וברך את עמך את ישראל, כי הנה כתיב רם כו' ומזה נמשך כו' שממית בידים תתפש כו' והנהגת העולמות הוא בבחי' שינה כו' ולכן כתיב ויקץ כישן כו' שיהי' גילוי אור א\"ס ב\"ה בחכמה וחסד בבחי' עצמותו ומהותו ית' כו' ואזי וברך את עמך כו' ואראה מראות כו' שע\"י המראה נראה הדבר שרואין בה לדבר גדול כו' ע\"ש. וזהו שבתפילין דמארי עלמא כתי' בפ' א' כי מי גוי גדול ומי גוי גדול, דברים סי' ד' פסוק ז\"ח, כי פרשה ראשונה זהו חכמה עילאה ובה ועל ידה ישראל נראים גוי גדול, משא\"כ כשהוא בבחי' רוממות כו', ולכן איכא למ\"ד לילה בחי' שינה הסתלקות לאו זמן תפילין הוא, ולמ\"ד זמן תפילין הוא כי ממשיכים מבחי' הנה לא ינום ולא יישן דהיינו מא\"א בחו\"ב, וכפי' הראשון דהקב\"ה היינו א\"א מניח תפילין כנ\"ל. ומזה יובן שמיד אחר יצ\"מ נאמרה מצות תפילין היינו בפ' קדש והי' כי יביאך, כי גלות מצרים נמשך מצד בחי' רם על כו' אסתלק לעילא כו' בחי' שינה כו', וביצ\"מ כתי' ויוציאנו ה' אלקינו או\"א שהלבישו לזרועות דא\"א, והוא בחי' ויקץ כישן כו' או לידה, אזי המצוה להניח תפילין שיהי' ג\"כ הקב\"ה מניח תפילין גילוי אור א\"ס בחכמה ואזי כי מי גוי גדול כו'. ומ\"ש ב\"פ גוי גדול י\"ל דגם הבחי' שנק' עשו בנו הגדול עיין בת\"א בד\"ה בשלח פרעה שהוא מצד עולם התהו שקדם לעולם התיקון ובחי' רב חסד נכלל ג\"כ ביעקב כו' ע\"ש, וזהו אתם עשיתוני חטיבה כו' שממשיכים בחי' אחד שהוא הגילוי בעולמות כמ\"ש בתו\"א בד\"ה וארא אל אברהם ולכן ואני אעשה כו'.\n<b>והנה</b> לפי' הב' דהקב\"ה היינו ז\"א ומניח תפילין המשכת המוחין היינו ג\"כ התחברות האו\"פ ממכ\"ע עם האו\"מ סוכ\"ע שנמשך גילוי אור א\"ס מאו\"א"],[2000560201,"וא\"א בז\"א, וזהו אחר יצ\"מ שהוא לידת ז\"א, ועיין בדרוש מיילדות העבריות, ועיין מענין פי' מוחין בביאור ע\"פ והנצח זו ירושלים, ועמ\"ש בביאור כי תשמע כו' לעשות הישר בעיני ה' כו' בפ' ראה בענין כי אל דעות ב' דעות יחו\"ע ויחו\"ת. והנה אף שז\"א נק' יחו\"ע אבל לגבי עתיק נק' ז\"א אלקים ויחו\"ת, וא\"כ מה שז\"א מניח תפילין הנה תש\"י זהו מה שנק' אצלינו יחו\"ע ולגבי עתיק נק' יחו\"ת, ותש\"ר דז\"א היינו מה שנמשך בו גילוי מוחין מיחו\"ע דעתיק, ועז\"נ כי הוי' ע\"ק הוא האלקים ז\"א כמ\"ש באד\"ר דקמ\"ג ע\"א, והוא ענין אסתכלותא דע\"ק בז\"א יאר ה' פניו כו', גם שם דק\"מ ע\"א ע\"פ חכמות בחוץ תרונה מבואר שתש\"ר הוא המשכה ממו\"ס במוחין דז\"א, וכ\"כ בואתחנן דרס\"ב ע\"א, וע' בזח\"א תולדות קמ\"א ב' שיצחק המשיך בחי' זו ע\"י הבארות שחפר, ויצא קס\"ב א' שיעקב המשיך זה ע\"י המקלות כו'.\n<b>והנה</b> בענין שבתפילין שאנו מניחים נאמר שמע ישראל כו' ה' אחד, ובתפילין דמארי עלמא נאמר שבח ישראל כי מי גוי גדול כו', הענין כי נש\"י נק' בנים לה' וברא כרעא בחי' רגל כביטול הרגל לגבי הראש, והקב\"ה נק' אבינו שבשמים אור אבא שבז\"א ונק' ישראל לי ראש. אך הקב\"ה שהוא ז\"א קורא לישראל לי ראש כי שרש נה\"י מהכתר בחי' וגם נצח ישראל לא ישקר כו', ועיין בביאור ע\"פ חגרה בעוז כו', ועיין בביאור ע\"פ אני דפ' ציצית בענין כשישראל עונין איש\"ר הקב\"ה מנענע בראשו כו' שנש\"י ממשיכים בחי' שמו הגדול וגלגלתא ומו\"ס, והיינו ע\"י ביטול היש והמשכה זו נמשך בז\"א, וזהו שבתפילין דז\"א נאמר שבח הנש\"י כו'. גם כמ\"ש בת\"א פ' מקץ סד\"ה רני ושמחי בענין עד שקראה אמי שע\"י מס\"נ בק\"ש ממשיכים נש\"י המוחין בז\"א כו', וע' מזה בד\"ה צאינה וראינה שזהו ענין שאו ידיכם קדש וברכו את ה' כי קדוש בוא\"ו היינו ז\"א והוא המשכת הארה להיות סוכ\"ע וממכ\"ע, אבל קדש הוא בחי' שלמעלה מגדר עלמין ולכן אין בו וא\"ו והמשכה, אך נש\"י ע\"י שאו ידיכם ביטול בשמע ישראל בשכמל\"ו ממשיכים מבחי' קדש בבחי' קדוש וזהו וברכו את הוי', וזהו פי' הקדוש ברוך הוא כו', וזהו שנאמר ויקרא לו אל"],[2000560202,"אלקי ישראל וישלח ל\"ג ך', ופרש\"י שרז\"ל דרשו שהקב\"ה קראו ליעקב אל והוא בגמ' פ\"ב דמגילה די\"ח ע\"א, ועיין ברבות ס\"פ ע\"ט, זח\"א קל\"ח א', ק\"נ ע\"א, רל\"ד ב', ח\"ב ס\"ו ב', ח\"ג קדושים פ\"ו, והמכוון י\"ל שיעקב ממשיך המוחין דאו\"א בז\"א וזהו שנק' אל שממשיך נהירו דאבא וגם מא\"א שנק' אל עליון כו', וזהו ענין והנורא אל עליון, פי' וא\"ו המשכה מבחי' אל עליון כו' כמ\"\"ש בד\"ה וידעת היום. והנה בענין כי מי גוי גדול עיין זח\"א וישלח קע\"ג ב', ויחי דרל\"ו סע\"ב, ח\"ג פנחס דרנ\"ח א' ושם נת' דתפילין דמארי עלמא הוא כתר וע\"ז מרמז הכ\"ף כי גו' כה' אלקינו כו', ועמ\"ש מענין כ\"ף בביאור ע\"פ יונתי גבי ולכי לך. אשר לו אלקים זח\"א בראשית ל\"א ב', כה' אלקינו ח\"ג פנחס דרמ\"ג א', ברבות בראשית פט\"ז גבי והנהר הגדול חדקל לפי שעלה והקיף את כל א\"י דכתי' בי' כי מי גוי גדול, לך לך פל\"ט גבי ואעשך לגוי גדול, ובנשא פי\"א ואעשך ע\"ש דהיינו ע\"י המילה, ואתחנן סי' רפ\"ט, מדרש איכה סי' ע\"ז ב', אסתר סי' קכ\"ז א'. אשריך ישראל ח\"ג קל\"ח סע\"ב, קנ\"ח א', צ\"ב א', ך\"ד סע\"ב. או הנסה הוא פרשה ג' מתפילין דמארי עלמא, והענין דאי' בב\"ר פמ\"ד מלבוא לקחת לו גוי כו' הם ע\"ב אותיות, וכ\"כ במדרש פ' דברים, ושם ע\"ב הוא בחסד. וצ\"ע דע\"פ קבלת האריז\"ל שם ע\"ב הוא בפ' והי' אם שמוע, ודוחק לומר דאצלו ית' כמו בתפילין דר\"ת. ויש ליישב שהרי הוא ענין התחלפות אור הגבורה בכלי החסד, אבל עיקר שם ע\"ב בחסד דהיינו פ' שמע רק למטה הוא דאחליפו דוכתייהו. ועיין מענין לקחת לו גוי בשמות רבה ס\"פ כ\"ב, ויקרא רבה ר\"פ כ\"ג אלו ואלו כו', ור\"ל שא\"כ הי' ההמשכה מלמעלה מהחכמה מצד שרש נש\"י ע\"ד אשר נשבעת לאבותינו מימי קדם. ולתתך עליון, הנה ארז\"ל שבת קנ\"ג ושמן על ראשך אל יחסר אלו תפילין, וכך הוא ענין השמן שנעשה עליון על כל המשקים כמ\"ש ברבות ר\"פ ואתה תצוה, ועמ\"ש מענין שמן בביאור ע\"פ מנורת זהב וע' זח\"ג ויקרא ד\"ז סע\"ב, אמור פ\"ח סע\"ב, בלק קפ\"ז א', ובגמ' ספ\"ק דמגלה ט\"ז ב' ויקר אלו תפילין עמ\"ש מענין יקר בהגהות ע\"פ וישב יעקב."],[2000560203,"<h3>[קיצור מד\"ה והי' לך לאות]</h3>\n<b>בס\"ד.</b>\n<b>בקדש</b> והי' נזכר יצ\"מ, ובשמע והא\"ש לא נזכר, יצ\"מ נמשל בפסוק בשם לידה, ביום הולדת אותך, יחזקאל ט\"ז ד', וכתי' יום צאתך כו' ימי חייך, יש בחי' לידה זו בכ\"י. יובן בהקדם ג' בחי' עיבור יניקה מוחין, ויבואר קודם איך ע\"י ההתבוננות במוח נולד אהוי\"ר, שלכאו' המוליד מוליד רק בדומה לו, הנה האדם שרשו מז\"א, שנאצל בסוד שורש רק ו\"ק, והמוחין באין בסוד תוס', שלכן ברה\"ע בו' ימים ו\"ק, ואעפ\"כ בע\"מ כי בראשית שת\"י בחוכמתא נמי מאמר בחי' מוחין שנמשכי' ומתלבשי' בז\"א, וז\"ע בעשרה דברים כו'.\n<b>וענין</b> המדות שרוצה איזה דבר והשכל הוא כלי להראות לו מה שירצה, ולכן הקטן ששכלו קטן רוצה בדברים קטנים, והגדול ששכלו גדול יותר רוצה דברים גדולים, והמשל לזה כמו אחד שמגיד לחבירו מקום ששם מטמון הנה הרצון להמטמון הי' אצלו גם קודם אבל בלי המגיד לא נתעורר הרצון לחפש המטמון, וכך השכל מראה מקום להמדות שעצם המדות הם להתאוות הדבר הטוב, אמנם האהבה היא בהעלם בבחי' שינה והשכל מעוררה שתתפש בדבר הטוב ותתפשט בה, ונמצא הגם כי המדות הם מהות בפ\"ע מ\"מ עיקר הולדתם הוא ע\"י המוחין, ולכן הקטן שהמוחין שלו קטנים מולידים מדות לדברים קטנים, ואין מתאווה לדברים גדולים הגם כי יש לו מדות, לפי ששכלו קטן מלהראות לו הטוב שבדברים הגדולי', כ\"א לדברים קטנים דוקא, כי ע\"פ שכלו יהולל איש.\n<b>והנה</b> השכל דנה\"ב מראה מקום למדותיו לתענוגי עוה\"ז, שזהו כמשל הקטן שמתאוה לדברים קטנים, הם עניני עוה\"ז ההוה ונפסד, אמנם הנה השכל שבנפש השכליות מראה מקום למדותיו לאהבת אלקותו ית', שזהו כמו שכל הגדול, ואז תוליד ותתפשט המדה באהבה עזה ע\"י התבוננו' השכל איך שכולא קמי' כלא חשיב, וכל האהבות זולתו ית' הוא כמו הקטן שמתאוה לחרסי האדמה, כי הוא ית' הוא הטוב העיקרי והנצחי, שעי\"ז תתלהט האהבה לבקשו כמטמונים, ולולי ידיעה זו לא הי' גילוי אהבה זו, הגם כי ישנה בהעלם בכאו\"א מישראל אהבה מוסתרת אך היא בבחי' שינה, והשכל מעוררה ומראה מקום שתתפש האהבה, רק שבמשל ידוע תחלה שיש לאהוב אוצר, ובנמשל השכל מודיע שאהבת השי\"ת ותומ\"צ זהו האוצר כמ\"ש כמטמונים תחפשנה, וז\"ע מוחין שהמדות מתנהלי' ע\"פ השכל, כמו שהמוח מנהיג גוף האדם, ולכן נק' חכמים עיני העדה, איזהו חכם הרואה כו', היפך הכסיל בחשך כו' החכם עיניו בראשו, וכמו השכל שמראה מקום להמדה כו', ומ\"מ ע\"י המדות מתעלה השכל וזהו האבות מדות חג\"ת הן המרכבה להגבי' בחי' אדם הוא בחי' מוחין להמשיך אוא\"ס בחכמה, כי שרש המדות גבוה יותר ז\"א בעתיקא ואו\"א רק במזלא, אך כ\"ז הוא כשהמדות בטלין להשכל ומתנהגי' ע\"פ הוראתו שלכן נק'"],[2000560204,"מרכבה כמשל המרכבה שבטלה להרוכב, ועי\"ז מעלה את הרוכב, וענין שהדעת כולל חו\"ג, כי חסד הוא התפשטות החיות, בחי' אהבה לדבק בה' ומה שאינו רוצה להיות בזה העולם זהו בחי' יראה גבורה, ומהדעת הם באים ביחד.\n<b>ועפ\"ז</b> יובן ענין בחי' עי\"מ, דהיינו כשהחו\"ג עדיין לא נולדו בהתגלות רק שהם עדיין בבחי' דעת ורוצים לידבק בה' בבחי' רצון ותעלומות לב, ולא בבחי' אהבה נגלית עדיין זהו בחי' עיבור, ובחי' יניקה היינו כשהאהבה היא בהתגלות רק החו\"ב עדיין אינו בהתגלות שכלו.\n<b>בס\"ד. (ש\"פ בשלח, רכ\"ז).\nביאור על בשלח פרעה שבת\"א.</b>"],[2000560205,"<h3>ויהי בשלח כו'</h3>\n<b></b>תהו ותיקון - ה\"פ - ביאור ד\"ה בשלח שבתו\"א\n[בשלח]\n<b>ויהי</b> בשלח פרעה את העם וגו', שהי' משלח פארות (כמו ותשלח פארת יחזקאל י\"ז ו') וענפים ועושה פרי למעלה, את העם כי פרעה הקריב שהקריב את העם לאביהם שבשמים, ולהבין זה למה דוקא ע\"י פרעה דוקא, צ\"ל תחלה ענין תהו ותיקון, שבתהו הי' ריבוי האור ומיעוט הכלים ולא היו הכלים יכולים לקבל ולסבול את האור ונשתברו ונפלו בשבירה והאורות נסתלקו למעלה.\n<b>ולהבין</b> ענין השבירה צ\"ל תחלה ענין הכלים, והנה איתא בע\"ח שיש פנימיות הכלים וחיצוניות הכלים ששרש נש\"י הוא מבחי' פנימיות הכלים ושרש המלאכים הוא מחיצוניות הכלים. ולהבין מהו נק' בשם פנימיות וחיצוניות, יובן זה ממה שאנו רואים למטה שיש ב' בחי' כלים פשוטי' ומקבלים, שיש בחי' כלי שמקבל בתוכו כמו כוס שמקבל בתוכו את היין וכדומה לזה, ויש ג\"כ בחי' כלי שאינו מקבל בתוכו כלום כמו הסכין אע\"פ שהוא ג\"כ כלי אבל אינו מקבל כלום רק שמתקן"],[2000560206,"המאכל שהוא בחי' שימוש רק בדרך מעבר בלבד. וזהו ג\"כ החילוק למעלה בין פנימיות הכלים וחיצוניות הכלים, ששרש נש\"י הוא מבחי' פנימיות דהיינו שמקבלים בחי' גילוי אוא\"ס ב\"ה בתוכם ממש, אבל מלאכים הם מחיצוניות הכלים שאינם רק בחי' שלוחי ההשפעה, אבל אינו נמשך להם לצורך עצמן כמשל הסכין שאינו מקבל בתוכו כלום, ולכן לא ניתנה התורה למלאכים אף שביקשו כמ\"ש תנה הודך על השמים, לפי שהתורה היא המשכה פנימיות וכמ\"ש ושכנתי בתוכם בתוכו לא נאמר אלא ושכנתי בתוכם בתוך פנימיותם ממש, והמלאכים אינם יכולים לקבל זה מפני ששרשן מחיצוניות הכלים, אבל נש\"י ששרשן מפנימיות הכלים שהם כלים לגילוי אוא\"ס ב\"ה ממש לכך ניתנה להם התורה.\nב) <b>ולהבין</b> זה בתוס' ביאור, יובן ממה שאנו רואים שהמוח הוא כלי לגילוי השכל שהשכל מלובש בו ממש, והיד הוא ג\"כ כלי לגילוי השכל שהרי ע\"י היד יוכל לכתוב את השכל, ואעפ\"כ אינם דומין זל\"ז כלל לפי שבמוח השכל מלובש בו ממש והמוח הוא כלי להשכל כמו הכוס שמקבל בתוכו את היין, אבל היד אע\"פ שכותב את השכל אבל עכ\"פ מ\"מ אינו מלובש השכל בהיד רק שהוא ממוצע שע\"י יומשך השכל לזולתו באותיות כדי שהכל יוכלו להבינו רק שהוא המשכה דרך מעבר בלבד ומ\"מ נק' בשם כלי לשכל, משום שעכ\"פ ע\"י היד נמשך הגילוי לזולתו ג\"כ, משא\"כ ע\"י הרגל לא יומשך כלל בחי' גילוי השכל. וזהו מ\"ש בע\"ח שחב\"ד הם בחי' פנימיות הכלים וחג\"ת הם בחי' אמצעים ונה\"י הם חיצוניות הכלים שהוא בחי' ראש תוך סוף כו' לפי שחב\"ד הוא כלי ממש לגילוי אוא\"ס ב\"ה כמ\"ש הוי' בחכמה, אבל חג\"ת המה בחי' מדות חסד דרועא ימינא גבורה דרועא שמאלא, שהם רק בחי' ממוצעי' שע\"י יומשך בהעולמות וכמ\"ש כי אמרתי עולם חסד יבנה, ושרש נש\"י נמשכו מבחי' חכמה (וכמ\"ש בנים אתם להוי' אלקיכם כמו שהבן נמשך ממוח האב וזהו ששרשן מפנימיות הכלים ששרשן מבחי' חכ' וכמ\"ש בתניא), אבל שרש המלאכים הוא רק מבחי' מדות ודבור, ולכן נקראו בשם חיות הקדש, וע\"כ לא ניתנה התורה להם לפי שאורייתא מחכ\"ע נפקת.\nג) <b>ומעתה</b> י\"ל ענין התהו שהי' ריבוי אור ומיעוט הכלים יובן עד\"מ כשהרב משפיע שכל לתלמיד, שכשהשכל גדול שלא לפי ערך המקבל צריך הרב להשפיל את השכל באותיות רבים ולהסבירו, אבל כשמשפיע לחכם כמותו א\"צ להשפיל אותו ולהלבישו באותיות רבים רק שמוסר ראשי פרקים ומזה יבין את כל השכל (וכמארז\"ל אלא א\"כ הי' חכם ומבין מדעתו) וזהו שהשכל גדול הוא ענין ריבוי האור, ומיעוט הכלי הוא אותיות מועטים."],[2000560207,"<b>ועוד</b> י\"ל ממ\"ש בלק\"ת פ' האזינו ע\"פ כנשר יעיר קנו שיחזקאל ראה את המרכבה פני ארי' פני שור כו' וזהו בזמן שאחר החורבן כשגלו לבבל שכינה עמהם (וגם משה בתחלת התגלות הקב\"ה אליו הי' ע\"י הסנה שהוא בחי' קוצים וברקנים שאז היו עדיין בקושי השעבוד כו') וכמ\"ש ואני בתוך הגולה לפיכך ראה ההתלבשות בבחי' פני ארי' ובחי' פני שור כו', כי בזמן שהי' בהמ\"ק קיים הי' גילוי השכינה במדרגה היותר גבוה ונעלה וכמו שהי' ראשית הגילוי לכל ישראל במ\"ת דכתי' פנים בפנים דיבר הוי' עמכם, פי' פב\"פ בלי שום אמצעות והתלבשות כלל (וע' מענין פב\"פ ומענין פא\"פ בד\"ה ראה) ולכן כתיב וכל העם רואים את הקולות וארז\"ל רואים את הנשמע ושומעין את הנראה, שהי' גילוי אלקות מבלי שום התחלקות ריבוי המדרגות רק שהיו רואין גילוי כללות החיות ושפע אלקי ואין שום פירוד וחילוק ח\"ו בין ראי' ושמיעה, והיינו שהי' מאיר רבוי האור והי' העין שהיא כלי לראי' בלבד יכולה לקבל ג\"כ כח השמיעה והאזן שהיא כלי לשמיעה בלבד יכולה לקבל גם כח הראי', וכל זמן שבהמ\"ק קיים היו הנשמות במעלה עליונה והי' כח השגתם בגילוי כללות החיות מבלי שום אמצעית כלל, אבל כשגלו לבבל הנה גם גילוי השכינה אז הוא ע\"י ירידה בבחי' התחלקות רבוי המדרגות בבחי' פני ארי' ופני שור שבמרכבה, ראי' בפ\"ע ושמיעה בפ\"ע שנתמעט האור כביכול ונמשך בכלים מכלים שונים בריבוי התחלקות, פני ארי' ופני שור. וזהו מ\"ש בזהר שיש בחי' מארי דעיינין ומארי דאודנין, ובעבודה ז\"ע שתים לפניה, יוצר משרתים ואשר משרתיו כו' והאופני' וחיות הקדש ברעש גדול שהאהוי\"ר נמשך לנש\"י ע\"י המלאכים, שע\"י ההתבוננות באריכות בברכות ק\"ש עי\"ז נמשך בחי' אהוי\"ר בנש\"י, משא\"כ בימי משה הי' נמשך ע\"י השכינה בעצמה שהרי גם המלאך לא רצה לקבל כמ\"ש אם אין פניך הולכים, ולכן אמר ליהושע עתה באתי. אבל אח\"כ בימי יחזקאל כיון שהוצרכו לקבל ע\"י פני ארי' פני שור, ע\"כ גם בעבודה לבוא לבחי' אחד ואהבת בק\"ש הוא ע\"י שתים לפניה ששם נא' מענין המלאכים איך שעומדים ביראה, ועי\"ז נמשך להאדם ג\"כ אהוי\"ר, וממילא מתעלים המלאכים ג\"כ עי\"ז כנודע מענין אכלתי יערי עם דבשי, יערי הם"],[2000560208,"המלאכים שע\"י מס\"נ בק\"ש באחד ואהבת בכל לבבך ובכל נפשך דהיינו בבחי' אליך ה' נפשי אשא הנה הנשמה עולה למקור חוצבה שהיא בשרשה הגבה למעלה יותר וכנ\"ל מתעלים המלאכים ג\"כ עי\"ז כי מאחר שמהם קיבלה אהבתם ויראתם להעלות לה' אחד לאהבה בכל נפשך יהיו גם הם עולים בסולם ונכללים בבחי' יחוד העליון ב\"ה ולאשתאבא בגופא דמלכא, וזהו והנה מלאכי אלקים עולים כו'.\n<b>ונחזור</b> לענינינו שמזה יובן ענין ההפרש בין תהו לתיקון שבתהו הי' רבוי האור ומיעוט הכלי היינו במעט התלבשות, משא\"כ בתיקון הוא מיעוט האור ורבוי הכלים וכמו ע\"ד ההתלבשות הנ\"ל, וע' בד\"ה אם בחקתי בהביאור (ך\"ו) שענין ריבוי האור שלא לבד שהאור הי' ברבוי כ\"א שהי' בא\"א מכמו אורות דתיקון יעו\"ש.\nד) <b>והנה</b> בתהו לפי שהי' רבוי האור ומיעוט הכלי לא היו הכלים יכולים לסבול את רבוי האור כ\"כ ונשתברו הכלים ונפלו בשבירה, ולהבין ענין השבירה י\"ל עד\"מ ממה שאנו רואים כשהרב משפיע כמו שהוא אצל הרב בגילוי ובהרחבה, לכך מצד גודל עומק המושג וקוטן שכל המשיג עי\"ז נתבלבל אצלו האותיות והשכל ואינו משיג כלום, אבל אם הי' שונה אליו בדרך קצרה והי' מצמצם שכלו אליו עי\"ז הי' יכול לכל הפחות לקבל את הפסק דין ותוכן המכוון אם הוא כשר כו' (וכמשארז\"ל לעולם ישנה אדם לתלמידו בדרך קצרה) אבל ע\"י שהשפיע לו ברבוי ובהשפעה גדולה מבלי צמצום עי\"ז מתפרדים אצלו האותיות ואפי' הפס\"ד אינו יודע, וזהו ענין השבירה, דהיינו שמתפרדין האותיות כי בהאותיות מלובש השכל כמו אותיות ב\"ש והי' העולם שיש בהן השכלה גדולה ונפלאה איך שבאמירה אחת נברא העולם, אבל כשמתפרדין האותיות נאבד השכלה. וזהו ע\"ד שנשברו לוחות הראשונות לפי שהי' בהם גילוי גדול מאד נעלה והיו אורות מרובין וכלים מועטין, שבתר\"ך אותיות שבעשה\"ד הי' כלול כל תושב\"כ ע\"כ נשברו. זאת ועוד זאת שאם לא רק כלים מועטים לא הי' נשברים מחמת זה רק שחטא העגל גרם להם שישברו כמו שמצינו בלוחות אחרונות שהי' בהם גילוי יותר כדאיתא במדרש פ' תשא ע\"פ ויגד לך תעלומות חכמה כפלים לתושי' שלוחות אחרונות כוללים הלכות ואגדות ומדרש כו', ואעפ\"כ לא נשברו, אלא ע\"כ הוצרכנו לומר שנשברו מחמת חטא העגל ומ\"מ גם מחמת החטא בעצמו ג\"כ לא היו נשברים וזו\"ז גורם כו' (וע' בביאור ההפרש בין לוחות ראשונות ולוחות אחרונות, והוא ביאור כי אתה נרי בענין והוי' יגיה חשכי דתרי\"ג), וכמ\"כ כאן אפ\"ל מחמת שהי' בהם ריבוי האור לא היו נשברים רק מחמת שהיו נקודות זת\"ז וכמ\"ש וימלוך וימת לפי שהיו בבחי' יש ענפים מתפרדים בחי' יש ודברים נפרדים ולא הי' בהם התכללות ע\"כ נשברו ונפלו למטה, והיינו שהכלים"],[2000560209,"שהם האותיות שהיו מתחלה כלים לגילוי אלקות נתפרדו ונעשו חיות לדבר גשמי להחיות אותו.\n<b>ולכן</b> הי' להם לפרעה ולעבדיו עושר וכבוד שלא ע\"י חשבון ומעשה ודעת, כי יניקתם מחיות אלקי שנפל בקליפות ע\"י שבה\"כ (וזה ממקום שיותר גבוה) והוא מוסתר ומכוסה אצלם וכמ\"ש וימנע מרשעים אורם שאינו מאיר אצלם בהתגלות כ\"א העלם והסתר בחשך כפול ומכופל, עד שמכחשים בהוי' אמר נבל בלבו אין כו', ונראים ליש ודבר בפ\"ע. משא\"כ בסט' דקדושה מקבלים חיות מגילוי אור פני הוי' והוא מתגלה אצלם אף שהוא ע\"י השתלשלות ירידת המדרגות בע\"ס הקדושות שהן הן מדותיו של הקב\"ה ית\"ש שע\"י דוקא יושפע החיות לנבראים לפי שהם כלים לגילוי אלקותו ית\"ש לפי שבתיקון הי' מיעוט האור וריבוי הכלים והיינו שכדי שיהי' בחי' כלי לגילוי אוא\"ס ב\"ה שעז\"נ השמים ושמי השמים לא יכלכלוך אפי' כלי לכלי לא יכלכלוך, לכן הוצרך להיות צמצום האור כדי שיוכלו הכלים דתיקון לקבל בחי' גילוי כו' וזהו שחכ' נק' בחי' יו\"ד שהיא בחי' צמצום שחכ' מקבל מבחי' צמצום דוקא.\nה) <b>והנה</b> כתי' וזרעתיה לי בארץ דוקא שישראל נזרעו למטה דוקא וכמ\"ש אור זרוע לצדיק וכלום אדם זורע כור אלא כדי להוציא כמה כורין ומהו הצמיחה היינו ע\"י תומ\"צ, שהמצות נתלבשו בגשמי' דוקא כמו ציצית מצמר גשמי דוקא ותפילין מקלף גשמי ששרשן מעולם התהו שנפלו בשבירה וע\"י שמבררין אותם עי\"ז נתעלים לשרשן הקדום לתהו ששם ריבוי האור וממשיכין ע\"י בתיקון ג\"כ ריבוי האור ואעפ\"כ יוכלו הכלים לסובלו לפי שהם בחי' ביטול והתכללות כמ\"ש למעלה שהשבירה הי' בתהו מחמת שהיו נקודות זת\"ז.\n<b>(ועוי\"ל</b> איך יכולים לקבל כלים דתיקון בחי' אורות דתהו שהמה בלתי בע\"ג כלל וכלל בכלים דתיקון שהמה מקור לבע\"ג, וצריך לומר שהוא ע\"ד מ\"ש המשל ופחד עמו עושה שלום במרומיו מיכאל שר של מים גבריאל שר של אש ואינם מכבים זא\"ז מפני שמאיר עליהם הארה יותר גבוה מבחי' המשל ופחד, כמשל שני שרים שהמה מנגדים זל\"ז כשבאים לפני המלך מחמת אימת המלכות המה עושים שלום כאילו לא היו שונאים זא\"ז מעולם, וזהו מחמת אימת המלכות, וכמ\"כ מחמת המשל ופחד עושים שלום כו'. וכמו\"כ צ\"ל כאן דכשצריך להיות התחברות כלים דתיקון בחי' שרש ומקור הגבול עם אורות דתהו בבע\"ג צריך להאיר הארה יותר גבוה משניהם אף מבחי' אורות דתהו)."],[2000560210,"<b>וזהו</b> ויהי בשלח שהוא משלח פארות כו' ופרעה הקריב לפי שע\"י פרעה זכו לתשובה והמשיכו אורות דתהו שהם בלי גבול ממש. וזהו צדקת פרזונו בישראל לשון פרזות ע\"ש מ\"ש פרזות תשב ירושלים מאין חומה מרוב אדם כו', והיינו כי חומה הוא מקיף לעיר ומגביל את העיר ונק' בחי' צמצום שמצמצם, אבל פרזות תשב לע\"ל שהיא בחי' גילוי אור א\"ס ב\"ה מבלי צמצום כמו שהי' בתהו בבחי' ריבוי האור כו'."],[2000560211,"<h3>[ולא נחם אלקים]</h3>\n<b>ולא</b> נחם אלקי' דרך ארץ פלשתים להיות כי כמה מיני עליות יש, הא' נקודה תחת יסוד כמ\"ש ותפול לפני רגליו, והיא עלי' ראשונה שלא יהי' כזיווג אחור באחור, והוא ראשית ההכנה להיות זיווג פב\"פ, ואח\"כ עלי' שנית לקבלתה מחג\"ת, עד שתתעלה להיות פב\"פ במ\"ת, וזהו שלא נחם אלקי' דרך ארץ פלשתים שהוא שמחה וטוב לבב שהי' במ\"ת בחי' פב\"פ מיד, אלא ויסב את העם דרך המדבר ים סוף פי' שתהי' תחלה בחי' נקודה תחת היסוד והו\"ע הבכי' ותפול לפני רגליו ותבך עד שתעלה להיות פב\"פ, והטעם הוא לצורך הבירורי' שמבררת בבכייתה, משא\"כ לע\"ל כי עין בעין יראו מיד כי תהי' אור הלבנה כו'.\n<b>ולא</b> נחם כו', כי פלשתים שמחה וצ\"ל תחלה נקודה תחת היסוד, כי מיש אי אפשר להיות יש כ\"א שבא בתחלה בבחי' אין, וכמו נהר דינור ע' בת\"א ד\"ה מקץ הא' שגם הצדיקים כו', רק לע\"ל כתיב שלח אורך ואמיתך המה ינחוני (תלים מ\"ג ב') היינו שלח אורך ממש כמ\"ש כי עמך מקור חיים באורך נראה אור, ואז ינחוני ע\"ד ה' בדד ינחנו. אך לגילוי אור זה נאמר הנני שולח לכם את אליהו, פי' הנני שולח לכם אתעדל\"ת שלמעלה מבחי' בשלח פרעה, והשיב לב אבות ג\"ר על בנים ז\"ת כי עכשיו רק גילוי ז\"ת ולכן ניתן רק ז' עממין, אבל לע\"ל כל העשר"],[2000560212,"עממין. והיינו פי' הפסוק היינו שלא נחם אלקים ולא נהגם דרך בחי' ומדריגת פלשתים דקדושה, היינו שמיד בצאתם ממצרים שהוא בחי' סור מרע והיציאה ממצרים וגבולים של העוה\"ז שהאדם קשור בהם שכשיוצא מבחי' זו יבא מיד לבחי' השמחה בה' בפילוש ובגלוי כו' שלא זו הדרך, כי צריך להיות כמה מדרגות בנתיים שהרי נאמר שמחו צדיקים בה' צדיקים דייקא, וביאור הטעם כי קרוב הוא ליפול מזה כי פן בראותם מלחמה שהוא ענין הנסיון שיבא להאדם לא יוכל לעמוד בקשרי המלחמה (וכשעומד בנסיון עי\"ז מעלה הניצוץ, משא\"כ כשלא יוכל לעמוד ח\"ו) ויסוג אחור ושבו מצרימה (ועמ\"ש בד\"ה אחרי ה' אלקיכם תלכו אחרי דייקא ע\"ד כי מנסה ה' כו', וזהו לכתך אחרי במדבר), אלא הדרך הנכון כמ\"ש תחת אשר לא עבדת את ה' אלקיך בשמחה שתהא השמחה ע\"י עבודה (כמ\"ש בד\"ה תחת אשר לא עבדת).\n<b>והענין</b> שיש להבין במ\"ש תחת אשר לא עבדת כו' בשמחה כי הלא זהו ממדרגת צדיקים שנאמר שמחו צדיקים בה' בתלים ססי' צ\"ז ואיך יגיע כל אדם לזה. והענין שיש ב' מיני אהבות, הא' שנעשי' מאלי' ע\"י התבוננות בה' אחד, והיא כשלהבת העולה מאליה ובוערת ברשפי אש ואין בה שום מבוקש (אגה\"ק סי' י\"ח בד\"ה כתיב מה יפית), והוא ענין אהבה בתענוגי' שמתענג על ה' עונג נפלא בשמחה רבה ועצומה שמחת הנפש וכלותה בטעמה כי טוב ה' ונעים כו', וע\"ז כתיב שמחו צדיקי' בה' ולא כל אדם זוכה לזה. והשנית היא אהבה ותאוה שהנפש מתאוה וחפצה לדבקה בה' וזהו יש בכל נפש מישראל ורע לה מאד להתרחק ממנו ח\"ו וע\"ז נאמר ואהבת את הוי' שיהי' אלקיך, אך איך הדרך לדבקה בו והרי לית מחשבה תפיסא בי' כלל ואין דרך לדבקה בו כ\"א ע\"י התורה ומצות שהם הדברים אשר אנכי מי שאנכי מצוך כו', ואי לזאת יהי' השמחה גדולה בעסק התורה והמצות ועז\"נ פקודי ה' ישרים משמחי לב, וכמ\"ש בד\"ה את קרבני לחמי ובד\"ה אוסרי לגפן. ועז\"נ תחת אשר לא עבדת את ה' בשמחה ובטוב לבב מרוב כל שצריך להיות השמחה בעבודה דהיינו בתומ\"צ, שעי\"ז מרוה צמאונו היינו לאחר שקיבל עליו עול מ\"ש וצמאה נפשו לאלקי' אזי ע\"י קיום המצות מרוה צמאונו וממשיך גילוי אוא\"ס בנפשו וזה יכול כל אדם להגיע. אבל השמחה בה' מצד מהו\"ע בלי שום מבוקש זהו רק מדרגת הצדיקים כו'."],[2000560213,"<b>ובהיות</b> כן שהשמחה צריך להיות בעבודת התורה והמצות דוקא (בד\"ה ה' לי בעוזרי) הנה היא מלובשת במעשה המצות וכמ\"ש וירא אלקי' את האור כי טוב וארז\"ל כי טוב לגנוז כו', כי אורה ושמחה ענין א' הוא כמ\"ש בת\"א בד\"ה ואתה תצוה, וצריך להיות גנוז אור השמחה במעשה המצות כו' דהיינו ע\"ד התלבשות האור בהכלי למעלה, וגם כי ע\"י גניזה של השמחה בהעבודה היא בבחי' אין בלי הרגש היש כו', כי העבודה היינו שהוא בבחי' עבד וקבלת עול ומזה עצמו הוא שמח שזכה להיות עבד למי שאמר והי' העולם ואין עוד מלבדו כו', וא\"כ בחי' זו הוא היפך פלשתים דקדושה ג\"כ שהוא השמחה בדביקות בה' בפילוש ובגילוי, והרי צריך להיות כי טוב לגנוז האור ושמחה בתוך העבודה היפך גילוי השמחה בעצמה כו', שמבחי' השמחה בעצמה לבד בלי העבודה יוכל לבא לבחי' יש כו', ומזה יוכל להיות נמשך יניקה לשמחה של הוללות הנק' פלשתים דקליפה, ע\"ד שמפרעה דקדושה לפי שהוא עלמא דאתגליא מלשון ופרע את ראש האשה נמשך יניקה לפרעה דקליפה.\n<b>והנה</b> לא מיבעיא במדת כל אדם שצריך להיות השמחה רק בעבודה כנ\"ל, אלא אפי' בצדיקים שנאמר שמחו צדיקים בה' אעפ\"כ א\"צ להיות בבחי' פלשתים [דקדושה] בהתגלות השמחה בפילוש כמבוי המפולש לרה\"ר, כי מזה יש יניקה לחיצונים בחי' רה\"ר וטורי דפרודא, כמ\"ש בנח וישכר ויתגל בתוך אהלה, וכתי' לא יחפוץ כסיל בתבונה כ\"א בהתגלות לבו במשלי סי' י\"ח ב', ולכן אין הברכה שורה אלא בדבר הסמוי מן העין הוא בחי' חסדים המכוסים שהשמחה מכוסה בתוך ההתבוננו' אשר חו\"ב הם תרין ריעין וחכמה הוא בחי' אין כו' ע\"כ אין מזה יניקה כו', משא\"כ בבחי' התגלות לבו הוא שרש עה\"ד טו\"ר שסחטה לו ענבים היינו גילוי יין המשמח, וצריך להיות יין המשומר בענביו שהרי גנוז תוך הכלים, וזהו ענין וכל הלבבות ייראוך וכל קרב וכליות יזמרו לשמך וכמ\"ש וגילו ברעדה שהשמחה והזמרה הוא בקרב וכליות ומבחוץ תכסה היראה כו', וזהו ג\"כ היפך בחי' פלשתים דקדושה ג\"כ שהוא הפילוש והגילוי, וזהו שהוכיחה מיכל את דוד בש\"ב סי' ך', מדוע כו' בהגלות נגלות כאחד הרקים כו' שאין זו הדרך כו', אך באמת שם שאני שהשמחה הי' בעבודה רבה בהעלותו את הארון כו'.\n<span data-k=\"ks\"><b>קיצור.</b> ולא נחם אלקים ולא נהגם שמיד בצאתם ממצרים יבואו לבחי' השמחה בפילוש, כי קרוב ליפול ח\"ו מזה כשיבואו לידי נסיון וצריך תחלה להרגיל א\"ע לילך אחרי הוי' שזהו בחי' המדבר, וצ\"ל עבדת בשמחה שהשמחה תהא גנוזה בעבודה שיש ב' מיני אהבות, א' שמחה בלי מבוקש, ב' שמחה ע\"י תומ\"צ, שמרוה צמאונו האור כי טוב לגנוז, ואפי' בצדיקים צ\"ל החסדים מכוסים ע\"ד וכל הלבבות ייראוך וכל קרב וכליות יזמרו לשמך.</span>"],[2000560214,"<b>וזהו</b> ויסב אלקים את העם דרך המדבר ים סוף (בד\"ה זכור את אשר עשה לך עמלק בת\"א פ' תצוה) דהיינו כמ\"ש לכתך אחרי במדבר שבחי' המדבר הוא בחי' אחרי ה', וע\"ז נאמר אחרי ה' ילכו כארי' ישאג והוא בחי' ומדרגת אתכפיא להיות מוח שליט על הלב, ועמ\"ש בד\"ה אחרי הוי' אלקיכם תלכו כו'. ועוד זאת כמ\"ש במדבר סיני באהל מועד, בחי' מדבר הוא כמ\"ש ומדברך נאוה מלשון דבור, כי הנה דבר ה' זו גילוי שכינה וכשמתלבשת בבי\"ע נק' מדבר בתוס' אות מ' פתוחה, לפי שאז יש פתח ומבוא לחיצוני' הם הקליפות וסט\"א לינק ולקבל חיות ממנה כו', וכן בניצוץ האלקי שבנפש שאף שכבר יצא ממצרים להיות סומ\"ר עדיין קשור בתאוות היתר מחמת תאוות נה\"ב מלבושי נוגה, וצ\"ל עליי' זו ג\"כ בבחי' מדבר דהיינו ע\"י דבור התפלה ברשפי אש וצמאון ע\"י שישים אל לבו שאפי' כל העולמות עליונים מרכ\"ד כו' הם בחי' מדבר ושממון לגבי אור א\"ס ב\"ה וכמ\"ש לעיל שבחי' מדבר נק' לכתך אחרי כו' ועי\"ז מברר ומהפך חשוכא לנהורא, וזהו ומדברך נאוה. וכמ\"ש סד\"ה כנשר יעיר קנו בענין ימצאהו בארץ מדבר יצרנהו כאישון עינו, כאישון עינו הוא השחור שבעין ובו דוקא נמשך ומתגלה כח הראי', כך עי\"ז החשך שמחשיך את האדם במרירות לבו ונפשו בהיותו בעיניו בבחי' מדבר ושממון נגד אוא\"ס ב\"ה, עי\"ז יבא וימשיך גילוי רצה\"ע, וז\"ש מי זאת עולה מן המדבר עילויה מן המדבר, וע' מזה בזח\"ב תצוה דקפ\"ז סע\"א. ועמ\"ש עוד מענין דרך המדבר בד\"ה אלה מסעי בנ\"י, וגם כי ע\"י דרך המדבר הוא מברר מה שנפל משבה\"כ בעולם התהו שנק' מדבר ושממה, ועי\"ז יבוא לבחי' המדבר הגדול והנורא שהוא עולם התהו בשרשו שנק' מדבר אשר לא ישב אדם שם, ר\"ל למעלה מבחי' ז\"א הנק' אדם, כי תהו היינו שאינו מושג, ובע\"ח שמ\"א פ\"ג בשם הרמב\"ן תהו בחי' כתר כו', ונמצא בחי' זו דדרך המדבר זהו ע\"ד מ\"ש לעיל באות הקדום והשנית היא אהבה ותאוה שהנפש מתאוה וחפיצה כו', ועי\"ז יבא אח\"כ לבחי' פב\"פ, והיינו כמ\"ש בע\"ח שלהיות עליות כנס\"י מתחלה היא אחור באחור ואח\"כ נעשית נקודה תחת היסוד, והוא ראשית ההכנה לבא לזיווג פב\"פ, ואח\"כ עליי' שני' שנגדלת נגד חג\"ת שלו, עד שאח\"כ תגדל כ\"כ כנגד חב\"ד דהיינו עלייתה בשעת מ\"ת פב\"פ דיבר ה', וזהו ענין רבבה כצמח השדה נתתיך ותרבי ותגדלי, ועמ\"ש מזה ע\"פ מאמר הזח\"ג במדבר דק\"ך ע\"ב בענין ובא לו לקרן בחי' קרן זהו היותה תחלה בבחי' ביטול נקודה תחת היסוד, וזהו ולא נחם אלקים דרך ארץ פלשתים שהוא ענין שמחה וטוב לבב בחי' פב\"פ, אלא ויסב את העם דרך המדבר ים סוף, דהיינו כסדר הנ\"ל, שמתחלה צ\"ל לכתך אחרי דוקא ואח\"כ תהי' בחי' נקודה תחת היסוד שהוא ענין יראה, וכענין"],[2000560215,"ותפול לפני רגליו ותבך עד שתתעלה לבחי' פב\"פ, והטעם הוא לצורך הבירורים שמבררת עי\"ז כו', ועמ\"ש עוד מענין זה עפ\"י מאמר הזח\"ג פ' בלק דקצ\"א ע\"א ע\"פ שחורה אני ונאוה, ולכן לע\"ל צדקת פרזונו, פרזות תשב, גילוי אוא\"ס מבלי צמצום, ואז יותן גם פלשתים שהוא מן הג' שלא ניתנו, רק לע\"ל יהי' עלי עשור כו'."],[2000560216,"<h3>זכור את יום השבת כו'</h3>\n<b></b><b>בס\"ד. (ש\"פ יתרו, רכ\"ז).</b>\nזכור ושמור - ה\"פ\n[יתרו]\n<b>זכור</b> את יום השבת לקדשו, ששת ימים תעבוד כו' ויום השביעי שבת לה' אלקיך, ובדברות האחרונות נאמר שמור את יום השבת וארז\"ל בר\"ה דך\"ז א', שבועות ד\"ך ע\"ב, זכור ושמור בדבור א' נאמרו, מה שאין הפה יכול לדבר ואין האוזן יכול לשמוע, וכן מחללי' כו' וביום השבת שני כבשים ג\"כ בדבור אחד, כמו שפי' רש\"י ז\"ל והוא מהילקוט רמז רצ\"ה שהביא מהמכילתא, וצ\"ל ענין דבור אחד שיש בשבת. וגם צ\"ל ענין זכור וענין שמור וענין ששת ימים תעבוד, מהו הציווי על עבודה בששת ימי החול כו'. וגם צ\"ל ענין לקדשו הלא שבת הוא מקדשא וקיימא משי\"ב וכמ\"ש (תשא ל\"ד י\"ד) ושמרתם את השבת כי קדש היא, דבשלמא קדושת יו\"ט תלוי בישראל שלכך אומרים מקדש ישראל והזמנים מתחלה ישראל ואח\"כ הזמנים משום דישראל אינהו דקדשינהו לזמנים. ובזה יתורץ מה שהקשה הפנ\"י על מה שארז\"ל בך\"ה באלול נברא העולם א\"כ יום ששי למע\"ב הי' ר\"ה ואיך עשה מלאכה בר\"ה שמאמר תוצא הארץ נפש חי' ונעשה אדם הי' ביום ששי שהוא ר\"ה ויו\"ט אסור בעשיית מלאכה כמו שבת, אך לפ\"ז לא יוקשה דקדושת יו\"ט תלוי בישראל שישראל אינהו דקדשינהו לזמנים וא\"כ קודם בריאת אדה\"ר לא הי' קדושת"],[2000560217,"יו\"ט כלל ולכן לאחר מאמר נעשה אדם שנברא אדה\"ר לא הי' מאמר עוד, אבל שבת מיקדשא וקיימא משי\"ב, וא\"כ מהו הציווי זכור את יום השבת לקדשו. וגם צ\"ל מ\"ש בת\"ז תיקון יו\"ד דך\"ב א' ותיקון ס\"ט דקי\"ו א', ובהקדמת ת\"ז ד\"ד ע\"ב וד\"י ודס\"ז, ע\"פ זה שמי לעולם וזה זכרי לדור דור שמי עם י\"ה שס\"ה ל\"ת וזכרי עם ו\"ה רמ\"ח מ\"ע, הרי כי ל\"ת הם בחי' י\"ה ומ\"ע בחי' ו\"ה, ובמ\"א נת' שזכור עם י\"ה גימ' רמ\"ח מ\"ע הרי מ\"ע ג\"כ בי\"ה.\n<b>ויובן</b> כ\"ז בהקדם ענין השבת שבו שבת מכל מלאכתו, דהנה ארז\"ל ע\"פ ממצוא חפצך ודבר דבר, דבור אסור הרהור מותר לפי שבריאת העולם הי' מבחי' דבור, לכן דבור אסור כי בו שבת אבל הרהור מותר שהעולם לא נברא במחשבה, וא\"כ לפ\"ז הי' צ\"ל דבור אסור מדאורייתא ולא מצינו שאסור מדאורייתא כ\"א מעשה כמו הזורע והחורש שהם מלאכות בבחי' מעשה, אבל דבור מדאורייתא מותר רק שמדרבנן דבור אסור הרהור מותר ואסמכוהו אקרא. אך הענין דהנה איתא בכמה מדרשי' שדיבורו של הקב\"ה חשיב מעשה ולכן עיקר האיסור דאורייתא בשבת הוא עשיית מלאכה מצד כי בו שבת, אבל דבור מותר מדאורייתא מפני שמדבור האדם לא יתהווה כלום כ\"א דיבורו של הקב\"ה חשיב מעשה כו', ומדרבנן דבור ג\"כ אסור מפני שעכ\"פ בריאת העולם הי' ע\"י דבור ובשבת שבת כו', לכן גם באדם הדיבור אסור מדרבנן. אבל הרהור מותר גם מדרבנן לפי שבריאת העולם עלמא דאתגליא לא הי' מבחי' מח', כ\"א מבחי' דבור דוקא שדבורו של הקב\"ה חשיב מעשה. דהנה כדי"],[2000560218,"שיתהווה העולם שהוא בחי' גבול מהארץ לרקיע מהלך ת\"ק שנה שהוא בחי' גבול מאתו ית' הבלתי בע\"ג הוצרך להיות ע\"י רבוי צמצומים דוקא כי גבול לגבי בבע\"ג אין ערוך כלל, לזה הי' ע\"י צמצום הדבור דוקא שחשיב מעשה שהוא בחי' צמצום והשפלה, וכמשל האדם בעת שעושה איזה כלי הנה בעת שעושה מושפלים שכלו ומדותיו בעשיית הכלי, כך עד\"מ למעלה כביכול שכדי שיהי' בריאת העולם הי' בחי' השפלה בדבור בבחי' צמצום בעשרה מאמרות פרטיים כו', ולכן בכל מע\"ב לא נאמר רק שם אלקים עד לאחר שבת נאמר ה' אלקים, של\"ב פעמים אלקים הם כנגד ל\"ב נתיבות חכ' ששם אלקים הוא מדת הצמצום לצמצם בחי' החכ' כו' עד שיהי' בריאת העולם, ושבת הוא כי בו שבת כאדם ששובת ממלאכתו שהשכל והמדות שנשפלו להתלבש בדבור ובמעשה עולים למהותן ועצמותן, כמו\"כ למעלה ענין השבת הוא בחי' העלאה מלמטלמ\"ע.\n<b>וזהו</b> מ\"ש והנה טוב מאד ויכולו השמים, פי' טוב מאד הוא בחי' בע\"ת כידוע דטוב הוא יצ\"ט ומאד הוא יצה\"ר כשנהפך לטוב ע\"י התשובה וכידוע ענין התשובה שהוא מדריגה גבוה שבמקום שבע\"ת עומדין צדיקים גמורי' אינם יכולים לעמוד, ועד\"ז הוא ענין השבת שהוא אותיות תשב בחי' העלאה מלמטלמ\"ע שהוא בחי' עליות החיות שירד בשי\"ב בבחי' ירידה, בשבת הוא עולה בבחי' עליית העולמות למהותו ועצמותו ית' כו', וזהו בחי' שבת דמיקדשא וקיימא שהוא בחי' עליות הכח הנמשך מחכ' לבחי' דבור שדבורו של הקב\"ה חשיב מעשה לבחי' עצמיות החכ' כו' כנ\"ל במשל שלאחר גמר המלאכה חוזרין המוחין למהותן ועצמותן כו', וזהו בחי' שבת דמיקדשא וקיימא שהעלי' היא ממילא כי בו שבת כו', ובד\"כ עלי' זו הוא מבחי' עשי' בחי' דבור הוא המל' לחכ' כו', וכמו\"כ הוא העליי' מבחי' עולם העשי' בעילוי כל עולם לפי ערכו עד בחי' חכ' דאצי' כו'.\nב) <b>אך</b> הנה כתיב אשר ברא אלקים לעשות, וארז\"ל לעשות לתקן שכל מה שנברא בשי\"ב צריכין תיקון אפי' תורמסין צריכין תיקון, וכתיב ושמרו בנ\"י את השבת לעשות את השבת דמזה משמע שישראל עושים את השבת, וצ\"ל הלא שבת מיקדשא וקיימא כו' כנ\"ל. הנה כתיב חכמות בחוץ תרונה וקאי על התורה כמ\"ש (משלי ט') חכמות בנתה ביתה חצבה עמודיה שבעה הם ז' ס\"ת כמשארז\"ל במד\"ר, ופי' חכמות לשון רבים פי' בזהר חכמות תרי חכ' עילאה וחכ' תתאה, דהנה התורה כמו שהיא למעלה הנה אורייתא מח\"ע נפקת (שהוא בחי' חכים ולא בחכ' ידיעא, וז\"ע אלפים שנה חו\"ב קדמה לעולם ז\"א כו'), והתורה כמו שנתלבשה למטה הוא רק נובלות חכמה שלמעלה תורה והוא בחי' ח\"ת, אבל מ\"מ הנה ח\"ע מלובש בח\"ת ולכן"],[2000560219,"ל\"ב חוטי הציצית הם כנגד ל\"ב נתיבות חכ', וכן ד' בתי התפילין ה\"ע ד' מוחין, וכן אבני האפוד שנשא אהרן שהגם שהיו גשמי' אבל הם רומזי' למעלה לבחי' אורות עליונים כו', והיינו כי ח\"ע נתלבשה בחכמה תתאה ועי\"ז תרונה שע\"י שנתלבשה ח\"ע בח\"ת עי\"ז תרונה, פי' תרונה הוא רננא דאורייתא שהוא בחי' שיר, כי הנה יש ד' בחי' טנת\"א והגילוי שבתורה הוא רק מבחי' אותיות התורה, ומעט גם מבחי' תגין ונקודות כמ\"ש במ\"א בענין ר\"ע הי' דורש על כל קוץ תלי תלים של הלכות, אבל טעמים שבתורה לא נתגלו שהטעמים הם זרקא מקף שופר הולך סגולתא הם בחי' שיר שהוא כמ\"ש ובלילה שירה עמי בחי' ואהי' אצלו שעשועים יום יום שהוא בחי' שעשועי' עצמי' כו', וע\"י שנתלבשה בח\"ת דוקא עי\"ז תרונה דהיינו שממשיכי' בחי' תענוג בחי' שיר בתורה והוא ע\"י המצות שלכן מברכין על המצות אשר קדשנו, פי' אשר הוא ל' תענוג וגם אשר אותיות ראש דהנה החכ' נק' ראשית כמ\"ש ראשית חכמה וראשית ל' נוקבא והיינו כי החכ' היא בחי' מקבל שמקבלת מבחי' ראש וכמ\"ש והחכ' מאין תמצא שנמשכת מבחי' אין דהיינו שלא בדרך השתלשלות עילה ועלול רק כמו בחי' יש מאין, כי בחי' האין שממנו תמצא החכ' הוא למעלה ממדרגת החכמה, והוא כמו עד\"מ באדם כשנופל לו המצאה וסברא חדשה אזי מתמלא תענוג, מזה אנו רואים שבחי' התענוג הוא למעלה מבחי' חכ' דהיינו שהוא מקור החכמה, ולכן בתחלת התחדשות הסברא יהי' העונג גדול להיות כי רגע זו יצאה ונמשכה החכ' ממקורה התענוג לכן מאיר בה אור התענוג, משא\"כ כשמתיישן הסברא אח\"כ אינו מתענג כ\"כ מהסברא שכבר נתרחקה ממקורה שהוא התענוג, וכמו\"כ למעלה בחי' תענוג העליון הוא מקור החכ' וזהו והחכ' מאין תמצא מאין הוא בחי' עונג, וזהו שנק' חכ' ראשית שהוא מקבל מבחי' ראש הוא התענוג עליון. וזהו חכמות בחוץ תרונה שמפני שנתלבשה בחי' ח\"ע בח\"ת הנה ע\"י המצות ממשיכים מבחי' אשר בחי' תענוג בתורה, וזהו כמו יושב ועוסק בתורה שהוא בחי' המשכת אוא\"ס ב\"ה בתורה, וזהו ג\"כ ענין לימוד התורה לשמה לשם התורה, והיינו כשלומד תורה כדינה ללמוד וללמד לשמור ולעשות, אז ע\"י המעשה וגם ע\"י ההכנה למעשה המצות ממשיך המשכת אוא\"ס ב\"ה בתורה. ועד\"ז הוא ענין לעשות את השבת שישראל עושין את בחי' השבת, שהגם ששבת מיקדשא וקיימא שהוא כי בו שבת דהיינו העלי' מעשי' לחכ' כנ\"ל, הנה עכ\"ז העלי' היא רק בחכ' שנקראת ראשית, ולכן שבת הוא בחי' שבת בראשית שהיא בחי' מקבל כנ\"ל, אבל פי' לעשות את השבת דהיינו להמשיך"],[2000560220,"מבחי' עונג בשבת שזהו מ\"ש וקראת לשבת ענג, ענג ר\"ת עדן נהר גן כו', וזהו הציווי זכור את יום השבת לקדשו דהיינו להמשיך מבחי' ענג בשבת כו'.\nג) <b>ומעתה</b> יובן ענין זכור וענין שמור, דהנה שמור הוא מל\"ת כמשארז\"ל (סוטה דף ה' ע\"א, שבועות ד' ע\"א, מכות י\"ג ע\"ב, עירובין צ\"ו ע\"ב, ע\"ז נ\"א ע\"ב, זבחים דק\"ו א', מנחות צ\"ט ב') כ\"מ שנאמר השמר פן ואל אינו אלא ל\"ת, וזכור הוא מ\"ע כי זכור עם י\"ה רמ\"ח מ\"ע, ולכאו' צ\"ל הלא שמי עם י\"ה שס\"ה מל\"ת וזכרי עם ו\"ה רמ\"ח מ\"ע כו' (בקבלה יש ב' דיעות, הא' הוא של\"ת הם בי\"ה של שם הוי' ומ\"ע הם ו\"ה של שם הוי', ויש דיעה שהגם ששרש ל\"ת הם מבחי' י\"ה זהו רק השורש שלהם, אבל בעצם הם למטה מבחי' מ\"ע דהיינו בחי' י\"ה שלמטה משם הוי' כמשי\"ת, וכאן נאמר כמו דיעה זו). הנה בקרי\"ס אמרו עזי וזמרת י\"ה ולע\"ל נא' בישעי' (כ\"ו א') ביום ההוא יושר השיר הזה כו' כי בי\"ה הוי' צור עולמים ואיתא במדרש תלים בקי\"ס הי' השיר של שני אותיות עזי וזמרת י\"ה, אבל לע\"ל יהי' השיר של ששה אותיות כי בי\"ה הוי' צור עולמים, ולכאו' צ\"ל הלא שם הוי' הוא ג\"כ י\"ה וא\"ו ה\"א וא\"כ מהו ב' פעמים י\"ה.\n<b>הנה</b> בישעי' סי' ל\"ח במכתב לחזקי' כתיב אמרתי לא אראה י\"ה י\"ה בארץ החיים כו' כי יש ב' בחי' י\"ה, וזהו ג\"כ מ\"ש מן המיצר קראתי י\"ה ענני במרחב י\"ה שיש ב' בחי' י\"ה, דהנה פי' יו\"ד ה\"א הוא שיו\"ד הוא בחי' צמצום כדי שיוכל להיות אח\"כ בחי' ה' התפשטות וא\"ו המשכה כו', והיינו שאפי' כדי שיהי' בחי' שם הוי' הוא ג\"כ ע\"י צמצום דיו\"ד, ולכן מתחיל שם הוי' ביו\"ד, וכדי שיתהווה עולמות הנבראים משם הוי' צ\"ל עוד צמצום והתפשטות דיו\"ד ה\"א, וזהו כי בי\"ה הוי' צור עולמים שכדי שיוכל להיות בחי' בריאת העולמות משם הוי' הוא ע\"י צמצום דיו\"ד דוקא ואח\"כ ה' התפשטות, והיינו בחי' י\"ה דבי\"ה, שע\"י בחי' יו\"ד ה\"א זה הוי' צור עולמים. ואפ\"ל היינו העוה\"ב והעוה\"ז כמארז\"ל ברבות בראשית פי\"ב דט\"ו ע\"ב, וכ\"ה במנחות דף כ\"ט ע\"ב, ביו\"ד נברא העוה\"ב ובה' נברא העוה\"ז, וע' בישעי' ע\"פ בטחו בהוי' (כ\"ו ד') דקס\"ד ב'. והנה בשעת בריאת העולם לא הי' הרע מעורב בהטוב כ\"א שהטוב הי'"],[2000560221,"בפ\"ע והרע בפ\"ע רק ע\"י חטא עה\"ד נתערב טו\"ר, לכן העבודה עכשיו ע\"י מל\"ת שהוא בחי' הרחקת הרע להפריד הרע מן הטוב כי לא יגורך רע כתיב, ואז אח\"כ יכול להיות נמשך ע\"י קיום מ\"ע בחי' ה' של שם הוי'.\n<b>וזהו</b> שמי עם י\"ה שס\"ה מל\"ת זכרי עם ו\"ה רמ\"ח מ\"ע, פי' כי ע\"י מל\"ת שמפרידים הרע מן הטוב עי\"ז ממשיכים בחי' י\"ה דבי\"ה הוי' צור עולמים והיינו ע\"י בחי' סור מרע, וזהו מן המיצר קראתי י\"ה שע\"י המיצר באתכפי' ואתהפכא במצות ל\"ת עי\"ז קראתי י\"ה דהיינו בחי' י\"ה דבי\"ה הוי' צור עולמים (פי' דהיינו בחי' יו\"ד ה\"א שלמטה משם הוי', והיינו בחי' י\"ה שביו\"ד נברא העוה\"ב ובה' נברא העוה\"ז כו'), ואח\"כ ע\"י בחי' ועשה טוב דהיינו קיום רמ\"ח מ\"ע עי\"ז ממשיכים בחי' אותיות ו\"ה של שם הוי' וזהו זכרי עם ו\"ה רמ\"ח, אבל בחי' י\"ה של שם הוי' הוא בחי' היותר גבוה וע\"ז אמרו בכהאריז\"ל שאין יכולים להמשיך מבחי' יו\"ד ה\"א של שם הוי' כ\"א ע\"י בחי' מס\"נ בק\"ש שהוא למסור נפשו באחד כו', וע' בלק\"ת מענין מושבותיכם תביאו לחם תנופה בביאור על ואהי' אצלו אמון ד\"ך ע\"ג.\n<b>ומ\"ש</b> במ\"א שזכור עם י\"ה רמ\"ח מ\"ע שע\"י מ\"ע ממשיכים מבחי' י\"ה, היינו כי יש ב' בחי' מצות, דהמצות שניתנו לנו הנה על ידם ממשיכים מבחי' ו\"ה, אבל יש בחי' מצותיו שהוא מה שהקב\"ה מניח תפילין והקב\"ה מתעטף בציצית שע\"י נמשך בחי' י\"ה של שם הוי' (וע\"י קיום המ\"ע הנה עי\"ז ממשיכים להיות הקב\"ה מניח תפילין כו' ונמשך בחי' יו\"ד ה\"א של שם הוי' כו'). ונמצא כי יש ג' מדרגות, ע\"י מל\"ת ממשיכים בחי' י\"ה שלמטה משם הוי', ואח\"כ ע\"י מ\"ע ממשיכים בחי' ו\"ה דשם הוי', וענין זכור עם י\"ה רמ\"ח היינו בחי' מצותיו שהקב\"ה מניח תפילין שנמשך ע\"י בחי' י\"ה דשם הוי' כו'.\n<b>וזהו</b> זכור את יום השבת לקדשו ושמור את יום השבת, שמור לנוק' וזכור לדכורא, כי שמור הוא בחי' שבת דמעלי שבתא שהוא בחי' העלאה מלמטלמ\"ע בחי' כלה כו', וזכור לדכורא שהוא בחי' המשכת העונג מבחי' י\"ה דשם הוי' שזהו מ\"ש וקראת לשבת ענג עדן נהר גן כו'. (ועפ\"ז אפשר לפרש הפסוק בישעי' (סי' ל\"ח י\"א) אמרתי לא אראה י\"ה י\"ה בארץ החיים דצ\"ל מהו ב\"פ י\"ה, אלא כי באמת יש ב' בחי' י\"ה הא' בחו\"ב ונהר יוצא מעדן, הב' בח\"ת ג\"כ ונהר יוצא היינו יסוד להשקות את הגן מל', וזהו שורש ב' בחי' ג\"ע היינו ג\"ע העליון וג\"ע התחתון כי ג\"ע העליון שרשו מבינה ה' עילאה, וג\"ע התחתון שרשו ממל', ע' בישעי' דרי\"א ע\"ב)."],[2000560222,"ד) <b>אך</b> הנה תחלה צ\"ל ששת ימים תעבוד וביום השביעי שבת כו', דלכאורה צ\"ל מהו הציווי על עבודה. והענין הוא דהנה ובטובו מחדש בכל יום תמיד מעשה בראשית דכמו במע\"ב הי' צמצום וירידה להוות בחי' בריאת העולם כנ\"ל כמו\"כ תמיד בכ\"י הוא בחי' הצמצום לחדש מע\"ב, וע\"י מה ממשיכים בחי' זו זהו ע\"י עבודה במו\"מ באמונה, ולכן ארז\"ל ברכות ח' א' גדול הנהנה מיגיע כפיו יותר מיראת שמים וכן אמרו במד\"ר ס\"פ ויצא פע\"ד חביבה היא המלאכה מזכות אבות שזכות הצילה ממון ומלאכה הצילה נפשות, זכות הצילה ממון שנא' לולי אלקי אבי כו', ומלאכה הצילה נפשות שנא' את עניי ואת יגיע כפי כו', וע' בספר תרטו\"ב בביאור ע\"פ רני ושמחי סס\"ב, וכן ארז\"ל באבות שמעי' אומר אהוב את המלאכה מפני כי ע\"י מו\"מ באמונה ממשיכים בחי' מה שבטובו מחדש בכ\"י תמיד מע\"ב. וגם פי' עבודה הוא בחי' עבודת המצות בבחי' אתכפי' ואתהפכא ועי\"ז ממשיכים אח\"כ בשבת שזהו זכור את יום השבת לקדשו זכור לדכורא. וזהו מ\"ש אשרי איש ירא את ה' וארז\"ל בע\"ז דף י\"ט א' אשרי איש ולא אשה, פי' אשה הוא בחי' מקבל ע\"ד שארז\"ל אל תהיו כעבדים המשמשים את הרב ע\"מ לקבל פרס שזהו בחי' אשה, אבל איש בחי' דכר משפיע שנש\"י ממשיכים בבחי' שבת.\n<b>ובזה</b> יובן משארז\"ל במד\"ר בראשית ס\"פ י\"א דף י\"ד ע\"א תני רשב\"י אמרה שבת לפני הקב\"ה לכולם נתת בן זוג ולי לא נתת בן זוג, א\"ל כנס\"י יהי' בן זוגך, וכיון שעמדו ישראל לפני הר סיני א\"ל הקב\"ה זכרו הדבר שאמרתי לשבת כנס\"י הוא בן זוגך היינו דבור זכור את יום השבת לקדשו עכ\"ל, פי' לכולם נתת בן זוג כי ששה ימים הם ג' זוגות ונשארה שבת בלא בן זוג, וזהו ולי לא נתת בן זוג א\"ל כנס\"י יהי' בן זוגך שישראל ממשיכים בשבת בחי' הענג כנ\"ל. והענין הוא כי הששה ימים הם ג' זוגות, חסד וגבורה, נצח והוד, וגם ת\"ת ויסוד הם ג\"כ זוג כמו בנענוע הלולב צפון ודרום חו\"ג, מעלה ומטה נו\"ה, מזרח ומערב הם ת\"ת ויסוד, כי גוף וברית חשיב חד, אבל השבת שהיא השביעית בחי' מל' אין לה בן זוג, ע\"כ א\"ל הקב\"ה כנס\"י הוא בן זוגך שבהם נא' ג\"כ הן עם לבדד ישכון כמשארז\"ל ברבות בא פט\"ו מהו הן כל האותיות מזדווגין חוץ משני אותיות הללו, א\"ט כו' ונשאר ה', י\"צ כו' ונשאר הנו\"ן, כשם ששני אותיות כו' כך ישראל אין יכולי' להזדווג ולהתערב כו' יעו\"ש, ובזה אתי שפיר הא דשבת אין לה בן זוג דאמאי לא תקבל מו\"ק ע\"י היסוד שהם ששת ימי בראשית כו', אלא כי הם נק' ששת ימי החול ושבת הוא קדש וא\"א לקדש להתדבק עם החול כו', וכמ\"ש כה\"ג בפע\"ח שער הקדישי' גבי לבנה כו', והיינו כי ששת ימי המעשה ו\"ק דבריאה יצי' והשבת מל' דאצי' כו', או שי\"ב הם ו\"ק דאצי' והשבת היא בינה שנק' שביעאה בזח\"ב ס\"ג ב', ע\"כ א\"ל כנס\"י הוא בן זוגך,"],[2000560223,"והיינו לפי' הא' ששבת היא מל' דאצי' מטרונה, א\"כ נש\"י ממשיכים מישראל דלעילא הוא ז\"א שיומשך היחוד במל', וז\"ס יחוד ו\"ה, וכה\"ג מצינו שכנס\"י נק' חתן לגבי תורה כמ\"ש מאורשה כו' והיינו כי תושבע\"פ מל' וישראל ממשיכים מז\"א תושב\"כ אל תושבע\"פ, ע\"כ נק' חתן כמ\"ש בד\"ה תורה צוה, וזהו פי' כנס\"י הוא בן זוגך. ולפי פי' הב' דשבת היא בינה ואין לה זוג מו\"ק שלמטה ממנה אלא כי נש\"י עלו במח' היא חכ' (כמ\"ש בזח\"א פ' חיי דקך\"ג ע\"א מח' ויובלא) ממשיכים האור בבינה, כי יסו\"א מקבל מעתיק ממו\"ס ומשפיע בבינה כו', וכן בעסק התורה שנק' מאורשה לישראל היינו שישראל ממשיכים אוא\"ס בחו\"ב כו' ע\"י בכל מאדך כו'. וזהו פי' זכור את יום כו' כלומר שתהי' בבחי' זכור היינו בבחי' דכר להשפיע ביום השבת ולקדשו כדרך שהחתן מקדש הכלה, וכמאמר וינוחו בה ישראל מקדשי שמך, שמך היינו מל' או בינה וישראל ממשיכי' הקדושה מבחי' אתה קדוש בבחי' שמך קדוש.\nה) <b>ומעתה</b> יובן ענין זכור ושמור בדבור א' נאמרו, דהנה ארז\"ל ביצה ט\"ז א' מתנה טובה יש לי בבית גנזי ושבת שמה לך והודיעם, דלכאו' צ\"ל הלא נת' שנש\"י ממשיכים בשבת שזהו פי' לעשות את השבת, לעשות לתקן, וכאן אמרו ששבת היא מתנה רק לך והודיעם כו'. אך הענין דהנה יש בחי' שבת שגבוה יותר דמה שנת' כאן ענין שבת הוא ששבתו מבחי' הצמצומי' דשם אלקים שבעש\"מ נאמר שם אלקים כנ\"ל, ואח\"כ שבת מכל מלאכתו שנתעלה בחי' שם אלקי' בשם הוי', אבל יש בחי' שבת להוי' אלקיך שהוא בחי' שבת שבתון שהוא גבוה יותר, ובחי' התענוג הוא מ\"ש אז תתענג על הוי' שהוא למעלה משם הוי', דמ\"ש וקראת לשבת ענג הוא רק הארה מבחי' ענג, אבל אז תתענג על הוי' הוא בחי' ענג בעצם ובחי' זו הוא בבחי' מתנה. וזהו זכור ושמור בדבור אחד נאמרו שלגבי בחי' זו זכור ושמור הם בשוה שאינו תופס מקום כלל, ואעפ\"כ צ\"ל בחי' שמור כמשל האדם כשנותנים לו מתנה צריך לשמור אותה שלא יאבדה, כמו\"כ בחי' שבת זו צריך ג\"כ שמירה כו', וענין השמירה הוא שלא יהי' מגסי הרוח כמו שארז\"ל אין אני והוא יכולים לדור, וכן כתיב (תלים ק\"א) דובר שקרים לא יכון לנגד עיני וארז\"ל חגיגה י\"ד ב' א\"ת מים מים שנאמר דובר שקרים לא יכון לנגד עיניו, פי' אפי' שקר זה לא יכון לנגד עיניו כי מים תחתונים הגם שהם מקור לתענוגי' גשמי' עכ\"ז צריך להבין שהכל בטל אליו ית', ולגבי בחי' שבת זה צ\"ל השמירה אפי' בשקר כזה.\n<b>ובד\"כ</b> ג' בחי' דשבת הם ג' סעודות דשבת, ששבת דמעלי שבתא הוא בחי' העלאה מלמטלמ\"ע בחי' כלה היא סעודה ראשונה דשבת, וסעודה שני' הוא בחי' זכור את יום השבת שהוא בחי' המשכת הארת הענג כנ\"ל, וסעודה שלישית הוא בחי' רעוא דכל רעוין בחי' זכור ושמור בדבור א' בחי' ענג בעצם כנ\"ל וד\"ל."],[2000560224,"<b>וע'</b> בד\"ה את שבתותי תשמורו שלא נדפס (ובד\"ה ויכל אלקי' ביום השביעי), ובהגהות לד\"ה ויאמר משה אכלוהו היום מענין ג' סעודות דשבת, וסעודה שלישית זהו ממ\"ש היום לא כו' יעו\"ש.\n<b>ענין</b> היום לא י\"ל ע\"ד ל\"ת, אך אפ\"ל זהו לדיעה של\"ת מגיעי' בבחי' י\"ה דשם הוי', וכאן נת' לדיעה של\"ת זה\"ע י\"ה דבי\"ה הוי' צור עולמים, וצ\"ע."],[2000560225,"<h3>אם כסף תלוה כו'</h3>\n<b></b><b>בס\"ד. (ש\"פ משפטים, רכ\"ז).</b>\nענין הקרבן - ו\"פ\n[משפטים]\n<b>אם</b> כסף תלוה את עמי את העני עמך לא תהי' לו כנושה, וצריך להבין יתור הלשון מה שאומר את עמי את העני עמך הל\"ל אם כסף תלוה את העני עמך, וארז\"ל במד\"ר ס\"פ ל\"א אם כסף תלוה ולא תקח ממנו רבית את עמי מה אני איני מט לעולם אף אתה אינו מט לעולם, והיינו שהמכוון מפסוק זה שיעשה גמילת חסדים ממש בלי שום פני' לעצמו, וזהו לא תהי' לו כנושה וארז\"ל במשנה יו\"ד פ\"ה דב\"מ יש רבית דברים כו' ולא יתנהג עמו כעבד לוה לאיש מלוה רק שיהי' גמילת חסד ממש ועי\"ז את עמי. ולכאו' צ\"ל איך התירו רז\"ל תילתא באגר ופלגא בהפסד ולמה לא הרחיקו לגמרי מאיסור נשך. אך הענין הוא דבעה\"כ של הסה\"ד הביא בשם שמ\"ל שירידת"],[2000560226,"הנשמה בגוף נק' בשם עיסקא, שכמו העיסקא הוא פלגא מלוה ופלגא פקדון, שמפלגא מלוה נוטל המקבל השכר ומפלגא פקדון שייך השכר להנותן, וכמו\"כ בירידת הנשמה בגוף יש ב' בחי', היינו מה שהירידה צורך עלי' זהו השכר להנשמה ולהגוף, ויש ג\"כ מזה ריוח למעלה שהוא הנותן, היינו כמ\"ש הבו גודל לאלקינו וארז\"ל במד\"ר איכה בזמן שישראל עושין רצוש\"מ מוסיפי' כח בגבורה של מעלה כמד\"א באלקי' נעשה חיל.\n<b>ולהבין</b> זה צ\"ל מארז\"ל על ג\"ד העולם עומד על התורה ועל העבודה ועל גמ\"ח, עבודה הוא בחי' עבודת הקרבנות. ולהבין זה צ\"ל מקודם פי' הפסוק מ\"ש (הושע וא\"ו פ\"ו) כי חסד חפצתי ולא זבח, ולכאו' אינו מובן שהרי עיקר בהמ\"ק הי' כדי להקריב קרבנות, וכן מלא כל תושב\"כ מענין הקרבנות כמו אדם כי יקריב מכם קרבן וכדומה שיש כמה פרשיות בתורה מענין הקרבנות, ואיך אומר כי חסד חפצתי ולא זבח. אך הענין הוא דהנה קרבן הוא שמקריבין בהמה ע\"ג המזבח, ובזה שמקריבין אותה ע\"ג המזבח עי\"ז מתעלית לשרשה ומקורה, דהנה ידוע שיש ד' חיות המרכבה פני ארי' פני שור פני נשר פני אדם, והנה פני ארי' הוא שרש ומקור לכל חיות, ופני שור הוא שרש ומקור לכל בהמות, ופני נשר לכל העופות, ופני אדם לנפש השכליות, והגם שרחוקה מאד נפש הבהמה מבחי' פני שור שהוא מרכבה ממש לשכינה וצריך להיות רבבות מדרגות ביניהם, מ\"מ הנה הוא שרש ומקור לבחי' נפש הבהמה רק שנמשכה ע\"י ריבוי השתלשלו' עד שנעשה נפש הבהמה, וכמשארז\"ל אין לך עשב מלמטה שאין לו מזל מלמעלה כו' וכ\"ש אילנות, שבודאי אין ערוך העשב והאילן למזל המכה בו ואומר גדל ומ\"מ הוא מקור ושרש להשפיע החיות בעשב והאילן שיצמח תפוח הגשמי, כמו\"כ פני שור הגם שנפש הבהמה רחוקה מאד מבחי' פני שור, מ\"מ פני שור הוא שרש ומקור לנפש הבהמה. והנה ע\"י שמקריבין את הבהמה ע\"ג המזבח עי\"ז מתעלית לשרש שרשה בחי' פני שור שבמרכבה, ואח\"כ מתכללת בבחי' פני ארי', וזהו ענין ארי' דאכיל קרבנין שהוא בחי' לאכללא שמאלא בימינא, שמתכלל הקרבן שעולה עד פני שור בבחי' ארי' שעל הימין כמ\"ש בלק\"ת בד\"ה וארי' כבקר יאכל תבן די\"א א', וע' בזהר בההקדמה ד' וא\"ו ע\"ב ובמק\"מ שם מענין ארי' דאכיל קרבנין. ואח\"כ מתעלי' עוד יותר, וזהו ענין"],[2000560227,"והחיות נושאות את הכסא וגם את בחי' כמראה אדם, כמ\"ש ועל הכסא דמות כמראה אדם עליו מלמעלה לבחי' אוא\"ס בחי' כי לא אדם הוא כו' כי רזא דקורבנא עולה עד רזא דא\"ס, ולכן ע\"י העלאת הקרבן מנשאים החיות את הכסא עם בחי' האדם שעל הכסא לבחי' אוא\"ס שלא אדם הוא כו'. דהנה בחי' אדם הוא ג' קוין שהוא בחי' חסד דרועא ימינא גבורה דרועא שמאלא תפארת גופא, ודרך כלל הוא ג' קוין שהוא בחי' חח\"ן מימין בג\"ה משמאל דת\"י כו' שהוא ע\"ס בכלל וזהו בחי' כמראה אדם, והנה זהו רק לאחזאה איך מתנהג עלמא אבל לאו דאית לך צדק ידיעא כו' ולא מכל אינון מדות איהו כלל ואין ערוך אליו כלל, וע\"י הקרבן מנשאים את בחי' כמראה אדם כו' לבחי' עצמיות אוא\"ס ב\"ה, וע\"י העלאה זו נמשך תוס' אור בע\"ס וז\"ע נחוח להוי' כו'.\n<b>וזהו</b> מ\"ש את קרבני לחמי לאשי שהוא בחי' אש שלי דהיינו שרפים עומדים הם בחי' אש, ולכך נקראים שרפים ע\"ש רשפי אש התשוקה שיש להם ליבטל וליכלל באוא\"ס, ונקראים עומדים כמ\"ש שרפים עומדים ממעל לו ע\"ש שעומדים תמיד במדרגה אחת בבחי' רצוא לפי ששרפים אומרים קדוש, והנה פי' קדוש הוא לשון מובדל דהיינו שמשיגים איך שאוא\"ס הוא קדוש ומובדל בערך על העולמות ואינו כמו בחי' שהנשמה מחי' את הגוף שמתלבשת בגוף ומתפעלת ממקרי הגוף, אבל למעלה כתיב אני הוי' לא שניתי כלל לפי שאינו מתלבש כלל בעולמות ומובדל מגדר עולמות, וזהו ענין ג' פעמים קדוש הוי' צבאות שכדי שיהי' בחי' צבאות אות הוא בצבא שלו (ע' בת\"א ד\"ה בעצם היום הזה יצאו בפ' בא) צריך להיות ג' צמצומים, כי קדוש הוא בחי' קדש ו' שענין הוא\"ו הוא רק המשכה בדרך קו מבחי' קדש, וזהו ענין ג' צמצומים כדי להיות צבאות כו', והנה כשהשרפים משיגים זה איך שהוא קדוש ומובדל עי\"ז נעשה להם הרצוא ליבטל וליכלל באוא\"ס ממש ועומדים תמיד בבחי' רצוא זו ולכך נקראו בשם שרפים ע\"ש רשפי אש כי טבע האש לעלות למעלה כו'.\nב) <b>והנה</b> הקרבנות הם ג\"כ בבחי' אש, כי הנה ידוע שדצח\"מ הוא כנגד ארמ\"ע, והנה דומם הוא כנגד בחי' יסוד העפר, וצומח הוא כנגד יסוד המים כי מים מצמיח כל מיני תענוג, וחי הוא כנגד בחי' יסוד האש, ומדבר הוא כנגד בחי' רוח וכמ\"ש ויהי האדם לנפש חי' ות\"א לרוח ממללא, והיינו שע\"י שמקריבין הבהמה ע\"ג המזבח, עי\"ז נעשה בחי' אש לעלות למעלה ונכללת בבחי' אש של השרפי'. וז\"ע"],[2000560228,"לחמי לאשי שהם בחי' לחם לאשי הם השרפים הנ\"ל, עד שמתעלה לבחי' אוא\"ס ממש והחיות נושאות את הכסא כנ\"ל, וזהו ענין הקרבנות.\n<b>והנה</b> עכשיו תיקנו התפלה במקום קרבנות כי הוא ג\"כ להקריב נפשו הבהמיות שתוכלל למעלה בשרשה כי שרש נפש הבהמית של האדם הוא ג\"כ מבחי' פני שור שבמרכבה, רק שהיא מבחי' פני אדם שבבחי' פני שור, וע\"י התפלה מתעלה לשרשה, וזהו ענין ברכת יוצר אור שהוא אריכות הסיפור מענין ביטול והתפעלות המלאכים באהוי\"ר איך שעומדי' ברום עולם ומשמיעי' ביראה כו' ושרפים אומרים קדוש, והאופנים וחיות הקדש מתנשאי' לעומת השרפים ואומרים ברוך כו', והנה ע\"י אריכות ההתבוננות שמתבונן איך שהשרפים וחיות הקדש אומרים קדוש וברוך ובטלים בתכלית לאלקות עי\"ז נקרב נפשו הבהמיות ג\"כ לפי ששרשו ג\"כ משם ורוצה גם הוא ליכלל למעלה להיות ואהבת בכל לבבך בשני יצריך, ועי\"ז נעשה עלי' לבחי' נה\"א ג\"כ כמ\"ש במ\"א, וזהו ענין ק\"ש שהוא למסור נפשו באחד שהוא בחי' ביטול של נה\"א שהוא בחי' עלי' לאוא\"ס ממש כמו והחיות נושאות את הכסא, והיינו שנה\"א מתפעל מבחי' התבוננות של אוא\"ס ממש איך שאני הוי' לא שניתי כו' וכולא קמי' כלא חשיב כמ\"ש במ\"א.\n<b>וכ\"ז</b> הוא בחי' זבח שהו\"ע הקרבנות, אך מ\"ש כי חסד חפצתי ולא זבח היינו עיקר המכוון כי חפץ חסד הוא בחי' פנימית הרצון והיינו שעיקר המכוון הוא כדי שיהי' בחי' המשכה מלמעלה למטה, אבל מ\"מ צריך להיות ג\"כ בחי' זבח, וכמו למשל כשאדם רוצה לנסוע לאיזה מקום לקנות סחורה שיש לו רצון בנסיעה זו, אבל לא זהו עיקר המכוון, כי עיקר המכוון הוא הריווח שיהי' מזה כדי להחיות נפשו, ואם לא הריווח לא הי' רוצה ליסע כלל, אך מחמת הריווח ממילא יש לו רצון בנסיעה זו ג\"כ לפי שאם לא הנסיעה לא ירויח. וזהו ג\"כ ענין מ\"ש חסד חפצתי ולא זבח, דהיינו שעיקר פנימיות הרצון הוא בחי' חסד, אך מ\"מ יש לו רצון ג\"כ בבחי' זבח רק שהוא בחי' חיצוני' הרצון, שלא זה הוא העיקר כי עיקר המכוון הוא בחי' המשכה מלמעלה למטה כי נתאוה הקב\"ה להיות לו דירה בתחתונים דוקא, וכך הוא ענין התפלה שהוא העלאה מלמטה למעלה ותורה ומצות הוא המשכות מלמעלה למטה שהוא בחי' חסד."],[2000560229,"<b>ועפ\"ז</b> יובן משארז\"ל (ר\"ה די\"ח א' וביבמות דק\"ה א') ע\"פ אם יתכפר עון בית עלי בזבח ובמנחה, בזבח ובמנחה אינו מתכפר אבל מתכפר בתורה ובגמ\"ח, רבה דעסיק בתורה חי מ' שנין אביי דעסיק בתורה ובגמ\"ח חי שיתין שנין, והיינו כי חסד חפצתי ולא זבח בחי' העלאות מלמטלמ\"ע כ\"א חסד דוקא בחי' תורה המשכת אלקות מלמעלמ\"ט, וכמו\"כ גמ\"ח (וצ\"ל דהיינו קרבן מנחה דאילו מנחה שבעולה (כמ\"ש במדבר ך\"ח ועשירית האיפה) יתבאר לקמן שזהו בחי' המשכה). וזהו ענין מה שארז\"ל (ברכות י\"ד סע\"ב) כל הקורא ק\"ש בלא תפילין כאלו הקריב עולה בלא מנחה וזבח בלא נסכים, ולכאו' אינו מובן מה שייך דמיונם זל\"ז, אך לפי הנ\"ל יתורץ דהנה קרבנות הם בחי' העלאה ממטה למעלה שהוא בחי' אש, שבחי' חי הוא בחי' יסוד האש כנ\"ל, אבל נסכים ומנחה הם בחי' צומח, שיין ומנחת סולת שחייב הכתוב כמ\"ש ועשירית האיפה סולת, הם בחי' צומח שהם מבחי' יסוד המים כי מים מצמיחים כל מיני תענוג ומים יורדי' ממקום גבוה למקום נמוך שהוא המשכת אלקו' ממעלה למטה, וזהו ג\"כ ענין ק\"ש ותפילין, כי ק\"ש הוא בחי' רצוא למסור נפשו באחד הוא בחי' העלאה ממטה למעלה. אבל מצות תפילין הם המשכת אלקות מלמעלמ\"ט והוקשה כל התורה כולה לתפילין, והיינו כמו שהתפילין הוא המשכת אלקו' למטה שכותבין הוי' אחד על קלף גשמי, כמו\"כ כל המצות הם המשכות אלקות למטה, וזהו שאמרו כל הקורא ק\"ש בלא תפילין דהיינו בחי' רצוא בלא שוב הוא כעולה בלא מנחה וכזבח בלא נסכים שהוא בחי' רצוא בלא שוב כנ\"ל.\nג) <b>והנה</b> מעתה י\"ל דלפי מה שנת' לעיל דתפלה הוא במקום הקרבנות שהיא בחי' העלאה ממטה למעלה, א\"כ לכאורה אינו מובן מה דאיתא במס' שבת ר\"פ מפנין דקך\"ז סע\"א וע\"ב, דקא חשיב ר' יוחנן התם עיון תפלה מן הששה דברים שאדם אוכל פירותיהן בעוה\"ז כו', ופריך התם והא תנן ריש פיאה אלו דברים כו' ולא קא חשיב רק שלשה דברים, ומשני הא דהני בהני שייכי כו', ופרש\"י עיון תפלה הוא בכלל גמ\"ח דכתי' גומל נפשו איש חסד, ור\"י לפרושי מתניתין כו', וא\"כ לפ\"ז הוא היפוך ממה שנת' לעיל דתפלה הוא במקום הקרבנות. והנה מתחלה צ\"ל פי' גומל נפשו איש חסד, והנה בפי' גומל יש שני פירושים, הא' לשון ויגמול שקדים (במדבר י\"ז ך\"ז) ויגדל הילד ויגמל (בראשית ך\"א ח'), והיינו שצריך לגמול את נפשו מבחי' מותרות שלא יהי' נמשך אחר תענוגי עוה\"ז שהוא רק מותרות. והב' הוא כמו אשירה להוי' כי גמל עלי (תהלים י\"ג ו') גמל עליכי (קי\"ו ז') שהוא ל' גמ\"ח ג\"כ"],[2000560230,"שז\"ע המשכה לנפשו כמו מי שעושה גמ\"ח בחבירו שמשפיע לחבירו, וזהו ג\"כ לשון גומל נפשו כו'.\n<b>והנה</b> ב' הפירושים יש בתפלה, דהנה ארז\"ל במשנה פ\"ה דברכות אין עומדין להתפלל אלא מתוך כובד ראש ופי' רש\"י כובד הכנעה, וזהו כפי פי' הא' בתיבת גומל שצריך לגמול נפשו מבחי' מותרות. וזהו ענין כובד ראש ע\"ז שנמשך נפשו בבחי' מותרות, ולפי' הב' לשון גומל נפשו הוא בחי' גמ\"ח, הענין הוא דהנה תפלה נק' בשם שפיכת הנפש וכמ\"ש בחנה ואשפוך את נפשי לפני הוי', ופי' וענין נפשי הנה כתיב והר סיני עשן כולו ר\"ת עולם שנה נפש, והנה עולם הוא בחי' מקום ז' רקיעים וארץ וד' רוחות, ושנה הוא בחי' זמן ונפש הוא בחי' חיות של העולם דהיינו מה שמחי' את העולם, ע' בד\"ה ויצוום אל בנ\"י מענין עש\"ן, וזהו ענין מלכותך מכ\"ע שהוא בחי' מקור חיות העולמות, והנה מאחר שנקרא בשם נפש הוא בחי' אחרונה כמו למשל בנפש האדם שיש ה' מדרגות נר\"נ ח\"י, והנה נפש הוא בחי' אחרונה כי הדם הוא הנפש דהיינו החיות שמתלבש בהדם להחיות את גופו כו', אבל רוח הוא מדרגה יותר גבוה כי רוח הוא בחי' רוח החיים שבלב בחלל הימיני, ונשמה הוא במוח שהוא בחי' שכל וכמ\"ש נשמת שדי תבינם, וע' בילקוט פלוגתא דר\"א ור\"י היכן הנשמה שרוי' אם בלב אם במוח ופליגי בפלוגתא דדוד ושלמה, וכמ\"ש בזהר זכה יתיר יהבין לי' מסט' דנשמתא כו' וחי' יחידה הוא בחי' מקיפים, נמצא שנפש הוא מדרגה אחרונה, כמו\"כ למעלה מה שנק' נפש הוא בחי' אחרונה שהוא רק בחי' מל' כו', והנה תפלה נק' בשם שפיכת הנפש כי מל' נק' תפלה כמ\"ש ואני תפלה, ע' בד\"ה נפתלי אילה שלוחה, דהיינו שהתפלה היא להמשיך תוס' אור מבחי' מדרגה עליונה יותר בבחי' נפש וכמ\"ש למען יזמרך כבוד ולא ידום, ופי' בזהר נהורא תתאה קארי תדיר לנהורא עילאה ולא שכיך, והיינו להמשיך מבחי' יחיד בבחי' מלך, וכמו שאנו אומרים יחיד חי העולמים מלך שבחי' יחיד נמשך בבחי' מלך ע\"י חי העולמים, ע' בת\"א בד\"ה כי אתה נרי ובהביאור ובההגהות לשם, וזהו ע\"י התפלה כי תפלה הוא ח\"י ברכאן דצלותא שהוא בחי' המשכה מלמעלה למטה ברוך אתה הוי' בבחי' מלך העולם, וזהו ענין מאה ברכות שהוא הכל להמשיך תוס' אור במל' שהיא בחי' נפש, וזהו יחיד חי העולמים מלך דהיינו שהמשכה מבחי' יחיד בבחי' מלך הוא ע\"י חי העולמים דהיינו ח\"י ברכאן שהוא ענין ח\"י חוליות השדרה, וזהו ענין גומל נפשו איש חסד שע\"י התפלה נמשך בחי' גמילות חסד בבחי' נפש שהוא בחי' מל'."],[2000560231,"ד) <b>אך</b> עדיין צ\"ל שהרי התפלה היא במקום קרבנות כמו שנת\"ל שהוא העלאה ולא המשכה, אך הענין הוא דריב\"ל סובר שהתפלות במקום תמידין תקנו (ברכות דך\"ו ע\"ב) במקום תמידין דוקא, והנה ע\"י תמידין נקראו ישראל רעייתי כמו שארז\"ל במד\"ר שה\"ש בפסוק לסוסתי דף י\"א ע\"א (ובדפוס שקלאוו ד\"ט ע\"ג) מהו רעייתי אמר ר' יונתן מפרנסתי הן שירעו אותי בשני תמידין בכל יום הה\"ד את הכבש אחד תעשה בבקר כו', והיינו שעי\"ז הם בחי' רעייתי פרנסתי ישראל מפרנסין לאביהם שבשמים, והענין הוא דהנה כמו למשל למטה שאנו רואים פעולת המאכל שהוא מחבר את הנפש עם הגוף ובלתי המאכל הי' נפרד הנפש מהגוף ולא הי' לו אחיזה בגוף, כמו\"כ למעלה ישראל מפרנסין לאביהם שבשמים שהם ממשיכי' המשכת אוא\"ס דלאו מכל אינון מדות כלל ואינו בערך המדות כלל בע\"ס והיינו ע\"י קרבנות התמידין נמשך התחברות אוא\"ס עם ע\"ס, וזהו ישראל מפרנסין לאביהם שבשמים, שמים הוא בחי' אש ומים שהוא מדות דאצי', ואביהם שבשמים הוא בחי' חכ'. וזהו מ\"ש ריח ניחוח להוי', ריח הוא בחי' העלאה, ניחוח הוא בחי' המשכה, להוי' בבחי' שם הוי', והיינו בבחי' ע\"ס, וזהו ג\"כ ענין אכלו ריעים לעילא שהוא בחי' או\"א שנק' ריעים והיינו שהוא בחי' המשכת אוא\"ס בבחי' חו\"ב. והנה תפלות כנגד תמידין תקנו שהוא ג\"כ המשכה אלקי' מלמעלה למטה מבחי' יחיד בבחי' ע\"ס כנ\"ל, וזהו שהתפלה נקרא סולם, ע' בלק\"ת בד\"ה כנשר יעיר ובד\"ה יונתי בשה\"ש, ובמ\"א בד\"ה ויחלום, וכמ\"ש והנה סולם מוצב ארצה וראשו מגיע השמימה, והיינו שהוא מחבר שמים שהם מקיפים עליונים עם בחי' ארץ, וכתיב והנה מלאכי אלקי' עולים ויורדים בו, והיינו שבתפלה יש שני בחי' העלאה והמשכה, ק\"ש הוא בחי' העלאה למסור נפשו באחד ותפלה הוא בחי' המשכה, וזהו עולים ויורדים בו.\n<b>והנה</b> יש עוד מעלה בתפלה שהוא כנגד קטרת ג\"כ וכמ\"ש תכון תפלתי קטרת לפניך, והנה הקטרת היו מקריבין ע\"ג המזבח הפנימי ותמידין היו מקריבין על מזבח החיצון, וכמו\"כ בתפלה יש שני בחי' ג\"כ מזבח הפנימי ומזבח החיצון והוא בחי' חיצוני' הלב ופנימי' הלב, והיינו כי בחי' חיצוני' הלב הוא בחי' ביטול של נה\"ב שנמשך מצד ההתבוננות של יוצר אור איך שהאופנים וחיות הקדש ברעש גדול אומרים קדוש וברוך כו' עי\"ז מתפעל ג\"כ נה\"ב שלו ונכלל ובטל לנה\"א שיהי' ואהבת בשני יצריך, אבל זהו רק חיצוני' הלב לפי שנמשך מהתבוננות הנ\"ל שזהו ע\"פ הטעם ודעת וכ\"ז הוא מהארה בעלמא, אבל בעצמיות אוא\"ס ב\"ה לית מח' תב\"כ"],[2000560232,"כו', אבל בפנימיות הלב הוא בחי' עומק הלב שהוא התקשרות עצמי' של נה\"א, וזהו ענין קטרת כי קטרת הוא לשון התקשרות וכמו שאמר רשב\"י בחד קטירא כו' בי' אחידא בי' להיטא, והוא בחי' רצון פשוט לאלקות עד שאינו רוצה בשום דבר זולתו ית', וכמ\"ש מי לי בשמים ועמך לא חפצתי בארץ, והנה ע\"ז כתיב שמן וקטרת ישמח לב דהיינו ע\"י קטרת נמשך בחי' שמן כי שמן שייך לקטרת, וכמ\"ש ובהעלות אהרן את הנרות כו' יקטירנה כו', והנה כתיב שמן ימינו יקרא שהוא בחי' חסד דא\"א ע' בלק\"ת ד\"ה בהעלותך, ובד\"ה ואברהם זקן (ך\"ז) מענין חסד של אמת חסד דקשוט יעו\"ש, והוא בחי' כשמן הטוב היורד על הזקן שהוא בחי' רב חסד שנמשך ע\"י הראש בבחי' מוחין כי אבא מלביש חסד דא\"א, וענין יורד על הזקן היינו בבחי' י\"ג ת\"ד בפנימיות השערות, וזהו ישנו ג\"כ בתפלה. ובזה יובן מה שהתפלה נק' בשם גומל נפשו גמ\"ח שעיקר הוא גמ\"ח המשכת חסד עליון הנ\"ל והקטורת היא בחי' נפילת אפיים כי נפילת אפיים הוא בחי' מס\"נ ממש וכמ\"ש בזהר ס\"פ במדבר דק\"ך ע\"ב ודקך\"ג א'.\nה) <b>והנה</b> על בחי' חסד זה נא' כי אמרתי עולם חסד יבנה, והנה בפי' כי אמרתי עולם חסד יבנה יש שני פירושים, הא' שעיקר בריאת העולם הי' מצד כי חפץ חסד הוא שכך עלה ברצונו לפי שטבע הטוב להטיב, והב' כי עולם הוא לשון זמן והיינו שלעולם צריך להמשיך בחי' חסד, וזהו חסד יבנה שצריך לבנות בחי' החסד שיומשך בעולם, שעכשיו באתעדל\"ת תליא מילתא כי מתחלת הבריאה הי' מצד בחי' כי חפץ חסד הוא ועכשיו במעשה התחתונים תליא כו', וז\"ש כי אמרתי עולם חסד יבנה שלעולם צריך להמשיך בחי' חסד כו'. אמנם צ\"ל שהרי ארז\"ל בפרק שנו חכמים כל מה שברא הקב\"ה בעולמו לא ברא אלא לכבודו שנא' כל הנקרא בשמי ולכבודי כו', וכן כתיב כל פעל ה' למענהו עשה, ולפי מה שנת' בפי' כי אמרתי עולם חסד יבנה משמע להיפך שהוא רק חסד חנם להטיב לברואים לבד.\n<b>אך</b> הענין הוא דהנה זו הקושי' עצמה יש ג\"כ במעשה המצות שהרי ארז\"ל בילקוט האזינו רמז תתקמ\"ה בשם פסיקתא בשעה שישראל עושין רש\"מ מוסיפים כח וגבורה שנא' ועתה יגדל נא כח אד' שע\"י מעשה המצות נעשה הגדלה בבחי' כח אד' וכתיב הבו גודל לאלקינו, תנו עוז לאלקים שישראל מוסיפין כח למעלה, וכן להיפוך ח\"ו בשעה שמכעיסי' אותו כביכול צור ילדך תשי, ובמד\"ר איכה בפסוק"],[2000560233,"ויצא מבת ציון, ר' עזרי' בשם ר\"י בר' סימון בזמן שישראל עושין רצוש\"מ מוסיפי' כח בגבורה של מעלה כמ\"ד באלקי' נעשה חיל (תילים ס') ובזמן שאין עושין רצוש\"מ כביכול מתישין כח שלמעלה דכתי' צור ילדך תשי (דברים ל\"ב), נמצא משמע מזה שמעשה המצות פועלים שינוי למעלה, ובמד\"ר בראשית ר\"פ מ\"ד משמע להיפוך דאיתא התם ע\"פ אמרת ה' צרופה (תהלים י\"ח ל\"א) וכי מה איכפת לי' להקב\"ה אם הוא שוחט ואוכל או נוחר ואוכל אם שוחט מן הצואר או מן העורף אלא שנתן הקב\"ה את המצות כדי לצרף בהם את הבריות הה\"ד אמרת ה' צרופה, וכן יש פסוקים ע\"ז בפירוש שנאמר אם צדקת מה תתן לו ורבו פשעיך מה תעשה לו, נמצא סותרים זא\"ז.\n<b>אך</b> הענין הוא דשניהם אמת, דהנה מה שע\"י המצות מוסיפים כח וגבורה הוא בבחי' ועל הכסא דמות כמראה אדם, כי אדם הוא בחי' ציור קוין שהוא בחי' רמ\"ח אברים דמלכא חח\"ן בג\"ה דת\"י, וע\"י המצות נעשה תוס' אורות כי רמ\"ח פקודין הם רמ\"ח אברין דמלכא, והיינו כמו שאבר ממשיך גילוי חיות הנפש שהוא כלי לגילוי חיות הנפש, כמו\"כ ע\"י המצות שעושים רש\"מ אזי ממשיכים גילוי אוא\"ס שיהי' אוא\"ס בבחי' גילוי בבחי' כמראה אדם, אבל כשמכעיסי' ח\"ו אזי אינו מאיר בהם אוא\"ס בבחי' גילוי רק בהעלם, וזהו שגלות נמשל לשינה וכמ\"ש עורה למה תישן הוי', והיינו כמו באדם למטה כשהוא ישן יש בו כל כחות הנפש ממש כמו שהוא ער רק שהם בו בהעלם שאינו מאיר בו בגילוי כחות הנפש הפנימי' כמו שכל ומדות, אבל כשהוא ער מאיר בו בגילוי השכל ומדות, כמו\"כ יובן למעלה שענין הגלות נמשל לשינה שאינו מאיר גילוי פנימי' אוא\"ס בבחי' ע\"ס, רק מה שצריך להיות לצורך קיום העולמות, אך זהו רק בבחי' כמראה אדם, אבל בעצמות אוא\"ס ממש שם כחשיכה כאורה שוין ואם צדקת כו', רק שכך עלה ברצונו שיומשך אוא\"ס ע\"י בחי' מעשה המצות. וזהו מ\"ש במדרש וכי מה איכפת לי' להקב\"ה כו' אלא שנתן המצות כדי לצרף בהם את הבריות, דהיינו שכך עלה ברצונו מצד כי חפץ חסד הוא.\n<b>ועפ\"ז</b> יובן ג\"כ מ\"ש כי אמרתי עולם חסד יבנה וכתי' כל הנקרא בשמי ולכבודי בראתיו, כל פועל ה' למענהו עשה, והיינו שמ\"ש כל פועל ה' למענהו עשה היינו בבחי' כבוד הנ\"ל שכל מה שברא לא ברא אלא לכבודו, כי כבוד הוא ל\"ב נ\"ח שהם התפשטות החיות בעולמות וכמ\"ש כולם בחכ' עשית, והנה בבחי' חכמה שהיא ראשית ההשתל' שם שייך גילוי והעלם, וע\"י מעשה התחתונים ממשיכי' גילוי אוא\"ס בבחי' חכ' וממילא נמשך למטה ג\"כ גילוי אוא\"ס, וזהו מ\"ש מלא כל הארץ כבודו שגילוי בחי' חכ' נמשך דוקא בארץ ע\"י מעשה המצות של תחתונים דוקא, ולכך המלאכים ביקשו את התורה ולא נתן להם לפי שעיקר גילוי בחי' ח\"ע אינו נמשך אלא דוקא בארץ ע\"י מעשה התחתונים דוקא וכמו שהשיב להם משה כלום יצה\"ר יש ביניכם כו', וזהו ענין כל פועל ה' למענהו עשה כו', אבל בעצמות אוא\"ס הוא רק"],[2000560234,"בחי' כי חפץ חסד הוא שכך עלה במח' ורצונו לעשות חסד לעולמות כו', וזהו מ\"ש כי אמרתי עולם חסד יבנה, שבריאת העולמות הי' מצד כי חפץ חסד הוא, אך מ\"מ כיון שכך עלה ברצונו שיהיו עולמות ע\"כ צריך לבנות את החסד, וזהו כפי פי' הב' שלעולם צריך להמשיך את החסד, והיינו מאחר שעלה ברצונו להטיב מצד טבע הטוב להטיב ונמשך בחי' זו מצד כי חפץ חסד בתחלת הבריאה, ואח\"כ צריכי' אנו להמשיך בחי' זו באתעדל\"ת אתעדל\"ע (הגם כי בעצם בחי' זו הוא למעלה מכדי שתוכל לפעול אתעדל\"ת של הנבראים אך ג\"ז הוא בחי' חפץ חסד מצד טבע הטוב להטיב לברואיו שיפעול אתעדל\"ת להמשיך בחי' אתעדל\"ע ממקום גבוה כזה והיינו מאחר שכבר עלה ברצונו כו'), וע\"י מה ממשיכי' את החסד הנ\"ל הוא ע\"י מה שהאדם עושה למטה צדקה וחסד שנותן לעני דלית לי' מגרמי' כלום. וזהו ג\"כ פי' הפסוק אם כסף תלוה את עמי רק גמ\"ח לחבירו בלי שום פני' לעצמו כלל, ועי\"ז נמשך מלמעלה ג\"כ בחי' חסד לעולמות בחי' כי אמרתי עולם חסד יבנה כו'.\nו) <b>ועתה</b> י\"ל פי' הפסוק אם כסף תלוה את עמי את העני עמך, דלכאו' תיבות את עמי מיותר, והנה איתא במדרש אם כסף תלוה את עמי עי\"ז את עמי בחירק, ולהבין פי' את עמי, הנה כתיב כי עמך מקור חיים פי' חיים היינו חיות של כל העולמות זהו בחי' חכמה וכמ\"ש והחכ' תחי' כו', ומקור חיים היינו למעלה גם מן החכ', ופי' עמך מקור חיים היינו שאפי' מקור חיים הוא ג\"כ טפל ובטל אך מ\"מ הוא עמך, והיינו מ\"ש עד שלא נבה\"ע הי' הוא ושמו בלבד שהי' האור נכלל במאור, והנה מקור חיים הנ\"ל נקרא מקור מים חיים ועז\"נ אותי עזבו מקור מים חיים, והנה בחי' מים הוא המשכה למטה כי מים יורדים כו' כנ\"ל, וזהו את עמי שעי\"ז ממשיכי' מקור מים חיים למטה, שהמקור מ\"ח הוא בחי' עמי כנ\"ל שהוא בחי' עד שלא נבה\"ע הי' הוא ושמו בלבד.\n<b>אך</b> ע\"י מה ממשיכים בחי' זו שהיא עמי זהו ע\"י את העני עמך כו', כי עני ועשיר הם כנגד שמשא וסיהרא, והנה סיהרא לית לה מגרמה כלום שאין לה אור בפ\"ע כלל רק שמקבלת האור מהשמש, ולכך יש לה שינויים שפעם הוא מלא ופעם הוא חסר, שבתחלת החדש היא חסירה ואח\"כ נתמלאה, והיינו לפי שמקבלת אור מהשמש, והמכוון מה שהסיהרא לית לה מגרמה כלום ושתהא צריכה לקבל אורה מהשמש דוקא, שעי\"ז היא בבחי' ביטול וכתיב ואל זה אביט אל עני ונכה רוח דוקא וכשהלבנה צריכה לקבל אורה מהשמש היא בטילה בתכלית הביטול ונעשית נקודה"],[2000560235,"חדא כנודע ונק' עני, וזהו שדהע\"ה אמר על עצמו כי עני ואביון אנכי, ולכאו' אינו מובן איך אמר דוד על עצמו כי עני ואביון אנכי הרי הי' מלך ישראל, אלא לפי שדוד הי' מרכבה לבחי' המל' שהיא בחי' ירח שהוא בחי' עני דלית לי' מגרמי' כלום ע\"כ אמר ע\"ע כי עני ואביון אנכי, והיינו שהי' בטל בתכלית הביטול ממש לאלקות לקבל גילוי אוא\"ס, וע\"כ משיח נקרא ג\"כ עני כמ\"ש עני ורוכב על החמור, והיינו לפי שהביטול הוא בחי' כלי לגילוי אוא\"ס וכמ\"ש מרום וקדוש אשכון את דכא ושפל רוח, וזהו שרש העניים מבחי' ירח שהוא בחי' עני. וזהו את העני עמך שיהי' בבחי' עני וכמו שפי' רש\"י ז\"ל הוי מסתכל בעצמך כאלו את עני. ובעבודה היינו בבחי' ביטול לאלקות עי\"ז ממשיך בחי' עמך היינו בחי' עמך מקור חיים הנ\"ל. וזהו מה שארז\"ל יאה עניותא לישראל דהיינו ההכנעה לפי שזהו הנין שהמקבל צריך להיות בתכלית הביטול. וע\"פ פשוט את העני עמך שישפיע לעני גמ\"ח כו', והנה כשהעשיר משפיע להעני עי\"ז גורם למעלה בחי' יחוד שמשא וסיהרא, שהוא בחי' יחוד הוי' ואלקי' דהיינו שעי\"ז נמשך בחי' גילוי שם הוי' שהוא בחי' שמש בשם אלקים שהוא בחי' ירח, והנה כתי' מלוה ה' חונן דל משמע מזה שאפילו בבחי' הוי' נמשך ג\"כ המשכה מלמעלה למטה בתוס' אור, וזהו מ\"ש והי' אור הלבנה כאור החמה שהוא יחוד סיהרא בשמשא עי\"ז נעשה אור החמה שבעתיים כאור שבעת הימים.\n<b>וזהו</b> מ\"ש אם כסף תלוה את העני עמך שנעשה יחוד שמשא בסיהרא והי' אור הלבנה כאור החמה עי\"ז את עמי שממשיכי' בחי' מה שהוא עמי והיינו אור החמה שבעתיים כאור שבעת הימים, דהיינו שנמשך מבחי' כי עמך מקור חיים שהוא בחי' עד שלא נבה\"ע הי' הוא ושמו בלבד, והענין הוא דהנה יש ב' בחי' הוי', וכמ\"ש ויקרא הוי' הוי' ופסיק טעמא בגווייהו, הא' הוא בחי' עד שלא נבה\"ע הי' הוא ושמו בלבד, והוי' הב' הוא בחי' הוי' שבהשתלשלות כו', ועי\"ז שנעשה יחוד משפיע ומקבל למטה עי\"ז נעשה ג\"כ למעלה שיהי' נמשך מבחי' הוי' הא' שלמעלה מבחי' השתלשלות היינו בחי' עד שלא נבה\"ע כו' לבחי' הוי' הב' שהוא בחי' אור החמה דעכשיו, וזהו מלוה ה' חונן דל שע\"י שחונן דל עי\"ז נמשך תוס' אור גם בבחי' ש' הוי' כו'. וזהו ג\"כ אם כסף תלוה את העני עמך עי\"ז ממשיך את עמי מה שהוא עמי היינו בחי' עד שלא נבה\"ע הי' הוא ושמו בלבד היינו האור כמו שהוא כלול במאור שז\"ע עמי כו'."],[2000560236,"<h3>והבריח התיכון כו'</h3>\n<b></b><b>בס\"ד. (ש\"פ תרומה, רכ\"ז).</b>\n<b></b>ויטע אשל כו' פונדק כו' תפלות כנגד תמידין - ד\"פ\n[תרומה]\n<b>והבריח</b> התיכון בתוך הקרשים מבריח מן הקצה אל הקצה, הנה איתא במד\"ר שהבריח התיכון הי' מהאשל שנטע אברהם אבינו בבאר שבע, דכתיב ויסע ישראל וכל אשר לו ויבא בארה שבע (ויגש מ\"ו א'), ואיתא ברבות ויגש פ' צ\"ד להיכן הלך א\"ר נחמן לקוץ ארזי' שנטע אברהם זקנו בבאר שבע המד\"א ויטע אשל (וירא ך\"א ל\"ג) וכן הוא ברבות שה\"ש בפסוק עד שהמלך במסיבו, והבריח התיכון הי' מהאשל כו', והוכיחו ג\"כ במד\"ר הנ\"ל מפסוק וכל אשר נמצא אתו עצי שטים, מצא לא נאמר אלא נמצא, מלמד שהיו מוצנעי' מימות יעקב אבינו. ולכאו' אינו מובן שהרי היו רד\"ו שנה במצרים וא\"כ איך היו מתקיימים עד זמן זה.\n<b>אך</b> הנה מתחלה י\"ל מ\"ש ויטע אשל בבאר שבע ואיתא בזה פלוגתא בגמ' סוטה דף יו\"ד סע\"א ח\"א אשל זה פונדק וח\"א אשל זה פרדס, וכ\"ה במד\"ר ג\"כ וירא ס\"פ נ\"ד, ופריך בגמ' בשלמא למ\"ד פרדס היינו דכתיב ויטע אשל אלא למ\"ד פונדק מאי ויטע ומשני הגמ' שגם בפונדק שייך ל' ויטע וכמ\"ש ויטע אהלו אפדנו. ולהבין ענין הנטיעה שעשה אברהם ע\"י הפונדק, היינו שע\"י שהאכיל והשקה כל העוברי' ושבים, וא\"ל ברכו למי שאכלתם משלו עי\"ז המשיך בחי' נטיעה למעלה, דהנה כתיב כי האדם עץ השדה, והנה בחי' אדם זהו מ\"ש ועל הכסא דמות כמראה אדם, והאדם זה הוא עץ השדה כי שדה הוא כמ\"ש ראה ריח בני כריח שדה אשר ברכו ה' (שהוא בחי' מל') והאדם הוא עץ השדה, שהוא בחי' אילנא דחיי עץ החיים עץ פרי (בחי' ז\"א), והנה אברהם עי\"ז שהאכיל והשקה למטה לכולם עי\"ז ויטע אשל שהמשיך עי\"ז בחי' האדם עץ השדה והיינו שהמשיך בחי' עץ החיים. וזהו מ\"ש בזהר פ' וירא דק\"ב ע\"ב וז\"ל ת\"ח כד חב אדם בעה\"ד טו\"ר חב דכתי' ומעץ הדעת כו' ואיהו בי' חב וגרם מותא לעלמא מה כתי' ועתה פן ישלח ידו ולקח גם מעה\"ח וגו' וכד אתא אברהם באילנא אחרא אתקין עלמא דהוא אילנא דחיי ואודי מהימנותא לכל בני עלמא עכ\"ל, והיינו שהאשל הי' תיקון עץ הדעת טו\"ר, לפי שהוא המשכה מבחי' עץ החיים כו', לכן הוא תיקון על בחי' עה\"ד. וזהו מ\"ש ויטע אשל שעשה למעלה בחי'"],[2000560237,"נטיעה זו דכי האדם עץ השדה. והנה במד\"ר שם אמרו לפי ב' הדיעות דפונדק ופרדס שאשל הוא ג\"כ לשון שאל, שאל מה תשאל, והיינו שאמר לכאו\"א שאל מה מבוקשך ומילא חסרון של כאו\"א.\nב) <b>ולהבין</b> כ\"ז, יש להבין מקודם פי' הא' שאשל הוא פונדק, ולהבין זה למעלה, הנה ארז\"ל רעייתי פרנסתי ישראל מפרנסין לאביהם שבשמים. ולכאורה אינו מובן זה איך שייך לומר ישראל מפרנסין לאביהם שבשמים אך הענין הוא דהנה ארז\"ל (ברכות ך\"ו) ריב\"ל אומר תפלות כנגד תמידים תקנום, והנה אנו רואים שענין הקרבת הקרבן הוא שעי\"ז היו מעוררים למעלה את המרכבה העליונה דהנה הקרבן עצמו הי' מבחי' פני שור, כי שרש נפש הבהמה הוא מבחי' פני שור שבמרכבה, והאש שלמעלה שהי' יורד בדמות ארי' הוא בחי' פני ארי' שבמרכבה דאכיל קורבנין, שהוא בחי' לאכללא שמאלא בימינא ע' בלק\"ת בד\"ה וארי' כבקר, ובזח\"א בהקדמה ד\"ו ע\"ב, והאדם המקריב את הקרבן הוא מבחי' פני אדם שבמרכבה, ואם היו מקריבין קרבן עוף שרשו מבחי' פני נשר כו', נמצא שבהקרבת הקרבן הי' מתעורר למעלה כל המרכבה העליונה.\n<b>וזהו</b> מ\"ש בזהר פ' פנחס דרמ\"א ע\"א ואתהניין מיסודא ועיקרא דילהון, ולכאו' אינו מובן זה כלל מה אתהניין כ\"כ עי\"ז שמקריבין נפש הבהמה ועולה לשרשו כיון ששרש הבהמה נמשך מבחי' המרכבה, וגם זה ע\"י ריבוי רבבות מדרגות השתלשלות עד שנמשך נפש הבהמה, והוא ע\"ד שארז\"ל אין לך עשב מלמטה שאין לו מזל מלמעלה המכה בו ואומר לו גדל שבודאי אין ערך העשב לגבי המזל המכה בו רק שע\"י רבוי השתלשלו' נמשך מבחי' המזל שיצמח העשב הגשמי, וכמו\"כ אין ערך נפש הבהמה גשמי' לגבי בחי' פני שור שבמרכבה רק שע\"י רבוא רבבות מדרגות נמשך ונשתלשל נפש הבהמה מבחי' פני שור, וע' בד\"ה אם כסף תלוה (ך\"ז), וא\"כ מהו ענין ואתהניין שאמרו בזהר מהו ההנאה כ\"כ מהעלאת נפש הבהמה לשרשו כו'. אך הענין הוא דהנה מה שנפש הבהמה נשתלשל מבחי' פני שור זהו רק הנפש שלה שנמשך ע\"י רבוי השתלשלות שיהי' מחי' את הבהמה ג\"כ, משא\"כ גוף הבהמה גשמי' א\"א להיות נמשך ע\"י השתלשלות כי גם ע\"י כמה רבוא רבבות השתל' מדרגות א\"א להיות נמשך שיתהוה גוף הבהמה גשמי' כי מרוחני' א\"א להיות"],[2000560238,"נמשך גשמי' כו', ומה שנתהווה גוף הבהמה גשמי' זהו ע\"י בחי' סוכ\"ע שהוא כל יכול, ע' בד\"ה ביום השמע\"צ סובב וממלא שלא נדפס, ורק נפש הבהמה נמשך בבחי' השתלשלו' מבחי' פני שור שבמרכבה, ולכך ע\"י הקרבן שמקריבין הבהמה ע\"ג המזבח כשמתעלה הבהמה למעלה לשרשה עי\"ז נעשה למעלה עלי' גם לבחי' פני שור כו' שהוא שרש שרשה כו', לפי שיש בכח הבהמה המשכה מבחי' סוכ\"ע שהוא גוף הבהמה המתהוה מבחי' סוכ\"ע דוקא.\n<b>ועוד</b> לפי שכשנמצא הבהמה למטה זהו ע\"י נפילה ושבירה שהוא מבחי' עולם התהו שהיו שם ריבוי האורות ונפלו בשבירה, ונמצא שכשנתעלה נפש הבהמה למעלה עי\"ז נעשה הנאה גם לשרש שרשה בחי' פני שור שבמרכבה לפי ששרשה מעולם התהו שהי' שם ריבוי אורות. וזהו ע\"ד כמו שאנו רואים שהאדם מקבל חיות מהמאכל אף שהאדם הוא למעלה במדרגה מבחי' המאכל, שהמאכל הוא צומח והאדם הוא מדבר ואעפ\"כ הוא מקבל חיות דוקא מהמאכל, והיינו לפי שיש בהמאכל ניצוץ אלקי גבוה מבחי' ניצוץ האדם וע\"כ הוא מחי' את האדם וכמ\"ש כי לא על הלחם לבדו יחי' האדם כי על כל מוצא פי הוי' יחי' האדם דהיינו מוצא פי הוי' שבמאכל שהוא בחי' מאמר תדשא האדץ דשא, והגם שבהאדם יש ג\"כ מוצא פי הוי' הוא מאמר נעשה אדם כו', אך לפי שהמוצא פי הוי' שבלחם הוא למעלה מבחי' מוצא פי הוי' שבאדם, לפי שהמאכל הוא מה שנפל בשבירה וע\"כ שרשו מעולם התהו שקדם לתיקון, וע\"כ יש בכח המאכל להחיות את האדם. וכך לפי ששרש נפש הבהמה הוא ממה שנפל בשבירה ושרשה מעולם התהו שקדם לתיקון, לכן הקרבת הבהמה שמתעלה לשרשה היא נעשית בחי' מאכל לשורשה בחי' המרכבה, וכמו המאכל שמחי' את האדם כמו\"כ הקרבת הבהמה היא בחי' לחם להמרכבה עליונה שז\"ע לחמי לאשי הם השרפי' בחי' המרכבה העליונה, ע' בד\"ה אם כסף (ך\"ז), ומה גם שהתהוות גוף הבהמה גשמי' הוא מבחי' סוכ\"ע כל יכול, וכמ\"ש באגה\"ק סד\"ה איהו וחיוהי שדקדק לשון הזהר ואתהניין מיסודא ועיקרא דילהון ופי' הטעם מפני שהוא בחי' אור חוזר מלמטלמ\"ע מתחתית העשי' שמתגלית שם ביתר שאת מבחי'"],[2000560239,"סוכ\"ע ומסיום הקו כו', וע\"כ עי\"ז שמקריבין הבהמה גשמי' ע\"ג המזבח עי\"ז אתהניין מעיקרא ושרשא דילהון (ופי' מעיקרא ושרשא דילהון כי חיות המרכבה הם ג\"כ מבחי' התהו והיינו ממה שנתברר מבחי' התהו כמ\"ש במ\"א ולכן הם בחי' בהמות וחיות כו' כמ\"ש במ\"א), ועי\"ז נעשה והחיות נושאות את הכסא דהיינו האדם שעל הכסא לבחי' עצמות אוא\"ס שלא אדם הוא כו'.\nג) <b>והנה</b> עכשיו תפלות כנגד תמידין תקנו א\"כ יש בתפלה ג\"כ בחי' העלאת המרכבה, והענין הוא דהנה תפלה הוא כדי להפוך ולהעלות את נה\"ב כמו שהיו מעלין הבהמה ע\"ג המזבח, כמו\"כ העבודה הוא להעלות את נה\"ב ג\"כ, ששרש נה\"ב הוא ג\"כ מבחי' פני שור שבמרכבה רק שהוא מבחי' פני אדם שבפני שור, וארי' דאכיל קרבנין זהו אהבה הבאה מלמעלה, כי אריה הוא אור י\"ה דהיינו אהבה הבאה מלמעלה, ובחי' פני אדם זהו\"ע בחי' דעת שמעמיק דעת בהתבוננות גדולת אוא\"ס ב\"ה כי אדם הוא מבחי' דעת, ובחי' נשר זהו\"ע התעוררות רחמים שמעורר רחמים רבים על נה\"א שז\"ע מה שאנו אומרים ברחמיך הרבים רחם עלינו וכן אבינו אב הרחמן המרחם כו' וכדומה וכמ\"ש כנשר יעיר קנו כו', ונמצא שיש בבחי' תפלה ג\"כ בחי' מרכבה עליונה.\n<b>והנה</b> ענין בחי' הדעת שזהו כנגד בחי' פני אדם כנ\"ל זהו\"ע התבוננות שבק\"ש שמע ישראל הוי' אלקינו הוי' אחד, אחד פי' בזהר אנת הוא חד ולא בחושבן, ופי' ולא בחושבן היינו שאין ערוך אליו כלל כי חשבון הוא בחי' ערך כמו למשל א' לגבי אלף הוא ערך אחד כמו אלף לגבי אלף פעמים אלף אפי' א' לגבי אלף אלפי אלפים הוא ג\"כ ערך, ואפי' טפה בים אוקיינוס נק' ג\"כ ערך לפי שיכולים לשער כמה טפות יש בים כמו שאמר ר\"י יכולני לשער כמה טיפות יש בים, וע\"כ כיון שהוא בגדר חשבון הוא בבחי' ערך, משא\"כ עצמות אוא\"ס הוא אנת הוא חד ולא בחושבן שאינו בבחי' ערך כלל, כי זה מה שהוא בגדר חשבון וערך זהו רק בבחי' השתל' לבד, כמו עד\"מ נפש הבהמה שנשתלשלה מבחי' פני שור שבמרכבה אף שהוא ריחוק הערך מאד כנ\"ל מ\"מ הוא בבחי' ערך לפי שעכ\"פ נשתלשל מבחי' פני שור"],[2000560240,"נפש הבהמה וכן אפי' אצי' לגבי בריאה אף שהם רחוקים מאד לפי שאצי' הוא בבחי' איהו וחיוהי חד איהו וגרמוהי חד מ\"מ הם בבחי' ערך לפי שמחכ' דאצי' אף שהיא בחי' חכים ולא בחכ' ידיעא, וחכ' דבריאה הוא בבחי' חכמה ידיעא, מ\"מ מבחי' חכ' דאצי' נתהוה חכ' דבריאה וע\"כ הוא בבחי' ערך, משא\"כ עצמות אוא\"ס אין ערוך אליו כלל וכמ\"ש אין ערוך אליך כי מי בשחק יערוך לה' (וע' בת\"א בד\"ה פתח אלי' מבאר היטב ההפרש בין התהוות חכ' דבריאה מחכ' דאצי' ובין התהוות חכ' דאצי' מבחי' הכתר, וע\"ש בדף ך\"ד ע\"ג וז\"ל שחכ' דאצי' היא במהותה ועצמותה בפו\"מ המתלבשת בבחי' הפרסא וגורמת התהוות חכ' דבריאה כו', הרי חכ' דבריאה אע\"פ שהיא אור חדש מ\"מ כבר יש לה איזהו ערך ויחוס עם חכ' דאצי', משא\"כ בחי' צמצום אוא\"ס להיות אצי' היינו התעלמות האור והעדרו עד שאינו עולה בשם כלל כנ\"ל ולכן נק' חד ולא בחושבן עכ\"ל, ולכן) אפי' אצי' אין ערוך אליו כלל, כי אצי' הוא רק הפרשת הארה בעלמא וכמ\"ש במשה ויאצל מן הרוח אשר עליו על ע' זקנים שהוא רק הפרשת הארה כו', וע\"כ אין ערוך אליו כלל יותר משאין ערך טפה בים אוקיינוס. והנה כשמעמיק דעת בזה עי\"ז נעשה לו צמאון ותשוקה לעצמות אוא\"ס ולא יחפוץ בשום דבר כיון שהכל הם אין ערוך לך כלל ואפי' לא כטפה א' לבד ג\"כ וכמ\"ש מי לי בשמים ועמך לא חפצתי בארץ שלא יהי' לו שום חפץ ורצון לא בג\"ע התחתון ולא בג\"ע העליון שז\"ע שמים וארץ כ\"א לו לבדו. והנה חפץ הוא בחי' פנימי' הרצון כי רצון הוא רק חיצוני' לבד וכמשארז\"ל כופין אותו עד שיאמר רוצה אני שאף שהוא ע\"י כפי' נק' רצון כו', משא\"כ חפץ הוא בחי' רצון פנימי בבחי' אהבה וחשק וכמ\"ש רק באבותיך חשק ה'. וזהו שאנו מאריכין ואומרים אמת ויציב ונכון וקיים כו' ונחמד ונעים כו' והיינו כדי שיגדל ויתאמת האהבה לה' בבחי' פנימי' הרצון והחשק כו'. והנה עי\"ז גם נה\"ב נכלל ג\"כ באש אהבה זו ונכלל לה' בבחי' אהבה בכל לבבך בשני יצריך, שמצד אריכות ההתבוננות גם הנה\"ב יסכים לזה ג\"כ כו', וזהו\"ע המרכבה שבתפלה כו'.\n<b>וזהו</b> מ\"ש רכב אלקי' רבותיים אלפי שנאן, שנאן הוא בחי' שור נשר ארי' אדם (כי נו\"ן פשוטה הוא בחי' אדם כמ\"ש בזהר בראשית די\"ח סע\"ב נו\"ן פשוטה, נו\"ן דא איהו אדם, פשיטו דאתכליל כחדא ברזא דכר ונוקבא, וכ\"ה בזהר פ' עקב דרע\"ד א', ובזהר פ' בהעלותך דקנ\"ח ע\"א נו\"ן פשוטה כללא דדכר ונוקבא), וזהו מ\"ש והניף את קרבנו לפני הוי' שהעלאת הקרבן מגיע לפני הוי' לעצמותו ומהותו כו', וע\"י העלאה זו נמשך אח\"כ המשכה בשם הוי' שז\"ע מ\"ש ריח ניחוח להוי' ריח הוא בחי' העלאה ועי\"ז ניחוח להוי' המשכה בבחי' שם הוי'. וזהו ג\"כ מ\"ש רז\"ל (זבחים פ\"ה) העולה קדש קדשים, לפי שעולה למעלה בבחי' עצמות אוא\"ס ממש. וזהו שארז\"ל"],[2000560241,"רעייתי פרנסתי ישראל מפרנסין לאביהם שבשמים, והיינו כי שמים הוא בחי' אש ומים בחי' מדות, ואביהם שבשמים הוא בחי' חכמה כי חכ' נק' אבא שרש כל האצי', וישראל ממשיכי' בבחי' חכ' ומדות, וז\"ע ויטע אשל כי האדם עץ השדה.\n<b>והנה</b> בתורה יש ג\"כ בחי' זו וכמשארז\"ל (מנחות דק\"י ע\"א) אמר ר' לקיש מאי דכתיב זאת התורה לעולה כו' (צו ז' ל\"ב) כל העוסק בתורת עולה כאלו הקריב עולה, והיינו לפי שתורה נק' ג\"כ אדם וכמ\"ש זאת התורה אדם, וזהו\"ע רמ\"ח מ\"ע שהוא רמ\"ח אברין דמלכא בחי' אדם, וע\"י התורה נמשך המשכה זו ג\"כ כי ישראל מתקשראן באורייתא ואורייתא בקודב\"ה, והיינו לפי שכדי שיומשך המשכה מאוא\"ס ויוכלו לקבל הוצרך להיות נמשך בבחי' כמראה אדם כדי שיוכל לקבל, וע\"כ נמשך המשכה זו בבחי' תורה שנק' אדם כו', וזהו שהתורה נק' לחם וכמ\"ש לכו לחמו בלחמי דהיינו שמחבר אוא\"ס עם נש\"י כמו שהלחם מחבר הנשמה עם הגוף כמו\"כ התורה מחבר אוא\"ס עם נש\"י וישראל מתקשראן באורייתא ואורייתא בקודב\"ה. וזהו ויטע אשל שע\"י אכילה ושתיה שהאכיל והשקה אברהם למטה עי\"ז ויטע אשל שהמשיך בבחי' כמראה אדם כי האדם עץ השדה.\n<b>והנה</b> האשל זה בעבודה ישנו ג\"כ בק\"ש, דהנה בק\"ש עם ג' תיבות ה' אלקיכם אמת יש רמ\"ח תיבין שהוא בחי' רמ\"ח אברין של אדם העליון שעל הכסא, ולבד הג' תיבות הנ\"ל יש רמ\"ה תיבות וז\"ע אשל ברמ\"ה. וגם י\"ל שג' פרשיות דק\"ש הם כנגד בחי' ראש גוף ורגל שישנם באדם כו', והנה בק\"ש יש שבעה ברכות וכמ\"ש שבע ביום הללתיך שהו\"ע שבע ברכות דק\"ש בשחר מברך שתים לפניה ואחת לאחריה, ובערב מברך שתים לפניה ושתים לאחריה, וזהו ענין באר שבע כו' ששם נטע את האשל, ונמצא שהאשל יש ג\"כ בק\"ש כו'.\nד) <b>ומעתה</b> צ\"ל מ\"ש במד\"ר שאשל הוא ל' שאל, והענין הוא דהנה כתיב כי שאל נא לימים ראשונים, והנה ימים ראשונים הוא בחי' ששת ימי בראשית"],[2000560242,"שנקראים ימים ראשונים וכמ\"ש וערבה לה' מנחת יהודה וירושלים כימי עולם וכשנים קדמוניות, והיינו לפי שששת ימי בראשית נמשכים מבחי' חכמה וכמ\"ש בראשית ברא ות\"י בחוכמתא ברא. וביאור הענין יובן ע\"פ מה שארז\"ל במד\"ר כל תולדת שבמקרא חסר חוץ מאלה תולדות השמים והארץ ואלה תולדות פרץ, והיינו שעולם על מלואו נברא דהיינו שמתחלה הי' מאיר גילוי אוא\"ס וכמשארז\"ל עיקר שכינה בתחתונים היתה, וז\"ע אור שבעת הימים, וזהו משארז\"ל אור שנברא ביום ראשון הי' אדם מביט בו מסוף העולם ועד סופו, רק אח\"כ ע\"י חטא עה\"ד נחסר כו', אך אלה תולדות פרץ הוא ג\"כ מלא לפי שתולדות פרץ קאי על לע\"ל שאז יאיר ג\"כ גילוי אא\"ס כמו בששת ימי בראשית וכמ\"ש והי' אור הלבנה כאור החמה כו' ואור החמה יהי' שבעתיים כאור שבעת הימים ולכך הוא מלא, וע\"כ נקראים ששת ימי בראשית ימים ראשונים ימי קדם לפי שאז הי' מאיר גילוי אלקות בעולם.\n<b>ועפ\"ז</b> יובן מה שהי' ברה\"ע בששה ימים, דלכאו' אינו מובן למה נבה\"ע בששת ימים, ואף שהי' צריך שיהי' נברא בעשרה מאמרות וכמו שארז\"ל באבות פ\"ה והלא במאמר אחד יכול להבראות אלא כדי להפרע כו' וליתן שכר טוב כו', אעפ\"כ הי' יכול לברוא העולם בע\"מ ביום אחד, ולמה הי' צריך שיהי' נברא בששת ימים דוקא, והענין הוא דלכך נברא בששת ימים כדי שיהי' אח\"כ בחי' שבת שאם לא הי' נברא בששת ימים לא הי' מדרגת השבת שהו\"ע כי בו שבת, ע' בד\"ה זכור את יום השבת לקדשו (ך\"ז), וכדי שיהי' בחי' השבת ע\"כ נברא בששת ימים כו'. ועוד י\"ל דלכך נברא בששת ימים, דהנה עולם הוא בחי' מקום, והנה מקום כולל ששה קצוות מעלה ומטה מזרח ומערב צפון ודרום, והנה שרש הו\"ק אלו הוא מבחי' ששה קצוות עליונים בחי' ששה מדות כו' לך ה' הגדולה והגבורה, וע\"כ נברא בששת ימים לפי שבכל יום הי' מאיר מדה אחת שבה נברא כו'.\n<b>והנה</b> בתחלה היו מאירים הששה מדות בגילוי, וז\"ע תולדות מלא כי העולם על מלואו נברא, ואח\"כ ע\"י חטא עה\"ד נעשה תולדת חסר וי\"ו שאינם מאירים הששה מדות בגילוי, ונעשו ששת ימי החול בחי' חולין, והעבודה היא להמשיך מבחי' ימים ראשונים בגילוי שיהי' מאיר הששה מדות בגילוי גם למטה. וזהו משארז\"ל כד אמליכתי' למעלה ולמטה ולד' רוחות תו לא צריכת, שצריך להמשיך למטה גם בבחי' ז' רקיעים וארץ גשמיי' שיהי' ג\"כ בבחי' אחד בבחי' ביטול לאלקו', וכמ\"ש הנה מקום אתי שהמקום הוא בטל בתכלית לאלקות וכמשארז\"ל הוא מקומו של עולם ואין העולם מקומו שהמקום הוא בטל לאלקות, והיינו לפי שמאיר המדות"],[2000560243,"בגילוי גם למטה. והנה המדות הם למעלה בבחי' ביטול ממש וכמ\"ש לך הוי' הגדולה והגבורה שהם בבחי' ביטול, וע\"כ כשנמשכים המדות למטה בבחי' גילוי ע\"כ נעשה גם למטה בבחי' מקום גשמי בחי' ביטול ונעשו חולין על טהרת הקדש וכמו שמצינו שר' יוחנן בן גודגדא הי' אוכל על טהרת הקדש כל ימיו, דהיינו שהחולין נעשו ג\"כ בחי' קדש לפי שהמשיך בהם ע\"י זהירותו מבחי' קדש ע\"כ נעשו ג\"כ החולין על טהרת הקדש. וזהו מ\"ש כי שאל נא לימים ראשונים שצריך להמשיך מבחי' ימים ראשונים שיאירו למטה כמו קודם החטא כו'. וזהו מ\"ש באברהם ויטע אשל, כי אברהם התחיל להאיר כמ\"ש רז\"ל ע\"פ מי העיר ממזרח, ואשל הוא שאל, דהיינו שאברהם ע\"י שהאכיל והשקה לבריות עי\"ז המשיך מבחי' שאל נא לימים ראשונים דהיינו שהמשיך מבחי' ימים ראשונים שהיו מאירים בשי\"ב.\n<b>אך</b> הנה כתיב כי שאל נא לימים ראשונים כו' הנהי' כדבר הגדול הזה או הנשמע כמוהו השמע עם קול אלקי' חיים מדבר מתוך האש כמונו ויחי, נמצא שמשמע מזה שמ\"ת גבוה הרבה מבחי' ימים ראשונים, והיינו לפי שהתורה שרשה למעלה מבחי' מדות וכמ\"ש ואהי' אצלו שעשועים יום יום שהתורה קדמה לעולם אלפים שנה, כי עולם הוא מבחי' מדות ימים ראשונים וכמ\"ש כי אמרתי עולם חסד יבנה, ע' בד\"ה אם כסף, משא\"כ התורה קדמה לעולם דהיינו שהתורה נמשכה מבחי' חו\"ב וכמ\"ש אאלפך חכ' אאלפך בינה כי אורייתא מח\"ע נפקת, והיינו לפי שבמ\"ת הוצרך להיות שיהי' נמשך ממקום גבוה מאד לפי שכדי שע\"י מצות גשמי' [יהיו] יכולים להמשיך למטה גילוי אלקות הוצרך להיות נמשך ממקום גבוה שלמעלה מסדר ההשתל', כי מה שאברהם המשיך מבחי' ימים ראשונים זהו ע\"י שהי' בחי' מרכבה לאלקו' והי' בטל בתכלית הביטול לאלקו', ואף שהמשיך ע\"י צדקה וגמ\"ח שעשה, מ\"מ עיקר ההמשכה הי' ע\"י כוונתו והביטול שלו, כי קיים אברהם אבינו את כל התורה כולה עד שלא ניתנה, אך כ\"ז ברוחני' ע\"י עובדות ולא ע\"י מצות גשמי', וע\"כ ההמשכה והגילוי שהמשיך זהו רק למעלה שהמשיך למעלה בחי' תוס' אורות. וזהו ויטע אשל בבאר שבע, באר הוא בחי' מל' שהוא מקור לז' היכלות דבריאה, או י\"ל דלכך נק' המל' באר שבע לפי שהמל' מקבל מבחי' שבע ז' מדות. אך כדי שיומשך למטה דוקא זהו ע\"י מצות גשמי' וכדי שיומשך ע\"י מצוה גשמי' הוצרך להיות נמשך ממקום גבוה שלמעלה מגדר השתל' מבחי' אנכי כו'.\n<b>וזהו\"ע</b> שיעקב נטל את האשל ועשה ממנו בריח התיכון, דהיינו מה שהמשיך אברהם רק מבחי' שאל נא לימים ראשונים ויעקב נטלו עמו למצרים וישראל עשו ממנו בריח התיכון המבריח מן הקצה אל הקצה, דהיינו מקצה העליון"],[2000560244,"דכתר עד קצה התחתון שנמשך למטה ג\"כ, כי זהו ע\"י מצוה מעשיות, ששרש המשכה זו היא מבחי' אנכי שגבוה מאד נעלה מבחי' ימים ראשונים, ולכן יכול להיות נמשך למטה יותר, וזהו כדוגמא ששבת בראשית הוא למעלה מבחי' שי\"ב שהיו מאירים בשעת בריאת העולם, וכך התורה היא למעלה מבחי' ימים ראשונים, ולכך התורה ניתנה בשבת דוקא כמארז\"ל דכ\"ע בשבת ניתנה תורה כו', אך הנה כ\"ז הי' לפי שיעקב נטל את הארזים למצרים, והיינו שע\"י מצרים דוקא שהוא בחי' מצרים וגבולים, ובעבודה הוא בחי' מיצר וגבול של נה\"ב, ואעפי\"כ נעשה אח\"כ יצ\"מ דהיינו לברר ולהפוך את נה\"ב בבחי' אתכפיא ואתהפכא מחשוכא לנהורא, עי\"ז נעשה אח\"כ בריח התיכון בתוך הקרשים המבריח מן הקצה אל הקצה שיומשך למטה ג\"כ בחי' גילוי אלקות שלמעלה אפי' מבחי' ימים ראשונים כנ\"ל."],[2000560245,"<h3>ועשית ציץ כו'</h3>\n<b></b><b>בס\"ד. (ש\"פ תצוה, רכ\"ז).</b>\nציץ ב' פירושים - ד\"פ\n[תצוה]\n<b>ועשית</b> ציץ זהב טהור כו', פי' ציץ יש בו ב' פירושים, הא' לשון הארה כמו נץ החמה, יציץ נזרו, יציץ ופרח ישראל שהוא מלשון הארה כו'. הב' מלשון הבטה וראי' מלשון מציץ מן החרכים, וכמו שפרש\"י על מציץ ל' הבטה ע\"ד מ\"ש ראה ראיתי את עני עמי כו'.\n<b>ולהבין</b> ב' הפירושים צ\"ל תחלה פי' הא' שהוא לשון הארה, הנה הציץ הי' אהרן נושא אותו על מצחו, והנה אהרן הי' אחד מז' רועים שהיו מפרנסים נש\"י"],[2000560246,"והיינו שאהרן המשיך בחי' אהבה רבה לנש\"י. והגם שארז\"ל הכל בידי שמים חוץ מיראת שמים א\"כ אהוי\"ר תלוי' הם בעבודת האדם מלמטלמ\"ע. אך הנה באמת יש שני בחי' אהוי\"ר, הא' הוא בחי' אהוי\"ר מלמטלמ\"ע הב' הוא בחי' אהוי\"ר הבאה לאדם מלמעלה למטה (בבחי' מתנה) וכמ\"ש אהבתי אתכם אמר הוי', ובחי' אהוי\"ר שמלמעלמ\"ט זהו בחי' המשכת אהרן כו'. וזהו מ\"ש בזהר שיש ד' בחי' דחילו ורחימו, ורחימו ודחילו כנגד ד' אותיות הוי', והיינו כנ\"ל שבחי' דחילו ורחימו הוא בחי' אהוי\"ר הבאה בעבודת האדם מלמטלמ\"ע והוא בחי' ו\"ה, ובחי' רחימו ודחילו הוא בחי' אהוי\"ר הבאה מלמעלמ\"ט בחי' י\"ה, ובחי' אהבה זו הבאה מלמעלמ\"ט זהו בחי' אה\"ר שממשיך אהרן כה\"ג לנש\"י, אך א\"א לבוא לבחי' אה\"ר הבאה מלמעלה כ\"א שיהי' לו תחלה בחי' אהוי\"ר מלמטלמ\"ע ואז יוכל לקבל בחי' אהוי\"ר הבאה מלמעלה, וזהו ציץ ל' הארה והיינו שהוא בחי' הארת אור האה\"ר הבאה מלמעלמ\"ט.\n<b>והפי'</b> הב' הוא ציץ מל' מציץ, מציץ מן החרכים ל' הבטה, הנה כתיב כי עין בעין יראו (ישעי' נ\"ב ח') וכתי' כי עין בעין נראה (שלח י\"ד י\"ד) נראה אותיות אהרן, והיינו כי אהרן ממשיך בחי' כי עין בעין. והענין הוא דהנה הבריאה יש מאין והיינו לפי שמלכותך מלכות כל עולמים וכמ\"ש כי בי\"ה הוי' צור עולמים וארז\"ל ביו\"ד נברא העוה\"ב ובה' נברא העוה\"ז שהוא רק משני אותיות, וכמשל ענין המלוכה הוא רק מלך שמו נקרא עליהם, וזהו שאנו אומרים ישתבח שמך והיינו בחי' מל' כי המקור לכל התהוות הנבראים הוא מבחי' המל' וזהו מ\"ש לכו חזו מפעלות אלקים אשר שם שמות א\"ת שמות אלא שמות שהכל נברא רק מבחי' שם והארה, ולכן הוא בחי' יש מאין שנתהווה העולם ליש ודבר מבחי' אין. אך הנה כתיב כי אל דעות הוי' שיש ב' דעות ד\"ת וד\"ע והיינו כי ד\"ת הוא כנ\"ל שלמטה היש ולמעלה האין, וד\"ע הוא בהיפוך שלמעלה הוא היש האמיתי ולמטה הוא בחי' אין, ובאמת צ\"ל איך שייך לומר שהעולם וכל הנבראים המה בחי' אין הלא אנו רואים שלמטה הוא בחי' יש כו', אך הענין הוא מאחר ששרש ומקור בחי' הנבראי' הוא בחי' אין בחי' שם והארה כנ\"ל שאינו תופס מקום כלל דבאמת כולא קמי' כלא חשיב, א\"כ מה שנברא ונראה העולם ליש ודבר אינו שהוא באמת יש ודבר כי הלא גם מקור המהוה בחי' זו"],[2000560247,"הוא ג\"כ רק בחי' אין, כ\"א המכוון הוא שהגם שנראה העולם לבחי' יש אעפ\"כ יהי' בחי' ביטול היש לאין, מחמת ההתבוננות איך שמקורה ושרשה הוא רק הארה בעלמא בחי' אין, והרי הוא רק כמו ערך שם האדם לגבי עצמותו שאינו בערך כלל, וממילא ההתהוות שנתהוה מבחי' הארה זו לא יתכן שיהי' בבחי' יש יותר מן בחי' זו עצמה המהוה אותה, ודי לבא מן הדין להיות כנדון, א\"כ אין זה אלא מחמת ההסתר שהוא ית' אל מסתתר להיות נראה ליש ודבר, אבל צריך להבין שבאמת בטל היש לאין, וכענין וכל צבא השמים לך משתחוים, ואח\"כ יוכל להשיג בחי' דיעה עליונה איך דכולא קמי' כל\"ח וכל מה שהוא קמי' יותר כלא חשיב יותר בבחי' ביטול, וזהו כי עין בעין נראה אותיות אהרן כי אהרן ממשיך שיומשך בחי' עין דלעילא בחי' ד\"ע בעין דלתתא בחי' ד\"ת כו'. וזהו ציץ לשון הבטה וכמו שפרש\"י מציץ ל' ראה ראיתי כו' בחי' ראי' והיינו בחי' ראי' דדעת עליון.\n<b>ובאמת</b> ב' הפירושי' של ציץ הוא אחד, דהיינו כשיש בחי' ד\"ת היינו בחי' ביטול היש לאין שהוא בחי' אהוי\"ר הבאה מלמטלמ\"ע אזי נמשך ע\"י אהרן כהנא רבא בחי' אה\"ר להיות עין בעין שיאיר בחי' עין דלעילא בעין דלתתא, וזהו בחי' אה\"ר הבאה מלמעלה בבחי' מתנה וכמ\"ש עבודת מתנה אתן כו'.\nב) <b>והנה</b> כמו\"כ יש ב' בחי' אלו בתפלה, כי הנה תחלה הוא בחי' שמע, שם עי\"ן, פי' עי\"ן הוא ז' מדות כשהם כלולים מיו\"ד, ושם עי\"ן הוא בחי' הארה מעי\"ן דהיינו בחי' מל' שהוא בחי' אין שממנו נברא העולם ליש כו', וזהו שמקדימין פסוד\"ז דהיינו איך שהמלאכים וכל צבא השמים אומרים שירה ובטלים לפניו ית' שזהו מ\"ש הללוי' הללו את ה' מן השמים יהללו את שם ה' כי הוא צוה ונבראו כו', וזהו שאומרים עשר פעמים הללוי' נגד עשרה מאמרות, בכדי להתבונן כנ\"ל שכל צבא השמים המה בטלים, ואזי גם הוא יוכל לבא לבחי' ביטול היש שזהו ההתבוננות בבחי' שמע שם עי\"ן בחי' ביטול היש ד\"ת. ואח\"כ בחי' ישראל הוא למעלה מבחי' ד\"ת ע\"ד מ\"ש בן פורת יוסף בן פורת עלי עין למעלה מבחי' עי\"ן דדעת תחתון, ואח\"כ ע\"י ההתבוננות בבחי' ה' אלקינו ה' אחד הוא בחי' ד\"ע איך דכולא קמי' כלא חשיב, וזהו בחי' אחד שהוא ז' רקיעים וארץ עכ\"ז כולא קמי' כלא חשיב ובטלי' לגבי בחי' אל\"ף בחי' אלופו של עולם שהוא היש האמיתי כו', וכאשר מתחלה יש בחי' ד\"ת ביטול היש דהיינו בחי' יחו\"ת, אזי יוכל לבוא לבחי' ד\"ע בחי' יחו\"ע.\n<b>ועפ\"ז</b> יובן ענין חטא דור המדבר במה שאמרו היש הוי' בקרבינו אם אין, וארז\"ל במד\"ר ובילקוט רמז רס\"ב משל לבן שהי' מורכב על כתפו של אביו ושאל"],[2000560248,"איה אבא כו' השליך האב את הבן בא הכלב ונשכו, כך הקב\"ה הוציא את בנ\"י ממצרים ושאלו היש הוי' השליך אותם מיד ויבא עמלק. ולהבין ענין החטא שלהם, הענין הוא דהחטא שלהם הי' מה שלא האמינו שנבואת משה הי' גבוה משאר הנביאים (כמו אפי' אברהם יצחק ויעקב), ובאמת כתיב וארא אל אברהם כו' באל שדי ושמי הוי' לא נודעתי, ופי' הרמב\"ן שם שדי הוא מקור לנסים מוסתרים אכן שם הוי' הוא מקור לנסים הנגלים ולהם הראו נסים נגלים כמו יצ\"מ וקרי\"ס שהם נסים בגילוי, א\"כ הי' להם להאמין שנבואת משה הי' הגבה מכל הנביאים, והם לא האמינו ואמרו היש הוי' כו'. וע\"פ הקבלה היש הוי' בחי' ז\"א אם אין הוא בחי' מל' והם לא ידעו אם נמשך מבחי' ז\"א ד\"ע או מד\"ת בחי' אין מל', וזהו החטא שלהם מיד ויבא עמלק כו' והיינו שקליפת עמלק היא מסתרת על בחי' ד\"ע שהוא הקליפה הלעו\"ז כו', שזהו ענין יודע את רבונו ומכוין למרוד בו, שהוא הלעו\"ז נגד בחי' ד\"ע כו'.\n<b>וזהו</b> מ\"ש הנה זה עומד אחר כתלינו משגיח מן החלונות מציץ מן החרכים, פי' כתלינו, הנה כתיב ביחזקאל ונתת אותה קיר ברזל בינך ובין העיר ולמדו רז\"ל מזה בברכות פ' אין עומדין משחרב בהמ\"ק חומת של ברזל מפסיק בין ישראל לאביהם שבשמים. ולכאו' צ\"ל הלא מצינו קיר לשבח כמ\"ש גבי אלישע נעשה נא עלית קיר קטנה ונשים לו שם כסא ושולחן ומטה ומנורה, ואיתא בזהר שזהו בחי' ד' תיקוני שכינתא, וגם ארז\"ל ע\"פ ויסב חזקיהו פניו אל הקיר מכאן למתפלל שלא יהא דבר חוצץ בינו לבין הקיר כו'. והענין הוא דהנה איתא בזהר שקיר הוא בל' יון אדון, והיינו בחי' שם אדנ\"י, שזהו ההפרש בין שם הוי' לשם אד', כי שם הוי' כשמו כן הוא"],[2000560249,"בלא קץ ותכלה, ואם הי' בריאת העולמות משם הוי' לא הי' העולם בבחי' יש ודבר כ\"א בבחי' ביטול, וכדי שיהיו העולמות בבחי' יש זהו ע\"י שם אד' שמסתיר ומעלים על אור קדושת שם הוי' כדי שיהי' מקור לעולמות הנבראים ונפרדים כו' כנ\"ל. והנה זהו עבודת האדם להמשיך בחי' שם הוי' להיות יחוד הוי' ואלקי' (כי שם אד' ושם אלקים הכל אחד) כמ\"ש שמש ומגן הוי' אלקים, וזהו כותל דקדושה כי כותל הוא כ\"ו ת\"ל, כ\"ו הוא גימט' של שם הוי', ת\"ל גימט' ה\"פ אלקי' להיות יחוד הוי' ואלקי'. וזהו מ\"ש ויסב חזקי' פניו אל הקיר והיינו שהמשיך בחי' פניו שהוא מ\"ש יאר הוי' פניו בבחי' קיר בחי' אדון שם אד', וכמו\"כ המתפלל צריך שלא יהי' דבר חוצץ בינו לבין הקיר כו' כי המכוון הוא להמשיך בחי' הוי' באמרו ברוך אתה הוי' ברוך לשון המשכה בשם אד' ולכן צריך שלא יהי' דבר חוצץ כו', וזהו כתלינו כותל דקדושה.\nג) <b>והנה</b> לעומת זה הוא בחי' כותל דעמלק שמסתיר ומעלים, שלכן נק' קיר ברזל כי ברזל הוא ב\"פ ק\"ך והיינו נגד בחי' ק\"כ צירופי אלקי' דקדושה ונגד ק\"כ צירופי' אלקי' אחרים, ולכן הוא מסתיר ומעלים לגמרי. וזהו מ\"ש במד\"ר ס\"פ תרומה ע\"פ וזאת התרומה אשר תקחו מאתם זהב וכסף ונחשת, זהב זו מלכות בבל, כסף זו מדי, נחושת זו יון, אבל ברזל אין כתי' כאן, והיינו כי ברזל הוא נגד מלכות הרביעית ובחי' מלכות זו א\"א לבררה כלל, וכמ\"ש רז\"ל במד\"ר שם שגם לע\"ל לא יקובל ממנה נדבה כו' והיינו כמ\"ש ראשית גוים עמלק ואחריתו עדי אובד, והיינו שאחרית של עמלק היינו מלכות הרשעה א\"א לברר אותה כלל כ\"א שבירתו זהו תיקונו כמשי\"ת לקמן.\n<b>וזהו</b> מ\"ש (מ\"א וא\"ו ז') והבית בהבנותו אבן שלימה כו' והמקבת וכל כלי ברזל לא נשמע בבית בהבנותו, וכמשארז\"ל (מדות פ\"ג משנה ד') שהברזל פוסל בנגיעה והיינו כנ\"ל שמבחי' ברזל א\"א לברר כלל, וזהו בחי' עמלק כי חושבנא דדין כחושבנא דדין שברזל עם הכולל גימ' עמלק, שזהו מ\"ש מלחמה להוי' בעמלק,"],[2000560250,"והיינו כמשארז\"ל אין השם שלם ואין הכסא שלם עד שימחה זרעו של עמלק, פי' אין השם שלם שי\"ה אינו מאיר בו\"ה, פי' יו\"ד ה\"א של ש' הוי' הוא בחי' סוכ\"ע כי בינה מקור המקיפים, ועמלק מונע הגילוי מבחי' י\"ה בו\"ה, וכמו\"כ אין הכסא שלם כי כסא הוא כס אל\"ף, פי' שמכוסה בחי' אל\"ף אלופו ש\"ע, כי הנה צריך להיות נכון כסאך מאז, פי' שכדי שיהי' נכון כסאך זהו מאז דוקא היינו כשמאיר מאל\"ף בז' ז' מדות, ועמלק הוא היפך זה, ונק' ע\"ש עמלק מפני שעמלק הוא ראשית גוים כמ\"ש ראשית גוים עמלק, פי' גוים הם ז' מדות הרעות בחי' ז' אומות הכנעני כו' והפריזי וראשית גוים אלו זהו עמלק דוקא, וזהו מארז\"ל הקנאה והתאוה והכבוד כו' הוא בחי' מדות רעות, וכבוד הוא בחי' לבושי' שהוא היפך לבושי כה\"ג שהי' בקדושה, וזהו אין השם שלם ואין הכסא שלם עד שימחה זרעו של עמלק, ולאחר שימחה זרעו של עמלק אז אח\"כ יהי' הגילוי בחי' י\"ה בו\"ה.\n<b>ובזה</b> יובן מה שחטא שאול במה שרצה להקריב קרבנות משלל עמלק, והיינו כנ\"ל שעמלק הוא בחי' קיר ברזל היפך בחי' ביהמ\"ק דקדושה שלכן לא הי' ברזל בבנין בהמ\"ק והברזל פוסל בנגיעה, לכן א\"א להביא קרבנות ג\"כ משלל עמלק כי א\"א להעלות בחי' עמלק כלל, וזהו שאמר לו שמואל מאסת את דבר ה' שהוא היפך מבחי' בהמ\"ק. ולכן משחרב בהמ\"ק כותל של ברזל מפסיק בין ישראל לאביהם כו' כי כשזה נופל זה קם, ופי' בין ישראל לאביהם שההפסקה היא מחמת ישראל כי לפניו ית' אין דבר חוצץ כי כחשיכה כאורה, אכן מחמת בחי' נש\"י הוא ההפסק שזהו מ\"ש עוונותיכם היו מבדילים שע\"י העון הוא מסך מבדיל בחי' עמלק קיר ברזל. והעצה לזה הוא בחי' תשובה שע\"י לב נשבר ונדכה עי\"ז שוברים הכותל להיות מציץ מן"],[2000560251,"החרכים ומשגיח מן החלונות, והיינו אף שאין שוברים כל הכותל עכ\"פ עושים עי\"ז חלונות וחרכים להיות מאיר אור א\"ס ב\"ה ע\"י חלונות וחרכים כנ\"ל, וכמו שע\"י החלון מאיר בחי' השמש כמו\"כ ע\"י חלונות אלו מאיר בחי' שמש הוי' כו'.\n<b>וכדי</b> לשבר את הכותל של ברזל הנ\"ל להיות נעשה בה חלונות וחרכים זהו ע\"י בחי' משה. וזהו ועשית ציץ כו' שמשה הוא העושה ומשבר בחי' כותל דעמלק, ולכן תלוי מלחמת עמלק במשה כמ\"ש והי' כאשר ירים משה ידו וגבר ישראל וכאשר יניח כו', וביאור הענין הנה התורה נק' תורת משה כמ\"ש זכרו תורת משה עבדי וכמ\"ש תורה צוה לנו משה, וצ\"ל מפני מה נק' התורה תורת משה, הנה ארז\"ל במד\"ר פ' ויקרא ע\"פ גבורי כח עושי דברו לשמוע בקול דברו, בנוהג שבעולם משאוי שקשה לאחד נוח לשנים, לשנים נוח לארבעה, שמא תאמר משאוי שקשה לס' רבוא נוח לאחד, כך ס' רבוא ישראל לא יכלו לקבל הדבור מפי הקב\"ה שנאמר אם יוספים אנחנו לשמוע, ומשה שמע הדבור מפי הקב\"ה, וזהו גבורי כח כו' לשמוע בקול דברו פי' שמע הדבור הוא בחי' דבר ה', והנה הדבור הוא גילוי ההעלם שהוא גילוי המחשבה כו', ופי' בקול דברו היינו בפנימיות הקול דהיינו מה שמאיר בבחי' הקול, ובחי' זו לא יכלו נש\"י לקבל כי זהו בחי' פנימיות דבר ה' הוא בחי' ד\"ע, כ\"א משה שהי' מן המים משיתיהו פי' בחי' מים עליונים שלמעלה מן הרקיע המבדיל, לכן הי' יכול לקבל בחי' זו, ולכן נמשכה התורה ג\"כ ע\"י משה דוקא עד שנק' תורת משה עבדי כי הוא עלה שמים וירד כו', ומחמת שהי' בחי' גבוה מאד מן המים משיתיהו לכן הי' יכול ג\"כ להעביר קליפת עמלק, והיינו מחמת עוצם הגילוי שהמשיך משה ממילא נדחה הרע של עמלק, וכמו שע\"י האור ממילא נדחה החשך, ולכן תלוי מלחמת עמלק במשה דוקא.\n<b>וזהו</b> ועשית ציץ, פי' שמשה הוא העושה הציץ לאהרן כהנא רבא להיות כי משה המשיך בחי' תורה עי\"ז ממילא נדחה החשך. זהב טהור הוא ע\"ד מ\"ש ממולח טהור קדש, פי' מעורב טהור בקדש להיות נמשך בחי' קדש בטהור שבחי' זו היא שרש נש\"י כמ\"ש נשמה שנתת בי טהורה היא.\nד) <b>ופתחת</b> עליו פתוחי חותם, הנה ארז\"ל חותמו של הקב\"ה אמת אני ראשון ואני אחרון ומבלעדי אין אלקים, ואין אמת אלא תורה, ונמשלה לחותם כמו החותם כאשר היא חקוקה על האבן טוב הנה מחמת רוב בהירות האבן אין יכולים לקרות האותיות כ\"א עד שיחתום בהחותם על השעוה הנה מחמת גסות השעוה ניכרים האותיות היטב, אך עכ\"פ הנה האותיות שעל השעוה הם האותיות ממש שעל האבן טוב, כך יובן בנמשל למעלה שהתורה הגם שירדה למטה ונתלבשה"],[2000560252,"בדברים גשמיים הנה עכ\"ז שרש התורה היא היא ממש כמו שהיא הגבה למעלה רק שנתלבשה בדברים גשמיי' כו', ולכן ע\"י בחי' התורה נדחה הרע של עמלק. וזהו חותם אותיות חומת והיינו שע\"י החותם דתורה נדחה בחי' החומת בחי' קיר ברזל דעמלק, אך הנה כ\"ז הוא כשהתורה היא בחי' תורת משה, דהיינו כשלומד התורה בבחי' ביטול כמו משה שהי' בבחי' ביטול כמ\"ש ונחנו מ\"ה, כמו\"כ צ\"ל לימוד התורה ג\"כ בבחי' ביטול.\n<b>קדש</b> להוי', פי' בפרד\"ס שהוא בחי' המשכת קדש להוי', וביאור הענין הנה יש קדש וקדוש, קדוש הוא בחי' קדש וא\"ו, המשכת בחי' הוא\"ו כדי שיהי' אחריו בחי' ה' אחרונה, שזהו מה שאומרים קדוש קדוש קדוש ה' צבאות והיינו שכדי שיהי' בחי' ה' צבאות זהו ע\"י בחי' וא\"ו, וזהו קדש וא\"ו היינו המשכת הוא\"ו, משא\"כ בחי' קדש הוא מובדל, והנה כתי' שאו ידיכם קדש וברכו את הוי', וזהו בחי' קדש להוי' המשכת בחי' קדש להוי' בבחי' ברכה כמ\"ש וברכו את הוי' שזהו בחי' ברכה והמשכה בשם הוי'. ועוי\"ל בפי' קדש להוי' ע\"ד משארז\"ל קדש למ\"ד מלמטה והוי' מלמעלה, א\"כ שם הוי' גבוה מבחי' קדש, אך באמת שניהם אמת, כי הנה כתי' ויקרא הוי' הוי' שיש ב' שמות הוי' שם הוי' דלעילא ושם הוי' דלתתא, והנה לגבי בחי' שם הוי' דלתתא שהוא מקור להתהוות העולמות כנ\"ל א\"כ קדש להוי' הוא בחי' המשכה בשם הוי', אך לגבי שם הוי' דלעילא הנה בחי' קדש למטה במדרגה, ולכן קדש למ\"ד מלמטה והוי' מלמעלה כו'.\n<b>והי'</b> על מצח אהרן כו' תמיד לרצון, פי' מצח חופה על המוחין פי' להיות כי אף כשמתבונן היטב ומוליד בנפשו בחי' אהוי\"ר אשר עי\"ז מאיר בחי' אה\"ר הנה הוא רק בשעת התפלה, אבל אחר התפלה חולפת ועוברת האה\"ר לזה הוא בחי' המצח בחי' נצחון, היינו שמחמת ההתבוננות יהי' נעשה אצלו הסכם חזק להיות יתד תקוע במקום נאמן, וזהו תמיד לרצון שההסכם שנעשה הוא תמיד כו' שגם לאחר התפלה שחולף ועובר ההתבוננות מ\"מ ישאר ההסכם הנעשה ע\"י התבוננות התפלה כו'."],[2000560253,"<h3>ויתן אל משה ככלותו כו'</h3>\n<b></b><b>בס\"ד. (ש\"פ תשא, כ\"ז).</b>\nאבות ומ\"ת\n[תשא]\n<b>ויתן</b> אל משה ככלותו לדבר כו', ברבות כי תשא פמ\"א ג' דברים מתנה לעולם הגשמים והמאורות והתורה כו', התורה מנין שנאמר ויתן אל משה כו', וכ\"ה ברבות בראשית פ\"ו. כי הנה יש להבין מה שמצינו בדברי רז\"ל שדורות הראשונים מאדה\"ר עד מ\"ת לא זכו לתורה אע\"פ שהיו צדיקים גמורים כמו מתושלח נח ואברהם כו' דמשמע שעבודתינו ע\"י תומ\"צ הוא גבוה למעלה ממדרגת עבודתם, וכדמשמע ברבות בראשית פכ\"ד ע\"פ זה ספר תולדות אדם ראוי הי' אדה\"ר שתנתן תורה על ידו מ\"ט זה ספר כו' חזר ואמר לא לאדם כו' שש מצות כו' שנא' ויאמר לאדם, לא לאדם אני נותנה כ\"א לבניו מ\"ט זה כו' תולדות אדם ע\"ש. וכן משמע ג\"כ ממ\"ש ברבות בשה\"ש ע\"פ לריח שמניך כל המצות שעשו לפניך האבות ריחות היו כו' משמע רק כמו ריח שאינו עצם הדבר כ\"א ריח והארה בעלמא ממנו. ובמ\"א מצינו שקיים אברהם כל התורה כו' במשנה סוף קדושין, והיינו שהשיגו ברוחניות כל המצות, וא\"כ מדרגתם גבוה כו'.\n<b>אך</b> הענין דשניהם אמת שיש יתרון גדול במ\"ת יותר ממה שהי' קודם שלא זכו לתורה, ומ\"מ יש ג\"כ יתרון בצד א' במה שקיים אברהם כו' יותר מאתנו, ועיקר ההפרש הוא שהם השיגו התורה ע\"י עבודתם מלמטה למעלה, ולנו ניתנה התורה במתנה מלמעלה למטה, דהיינו שהם המשיכו ע\"ד שע\"י אתעדל\"ת נמשך אתעדל\"ע"],[2000560254,"שהוא ע\"ד (איוב ל\"ד י\"ד) אם ישים אליו לבו כו' רוח אמשיך רוח כו', וכמ\"ש בד\"ה וקבל היהודים בענין פי' קיים אברהם כו' דהיינו ע\"י שהי' הלוך ונסוע שהוא בחי' רצוא ושוב כו', וזהו ממש ענין רמ\"ח מ\"ע ושס\"ה ל\"ת שהן הן בחי' רצוא ושוב כו', ע\"ש, ולכן רצוא ושוב גימט' תורה. וכמ\"כ נת' ענין זה בד\"ה וכל העם רואים את הקולות, עוד נת' ענין זה בד\"ה משה ידבר דמ\"ש באברהם וישמור משמרתי מצותי דהיינו שגרם ירידת והמשכת אוא\"ס ב\"ה והתלבשותו במדת החכמה וחסד ע\"י שהי' שפל רוח מאד שזהו מדת חכמה כח מ\"ה, וזהו אברהם אבר מ\"ה, וע\"י שהרבה חסד בעולם ויטע אשל כו' (וכמ\"ש בס' הבהיר אמרה מדת החסד כ\"ז שאברהם בעולם לא הוצרכתי כו'). גם ע\"ד מ\"ש בפי' ויעל אברם ממצרים בד\"ה בחדש השלישי, נמצא מה שהמשיך אברהם אור א\"ס בחכמה זהו ע\"י אתעדל\"ת בביטול עצום בבחי' ואנכי עפר ואפר כו', ואם לא הי' הביטול עמוק כ\"כ לא הי' יכול להגיע ולעורר המשכה זו, וזהו ענין שהם השיגו ע\"י עבודתם מלמטה למעלה ע\"י שהיו בבחי' מרכבה ממש, ועמ\"ש בענין מארז\"ל במדרש פ' חיי פ\"ס יפה שיחתן של עבדי אבות מתורתן של בנים כו'."],[2000560255,"<b>אבל</b> לנו ניתנה התורה במתנה מלמעלה למטה כמו ע\"י תפילין אנו ממשיכים המשכת אור א\"ס בחכמה שבפ' קדש שבתפילין מלובש בה חכמה ובפ' והי' כי יביאך בינה, וכשאדם מניח תפילין ממשיך המשכת אור א\"ס בחכ' עילאה אף אם אין לו חלק א' מאלפי אלפים מהביטול של אברהם, נמצא לא שייך לומר ע\"ז שבאתעדל\"ת ממש נמשך אתעדל\"ע זו אלא זהו ע\"ד מתנה ממש שאור א\"ס ב\"ה נמשך מעצמו מלמעלה למטה ע\"י קיום מצוה זו, שהרי אין ההעלאות מ\"נ שע\"י המצוה מערך ההמשכה כלל, וכמ\"ש ג\"כ במ\"א בת\"א בפ' בשלח סד\"ה לסוסתי בענין אך הנה יש עוד אתעדל\"ע שהם אותיות זכרים שהם באים שלא ע\"י אתעדל\"ת כלל כו' והוא בחי' שמחה של מצוה מרוב כל כו' שהוא ההמשכה מבחי' תר\"ך עמודי אור כו' ע\"ש. וזהו ענין ותתן לנו הוי' אלקינו כמ\"ש בד\"ה האזינו השמים (השלישי). ומלבד שזה בא שלא ע\"י אתעדל\"ת, עוד זאת שההמשכה באה ממקום עליון יותר למעלה מהבחי' שאתדעל\"ת מגעת שם, כנז' בד\"ה לסוסתי הנ\"ל בענין קרי\"ס שלהיות הפך ים ליבשה זהו מבחי' ואתם תחרישון, כי כל האתעדל\"ת מגעת רק עד חכמה, משא\"כ בחי' כתר הוא למעלה מאתעדל\"ת כו' (עד\"מ מה שהרב משיב לתלמיד ע\"פ שאלתו, אף שזהו משכל הרב מ\"מ התשובה לפי ערך השאלה, משא\"כ מה שהרב משפיע מעצמו שכל וסברא עמוקה אף שילבישנה במשלים מ\"מ היא מעצמות שכל הרב ממש).\n<b>ועד\"ז</b> יובן כאן דהיינו שבתורה נמשך מעצמיות ומהות חכמתו ית' פי' מן כח מהות חכמתו ית' נמשך ונתלבש באותיות התושב\"כ, וכמו פ' קדש שבתפילין שמלובש בה חכמה עילאה מאחר שנמשך ונתלבש בה מרצונו וחכמתו ית' בבחי' מתנה בלי התעוררות הנבראים הוא עצמיות ומהות חכמתו ית' חכים ולא בחכ' ידיעא, רק שהוא כמו שהרב מלביש שכלו העמוק במשל כמ\"כ פ' קדש הוא עד\"מ כמו לבוש ומשל, אבל עכ\"ז בה מלובש עצמיות חכ' עילאה, וכמו בהטפה מלובש עצמיות חב\"ד עד שמוליד בדומה לו, וכמ\"ש בפי' אשר קדשנו במצותיו וצונו שזה שבאתעדל\"ת של קיום המצות גשמיות יהי' נמשך אתעדל\"ע המשכות רמ\"ח אברים דמלכא ז\"א [דאצי' כי ז\"א הוא בעל ט' ספירות, וט' פעמים ט' וראש תוך סוף וה' חסדים המגדילי' עולה רמ\"ח] זהו נמשך מבחי' אשר הוא תענוג העליון בחי' עת\"י המאיר בחו\"ב אהי' אשר"],[2000560256,"אהי', משם דוקא נמשך הכח שיהי' נמשך אתעדל\"ע רמ\"ח אברין דז\"א ע\"י קיום המצות גשמיות, והיינו כי אשר אותיות ראש כמו עד\"מ הראש מושל ושולט על הרמ\"ח אברים להנהיגם כרצונו אף נגד טבעם [ועמ\"ש במ\"א בביאור על סש\"ב פך\"ג מענין שבטרדא גדולה שולט הרצון גם על הכחות כמו כח הדוחה וכדומה, וע' בד\"ה ונשב בגיא], כך מבחי' אשר נמשך שיהי' קדשנו במצותיו וצונו וכמ\"ש בלק\"ת בד\"ה ביום השמע\"צ שמאלו תחת לראשי כו', ועמ\"ש מזה בד\"ה לסוסתי ברכבי גבי והוא כחתן יוצא מחופתו. אמנם מה שהמשיך יעקב אבינו חכמה עילאה בעבודתו במקלות וברהטים שהמשיך המוחין בז\"א כמ\"ש בזהר ויצא דקס\"א ע\"ש במק\"מ, והן הן דוגמת ד' בתי תפילין מאחר שאינה מצוה ולא הורד ממנו ית' להתלבש ברהטים ובמקלות, רק שהוא אבינו יעקב הכין נפשו במס\"נ ועשה יחודים עליונים באצי' עד שגרם בהעלאת מ\"ן שלו המשכת חכמה דאצי' בנפשו ממש, וע\"פ עובדא הנ\"ל כמו אופן התפילין, אבל מאחר שאין זה מצות המלך הקב\"ה להיות הרהטים כמו תפילין רק שאבינו יעקב להיותו מרכבה המשיך זה, הרי אין המשכה זו רק לפי ערך ההעלאת מ\"נ לכן אין בזה המשכת והתלבשות עצמות ומהות חכמתו ית' כ\"א רק הארה בעלמא כו', וכמו עד\"מ הארת החכמה ע\"י הדבור שאין בזה רק הארת החכמה ולא העצמות כו', וכמו שהמלאכים ביקשו התורה ולא ניתנה להם, והרי הם אומרים קדוש בכלות הנפש עכ\"ז אין ממשיכים רק הארת חו\"ב ולא העצמות כמ\"ש בת\"א בביאור ע\"פ זכור ושמור בדבור א' נאמרו שם דק\"כ ע\"ד בד\"ה אך ההפרש כו' [ולכן במלאכים נאמר רק זכר רב טובך יביעו שרק זכר מבחי' רב טוב יביעו המלאכים כמ\"ש בסידור ע\"פ בדף נו\"ן סע\"ב וע\"ג (ד' זיטאמיר), משא\"כ בישראל נא' ורב טוב לבית ישראל].\n<b>וזהו</b> מ\"ש ברבות בשה\"ש ע\"פ לריח שמניך טובים כל המצות שעשו לפניך האבות ריחות היו אבל אנו שמן תורק שמך מאתיים וארבעים ושמונה מ\"ע כו', ור\"ל ריחות היו כמו הריח מהפרי שאין בו עצמיות ומהות הפרי כלל רק ריח שאינו אלא כמו הארה ולא העצמות כמו\"כ בהמשכתם לא האירה עצמיות ח\"ע של אור א\"ס ב\"ה"],[2000560257,"רק הארה כו', ועמ\"ש בלק\"ת בשה\"ש ע\"פ לריח שמניך, ועמ\"ש במ\"א בביאור מאמר הזהר ע\"פ וה' פקד את שרה בענין שמרבע\"ה אמר הראני נא את כבודך כבוד ל\"ב נתיבות חכמה דהיינו ענין ד' פרשיות דתפילין שהם מוחין דז\"א, והשיב לו הקב\"ה וראית את אחורי קשר של תפילין שהוא העור בחי' מל' דתבונה אותיות המחשבה [והגם כי משה הי' דור שביעי לאברהם, כמ\"ש במד\"ר], אכן ופני המוחין עצמן לא יראו והרי ע\"י קיום מצות תפילין ממשיכי' עצמיות הד' מוחין ממש, מה שמשה רבע\"ה לא יוכל להשיג זה כלל, א\"כ מזה יובן שהוא בחי' שלמעלה מאתעדל\"ת רק באה מאליו מלמעלה למטה דרך מתנה, וכמ\"ש מזה ג\"כ בד\"ה רני ושמחי בענין שמחה בצפרא שזהו מ\"ש והיו הדברים האלה אשר אנכי מצוך אנכי מי שאנכי, כי הגם שבאתעדל\"ת ממטה למעלה א\"א להיות מגיע כ\"א בבחי' מלכותו ית', אבל מלמעלה למטה אור א\"ס מאליו וממילא נמשך גם מבחי' אנכי מי שאנכי כי לפניו ית' כחשיכה כאורה המגביהי לשבת המשפילי כו' יעו\"ש. וענין שמחה בצפרא י\"ל זהו מ\"ש במ\"ת ויהי ביום השלישי בהיות הבקר, הבקר אור כו' בוקר דיוסף כמ\"ש במ\"א, ע' בבה\"ז בלק ע\"פ ה' בקר תשמע קולי בקר כו', ובזה יובן ענין שהמאורות מתנה לעולם כו'. ועד\"ז נת' במ\"א ההפרש בין אהבה דאברהם לבחי' אהבה דאהרן שהוא ע\"י מ\"ת כה\"ג כו' שבחי' אה\"ע דאברהם מלמטה למעלה, אבל אהרן אותיות נראה אור בחי' שיורד על פי מדותיו מלמעלה למטה כו' בד\"ה בהעלותך את הנרות."],[2000560258,"<b>נמצא</b> מובן לפ\"ז ההפרש ששניהם אמת, שבמקור התורה דהיינו בחכמתו ורצונו ית' ניתן לנו ממקום הגבוה יותר ממה שהם השיגו ברוחניות ע\"י העלאת מ\"נ שלהם דהיינו מה שקיימו כל התורה, והיינו שלא זכו לתורה פי' שלא הגיעו בעבודת נפשם למקור התורה באמיתתה כנ\"ל. אבל בזאת יתרון מעלתם עלינו שהרי אין אנחנו משיגים בנפשינו כלל מאור חכמה דאצי' הגנוזה ומלובשת בפ' קדש רק שחסד ה' עלינו שזיכנו להתקשר נפשנו בעצמותו ית' ע\"ד סגולה שנכתוב פ' קדש ונניח אותו על היד ועל הראש [לשעבד הלב והמוח] ועי\"ז יתלבש בנפשנו חכ' דאצי', אבל אין הנפש מכרת כלל מהות ההמשכה ואפילו יהי' בה העלאת מ\"נ אין בכחה לעורר כלל המשכת מהות חכמה דאצי' להיות כי א\"א לה להשיג כ\"א ביטול עולם השפל הזה לאלקות, ועולם הגלגלים דעשי' הוא מלבושי נוגה לבד כידוע, ואיך יתפש בה אפילו הארה דהארה מחכ' דאצי' מקור כל האורות דאצי', רק בדרך הלבשה מתלבשת בתפילין שגנוז בה בהעלם, ועי\"ז מתקשרת הנפש בג\"ע העליון בזיו הארת החכ' דמל' דאצי' שבתוכה חכ' דאצי', וזהו הקבלת שכר ממעשה המצות [ומ\"מ מעשה המצוה עצמה גבוה יותר].\n<b>אבל</b> האבות השיגו בחייהם בחי' עולם הבריאה וגם אורות דמל' דאצי' המלובש בבריאה ע\"י עבודה ומס\"נ שלהם (וע' בהרמ\"ז ר\"פ וארא עמש\"ש בזהר דכ\"ג ואלין דמתחזיין לא זכי בהו בר נש עד דאתו אבהן וע\"ד כתיב וארא דחמי אינון גוונין דאתגליין כו', וז\"ל בבריאה יש שני בחי' אחת הוא אור העצמי שלה כו', והשני אור אימא דאצי' המאיר בבריאה כו', והאבות זכו לאל שדי הוא האור הבריאה בעצמו כו', אך מרע\"ה זכה לגילוי בחי' אור האצי' המאיר בבריאה עכ\"ד, ויש לכוונו עם מש\"כ) וכמ\"ש ויסע אברם הלוך ונסוע וכמ\"ש בזהר פ' לך ד\"פ ע\"א ע\"ש, וכן ביעקב ע\"י עבודת המקלות השיג בנפשו ממש חכ' שבמל' כו', ומ\"מ במקור התורה חכים ולא בחכ' ידיעא כמו שהיא בחכ' דאצי' לא השיגו כלום, וזהו ושמי הוי' לא נודעתי להם כמ\"ש במ\"א, ומצד זה עבודתינו במצות מעשיות גבוה הרבה מעבודתם שבמצות מלובש חכמתו ורצונו ממש כנ\"ל, וזהו שלא זכו לתורה.\n<b>ועפ\"ז</b> יובן ענין מתנה דיש בזה מעלה כנ\"ל, וגם חסרון כמבואר בפ' בתרא דברכות בענין ההפרש בין שחלק ובין שנתן כו', ומבואר במג\"א סי' רכ\"ד"],[2000560259,"סק\"ד ודבוקים בו, משא\"כ עוכומ\"ז בהנחל כו' בהפרידו כו' כמ\"ש הט\"ז שם. והענין דכתב הרמ\"ז פ' צו דכ\"ח ע\"א בשם הפע\"ח בכוונת ברוך אלקינו שבראנו לכבודו שהתורה שלנו היא מן הבריאה ואמנם הוא ז\"ל פי' שהיא מבחי' פנימי' אצי' המושפע לבריאה כו', ועמ\"ש בזה הרמ\"ז פ' וארא כ\"ג ב', ועד\"ז פי' בפ' בראשית דף ד' סע\"ב ע\"פ ואשים דברי בפיך בענין ד' בחי' פרד\"ס אשר פר\"ד מתקן בי\"ע כו', והיינו להיותם מאצי' שבבי\"ע כנ\"ל, ועמ\"ש בלק\"ת פ' עקב בד\"ה ולהבין שרש טעם כו' ברית ותורה לבהמ\"ז שם פ\"ג בפי' ועל תורתך שלמדתנו תורתך היא תורה דאצי' ושלמדתנו הוא בחי' התורה דבי\"ע כו', והיינו שבחי' פר\"ד שבתורה הוא המתקן בחי' ומשם יפרד כו', ע\"ד ורב שלום בניך א\"ת בניך אלא בוניך כו', וכמ\"ש מכ\"ז ע\"פ ויאמר לו יהונתן מחר חדש, ולכן שייך ע\"ז שנתן כי נמשכה לעולם הפירוד, וזהו מתנה יש לה הפסק ע\"ד הוי' הוי' ופסיק טעמא בינייהו, הגם דבאד\"ר נשא קלח\"א משמע דהיינו בחי' ז\"א ובחי' עתיק יומין וה\"ע ממכ\"ע וסוכ\"ע, אך כי הפסיק ה\"ע והבדילה הפרוכת [ובמקדש היו י\"ג פרוכת] ובחי' פרוכת הוא ג\"כ המפסיק בין אצי' ובין בי\"ע.\n<b>וזהו</b> שארז\"ל והתקן עצמך ללמוד תורה שאינה ירושה לך, ופי' במד\"ש כי האומר לא יגעתי ומצאתי אל תאמין, והיינו כי ירושה אין לה הפסק אבל מתנה יש לה הפסק. וצ\"ע דהכתיב מורשה קהלת יעקב וארז\"ל סנהדרין דצ\"א סע\"ב מורשה היא לכל ישראל משי\"ב, וכן פי' בזהר יתרו דפ\"ג ע\"ב לאמר למהוי ירותא לכולא דכתיב תורה צוה לנו משה מורשה, וזה לכאורה סותר המשנה שאינה ירושה לך.\n<b>וי\"ל</b> כמ\"ש בד\"ה יונתי בענין ואנכי איש חלק ב' חלקים, ע\"כ מצד הנשמה שבאצי' שהוא ז\"א דאצי' אזי התורה ירושה היא כי אלפים הם חו\"ב וז\"א אחסנתי' דאו\"א ירית ושרשו מחו\"ב דא\"א אוירא דכיא ואשא דכיא מימינו אש כו', וע' אמור"],[2000560260,"צ\"ד שבת ירושה, אבל מצד הנשמה שבבי\"ע אינה ירושה לך, ולכן צ\"ל תפלה סולם לחבר ב' חלקי הנשמה ואזי התורה מורשה, וזהו שעליי' התומ\"צ בשבת כי אז עליות העולמות כו'. ובספר זהרי חמה ויחי דרי\"ו ע\"א בפי' לעולם יירשו ארץ ירותת עלמין כלומר ירושת עולם כדין הירושה שאין לה הפסק כלל, משא\"כ במתנה, וז\"ש לעולם יירשו ארץ כי מאחר שהיא בלשון ירושה היא לעולם עכ\"ל. עוי\"ל כי תורה יש בה ב' בחי', הא' מה שנתלבשה בז\"א ש\"ס משנה, הב' ג\"ר שבאים בסוד תוס', והבחי' א' ירושה, והב' מתנה ויש לה הפסק כי לפעמים מחמת החטא מסתלקים ג\"ר, ולמטה זהו ע\"ד פ\"א שחרית ופ\"א ערבית זהו ירושה, אכן ע\"ד לא ימוש ספר התורה כו' שזהו ברכה (מנחות צ\"ט סע\"ב) זהו מתנה כו'. עוי\"ל כי תורת ה' ובתורתו כו'. עוי\"ל נובלות ועצמיות כו'. עוי\"ל שזה שיהי' תורתו אומנתו זהו מתנה כו', גם ע\"ד אדם אחד מאלף מצאתי אלף נכנסים למקרא כו' עד א' להוראה. עוי\"ל דרך כלל לכל ישראל התורה היא ירושה ואין לה הפסק וז\"ש מורשה קהלת יעקב, אבל לכל א' בפרט התורה אינה ירושה לך, וכמו שארז\"ל בנדרים דפ\"א ע\"א מפני מה אין מצוי שיהיו בני ת\"ח ג\"כ ת\"ח כמותם שלא יאמרו התורה ירושה היא, ולכן לזה צריך זכות כדאיתא גבי רב יוסף פ\"ז דב\"מ דפ\"ה סע\"א שהתענה ג\"כ ק\"ך תעניות עד דאקריוהו מ\"ש בישעי' ססי' נ\"ט לא ימושו מפיך ומפי זרעך ומפי זרע זרעך מעתה ועד עולם ע\"ש, ובנדרים שם משמע אשר זהו ע\"י שמברכין בתורה תחלה כו' ע\"ש.\n<b>עוי\"ל</b> דארז\"ל כי לשון מתנה למי שראוי ליורשו אין לה הפסק (נימוקי יוסף דרך\"ב והאלפס דרך\"ה), וא\"כ מה שזהו מתנה זהו עילוי יותר, וכיון שבישראל נאמר מורשה קהלת יעקב שהם ראויים לירש התורה והארץ והעוה\"ב בבחי' ירושה ממש, והיינו כי אורייתא מחו\"ב נפקת וישראל הם ז\"א שנק' בן לאו\"א כו', וכן איתא ע\"פ כבד את אביך זה תושב\"כ וכמארז\"ל מוסר אביך זה תושב\"כ ותורת אמך זה תושבע\"פ כו', וזהו ענין בן העוה\"ב שהוא בן ממש לעוה\"ב וכן יש להם חלק לעוה\"ב, חלק דוקא ע\"ד שחלק מחכמתו כו', לכן גם מה שבא בבחי' מתנה אין לו הפסק. וענין ירושה זו זהו כמ\"ש במדרש תלים סי' ה' ע\"פ למנצח על הנחילות שנחלתם אותי כמ\"ש חלקי הוי' אמרה נפשי כו', וח\"ו אין ירושה זו כמו למטה שהמוריש אינו בעולם ח\"ו [דהלא ארז\"ל במד\"ר פ' תרומה עשו לי קיטון א' שאדור בתוכה כו'], כ\"א למעלה ענין הירושה להיות בחי' ברא כרעא דאבוה כו', וזהו יעקב חבל נחלתו, ולבא לבחינה זו זהו ע\"י סולם מוצב והו\"ע"],[2000560261,"התפלה כו', וזהו להנחיל אוהבי יש, יש דוקא היינו קנה חכמה קנה בינה, משא\"כ בריאת העולם מבחי' הארה וזיו ולא מבחי' יש כו', וע' בפרדס ערך יש ובמא\"א יו\"ד ל\"ה.\n<b>וזהו</b> ויתן אל משה דוקא כי התורה נק' תורת משה ועמ\"ש מזה בד\"ה ועשית ציץ לפי שהי' בבחי' ונחנו מ\"ה ביטול, ועמ\"ש מענין והאיש משה עניו בביאור מאמר הזהר פ' וישב קפ\"א ע\"פ אך אל הפרוכת כו' כי משה מ\"ה הביטול בפנימי' ביטול דמ\"ה שלמעלה מביטול היש דב\"ן כו', ועמ\"ש במה שאמר ונתתי עשב כו', וע' בביאור שני דיונתי מענין משנה תורה משה מפי עצמו וברוה\"ק כמ\"ש התוס' ומענין תורת כהנים שאמר כך ציוני מפי הגבורה. והנה משה משה לא פסיק טעמא, עיין סד\"ה ואלה המשפטים בענין כי תקנה כו', ולכן עי\"ז נמשך שיהי' מתנה זו בבחי' שאין לה הפסק, וגם שבמשה נאמר ויקרא הוי' הוי' שלא יהי' פסיק טעמא כמ\"ש בת\"א בשלח סד\"ה וירא ישראל."],[2000560262,"<h3>הללוי' הללו כו' מן השמים</h3>\n<b>בס\"ד.</b>\nהללוי' הללו את ה' מן השמים הללוהו במרומים, הנה ארז\"ל שבת דקי\"ח ע\"ב אמר ר' יוסי יהי חלקי מגומרי הלל בכל יום איני והאמר מר הקורא הלל בכל יום ה\"ז מחרף כו', כי קאמרינן בפסוקי דזמרה, ופי' רש\"י שמזמור הללוי' הללו את ה' מן השמים ומזמור הללוי' הללו אל בקדשו הם עיקר פסוד\"ז [וכן משמע בזח\"ב פקודי דרל\"ב א' ת\"ח תושבחתא דא אמר דוד לקבל רזא דשמא קדישא דאיהו כללא דתושבחתא דכולא ואינן דא (היינו הללו את ה' מן השמים) ותושבחתא בתראה דכתי' הללו אל בקדשו, אבל דא הוה על עשר מינים (פי' המק\"מ הם ע\"ס הנרמזי' בהללו אל בקדשו) ודא הוה על שבעה מינים (פי' המק\"מ ז\"ק הנרמזי' בהללו את ה' מן השמים)], והיינו מפני כי במזמור הללוי' הללו את ה' מן השמים נחשב כל בחי' שמים וארץ כו', וכמ\"ש בסידור האריז\"ל הללוי' הללו את הוי' מן השמים אצי', הללוהו במרומים בריאה, מלאכיו יצירה, צבאיו עשי', הללוהו שמש וירח בחי' התכללות עשי' ביצי', כוכבי אור התכללות יצי' בבריאה, שמי השמים בריאה באצי', והמים אשר מעל השמים אצי' בעצמיות המאציל כו', ואח\"כ קחשיב הללו את ה' מן הארץ תנינים כו' אש יסוד האש, ברד שלג וקיטור יסוד המים, רוח סערה עושה דברו יסוד הרוח, ההרים וכל גבעות בחי' דומם, עץ פרי כו' בחי' צומח, החי' וכל בהמה בחי' חי הבלתי מדבר, מלכי ארץ כו' בחי' מדבר, ומסיים הודו על ארץ ושמים וירם קרן לעמו כו' לבנ\"י עם קרובו.\n<b>ולהבין</b> פי' וענין וירם קרן, וגם להבין פרטיות הנ\"ל, הנה נודע כי פסוד\"ז הוא הקדמה לבוא לבחי' הביטול דק\"ש ובק\"ש אומרים שמע ישראל ה' אלקינו ה' אחד ונאמר שמע ישראל דוקא לפי שישראל עם קרובו, וכמשארז\"ל במד\"ר"],[2000560263,"ואתחנן פ\"ב ע\"פ אשר לו אלקים קרובים אליו, אשר לו גוי קרוב אין כתיב כאן, אלא אשר לו אלקים קרובים אליו והיינו כי ישראל הוא בחי' כי שרית עם אלקים, והם קרובים ודבוקי' לבחי' שם הוי', וכמ\"ש ואתם הדבקים בהוי' אלקיכם, שלזה נק' עם קרובו היינו לבחי' שם הוי' שהזכיר תחלה יהללו את שם הוי' כי נשגב כו', וע' מזה בלק\"ת שלח בד\"ה בפ' נסכים בסוף סי' ב', וז\"ע מה שא\"א וקרבתנו מלכנו לשמך הגדול, שמך הגדול דוקא, וע' בלק\"ת בביאור ולא אבה, בענין ויהפוך ה' שורש נש\"י יעו\"ש.\n<b>והנה</b> בענין ה' אחד צ\"ל מפני מה לא נאמר יחיד שמורה יותר על אחדות, כי אחד יש גם אחד המנוי שיש שני ושלישי, אבל יחיד מורה על אחדות יותר, ובאמת בברוך שאמר אנו אומרים יחיד חי העולמים מלך ובישתבח אנו אומרים מלך יחיד חי העולמים, ומפני מה בק\"ש נאמר אחד דוקא. אך הענין הוא דהנה יחיד מורה על אוא\"ס שלמעלה מבחי' סוכ\"ע וממכ\"ע אשר אני ה' לא שניתי ואתה הוא קודם שנברא ואתה הוא לאחר שנברא, משא\"כ אחד מורה על בחי' המהווה ז' רקיעים וארץ וד' רוחות כי חי\"ת שבתיבת אחד מורה על ז' רקיעים וארץ, ולמעלה הוא בחי' ז' מדות לך הוי' הגדולה, וד' רומז לד' רוחות העולם, והאל\"ף הוא בחי' אלופו ש\"ע המהוה ומחי' הז' רקיעים והארץ והד' רוחות, והיינו שאע\"פ שנתהוו ז' רקיעים וארץ וד' רוחות אעפ\"כ הם בטלים לאוא\"ס ב\"ה ולכן אומרים אחד דוקא ולא יחיד, שמתיבת יחיד לא נשמע ונבין שהגם שנתהוו ז' רקיעים וארץ וד' רוחות, ואעפ\"כ הם בטלים לאוא\"ס ב\"ה. ועל בחי' אחד זה נא' יש אחד ואין שני לו (קהלת ד' ח'), פי' הגם כי אחד יש גם אחד המנוי כמו יום אחד, אבל יש אחד שאין שני לו כלל. וע' מזה בד\"ה הגידה לי שאהבה נפשי (ך\"ב) ובד\"ה יש אחד ואין שני (ך\"ח).\nב) <b>וביאור</b> הענין דהנה אנו מבקשים הבט משמים וראה, וכתיב השקיפה ממעון קדשך מן השמים וברך את עמך ישראל, וכמו\"כ בתפלת שלמה המלך"],[2000560264,"נא' כמ\"פ ואתה תשמע השמים (מ\"א ח'), וצ\"ל מהו הבקשה מן השמים דוקא, אך הענין הוא דהנה שמים הוא בחי' אש ומים, אש הוא בחי' גבורה בחי' העלאה מלמטלמ\"ע, ומים יורדין מגבוה לנמוך שהוא בחי' חסד שמלמעלמ\"ט, ומדת הת\"ת מחבר חו\"ג כנודע, וזהו בחי' שמים שהוא כללות המדות ז\"א דאצי', ולכן בתיבת שמים יש תיבת מים בשלימות, אבל מתיבת אש אין בו רק אות השי\"ן בלבד (ואות אל\"ף מתיבת אש י\"ל שיוצא מניקוד הקמץ שתחת השי\"ן שמוציא אל\"ף כנודע מספרי הדקדוק), והיינו מפני כי ז\"א רובו חסדים כו' וכמ\"ש זכר חסדו, וגם מים שרומז לבחי' חסד הוא בחי' יומם דאזיל עם כולהו יומין כמ\"ש בזהר, ועמ\"ש מזה בלק\"ת בד\"ה מצה זו ובכ\"ד, וזהו הבקשה הבט משמים והשקיפה כו' מן השמים דוקא כי כשנמשך במדות אז ואוהב את יעקב ואת עשו שנאתי כי מצד המדות הנה אהבה היא פנימיות החסד והשנאה היא בחי' הגבורה ולכן כשנמשך במדות אזי ואוהב את יעקב, אבל בגלותא הנה אמרו בזהר קוב\"ה בגלותא סליק לעילא לעילא דהיינו לבחי' יחיד שלאו מכל אינון מדות כלל שגם החכ' כעשי' גשמית נחשבת לפניו וכ\"ש בחי' המדות אשר שם כחשיכה כאורה ואם צדקת מה תתן לו, לכן מצד זה נמשך הגלות, שמצד בחי' זו יכול להיות נמשך השפע לאו\"ה כו', כי הנה כתי' רם על כל גוים הוי' שאו\"ה מקבלים חיות מצד רוממות ה' והתנשאותו בעצמותו כביכול שהוא מצד עצמותו ומהותו רם ונשא מגדר עלמין עליונים ותחתונים ואין להם יחוס ושייכות אליו כלל ומזה נמשך ממשלת האו\"ה על ישראל בזמן הגלות גוים מרקדין בהיכלו כו' כי שממית בידים תתפש והיא בהיכלי מלך שאינו תופס מקום כלל, וכך כל העולמות עליונים ותחתונים כולא כלא ממש חשיבי קמי קוב\"ה, וכדכתיב כי נשגב"],[2000560265,"שמו לבדו (שגם בחי' נשגב סוכ\"ע הוא ג\"כ מבחי' שמו כו') רק הודו וזיוו והארתו על ארץ ושמים, וזהו כד סליק קוב\"ה לעילא, וע' מזה בתו\"א בד\"ה כי עמך מקו\"ח. ולכן הבקשה הבט משמים דוקא שכאשר נמשך בבחי' מדות אז ואוהב את יעקב כו', וזהו ענין הללו את ה' מן השמים, שמים הוא בחי' מדות והללו מן השמים הוא בחי' ביטול המדות לאוא\"ס ב\"ה שלאו מכל אינון מדות, וע\"י העלאה זו נמשך אח\"כ בחי' המשכת אוא\"ס ב\"ה.\nג) <b>והענין</b> הוא, דהנה כתיב לך ה' הגדולה כו' כי כל בשמים ובארץ הנה לך וכל הוא בחי' א', רק שלך הוא בחי' העלאה מלמטלמ\"ע וכל הוא בחי' המשכה מלמעלמ\"ט, והנה לך הוא גימ' נו\"ן שהוא בחי' חמשים שערי בינה, כמשארז\"ל בר\"ה דכ\"א סע\"ב חמשים שערי בינה נבראו בעולם, ופי' שערי בינה כי כדי שיתהוו המדות מן השכל זהו ע\"י שערים, שהוא בחי' ההטי' במוח אל המדה שעיקר המדה הוא בלב, אמנם בעת שמתבונן בשכלו שכך טוב לפניו נעשה הטי' בשכלו כן, וזהו בחי' השער שע\"י השער הזה נעשית המדה אח\"כ בלב, ומספר מ\"ט שע\"ב הוא כי ז' מדות וכ\"א כלול מז' הם מ\"ט ושער הנו\"ן הוא עצם הבינה, וזהו לך ה' הגדולה שהעלאת המדות הוא ג\"כ ע\"י השערים כי השער משמש כניסה ויציאה וכשם שהתהוות המדה הוא ע\"י השער כמו\"כ עליית המדה הוא ג\"כ ע\"י השער, וזהו לך ה' הגדולה שהוא בחי' ביטול המדות לבחי' אוא\"ס שלאו מכל אינון מדות שאע\"פ שמדת הגדולה הוא בחי' גבוה שע\"י הוא הנהגת העולמות כמארז\"ל לך ה' הגדולה זו מע\"ב והגבורה זה קרי\"ס והתפארת זו מ\"ת, אעפ\"כ הם בטלים לך ועלייתם הוא ע\"י נש\"ב.\n<b>וזהו</b> כגוונא דאינון מתייחדין לעילא באחד אוף הכי איהי אתייחדת לתתא ברזא דאחד, פי' דאינון קאי על המדות שמתייחדים לעילא דהיינו בחי' ביטול ועלייתם לעילא דהיינו בבחי' בינה ע\"י הנש\"ב. וזהו ג\"כ מאמר השבטים ליעקב כשם שאין בלבך אלא אחד כי יעקב ויצחק גימ' שמים כמ\"ש בפנ\"י פ' הברכה ע\"פ רוכב שמים בעזרך, והיינו מפני שיעקב הוא בחי' מדת הת\"ת שמחבר בחי' יצחק ואברהם שהוא בחי' שמים, כנ\"ל שהשמים הוא בחי' מדות, ופי' בלבך אלא אחד שהוא בחי' ביטול השמים בחי' מדות לאוא\"ס ב\"ה שלאו מכל אינון מדות שזהו בחי' אחד כנ\"ל"],[2000560266,"שהז' רקיעים והארץ בטלים לבחי' אל\"ף, ולמעלה הוא בחי' ביטול הז' מדות לאוא\"ס שלאו מכל מדות, שז\"ע שמתייחדין לעילא כו', ועי\"ז נעשה כי כל בשמים ובארץ שנמשך בחי' כל שהוא בחי' הכלליות בשמים ובארץ, ופי' וענין כל הוא ע\"ד מ\"ש אמרו אליו כל תשא עון, פי' לפי שאתה כל וכלליות הכל דהיינו בחי' א\"ס ב\"ה הסוכ\"ע שלמעלה מהחכ', כי מחכ' ולמטה יש התחלקות לפרטיות חכמה ומדות, אבל למעלה מן החכ' אין שום התחלקות, ולכן תשא עון, כמ\"ש בלק\"ת בד\"ה שובה השני, וכמו\"כ ע\"י ההעלאה בבחי' לך הוי' ביטול המדות לבחי' אוא\"ס שלאו מכל אינון מדות כו' עי\"ז נמשך בחי' כל בחי' הכלליות מבחי' דלאו מכל אינון מדות כו' בשמים ובארץ. ועד\"ז יובן איך ע\"י בחי' הללו מן השמים נמשך שיהי' הללוהו במרומים ובמלאכיו וצבאיו שהוא בחי' בי\"ע כמשי\"ת לקמן. וזהו אוף הכי איהי אתייחדת לתתא ברזא דאחד, רק שזהו רק רזא דאחד, ולא כמו דאינון מתייחדין לעילא כמ\"ש בסידור ע\"ז. וע\"ד זה הוא מה שאמרו השבטים ליעקב כשם שאין בלבך אלא אחד כך אין בלבנו אלא אחד, ופי' מה שאין בלבנו אלא אחד נמשך מבחי' מה שאין בלבך אלא אחד כו', כי ע\"י ההעלאה מה שאין בלבך אלא אחד עי\"ז נמשך שיהי' גם בלבנו בחי' אחד שע\"י ההעלאה בחי' לך ה' ביטול המדות לבחי' שלאו מכל אינון מדות עי\"ז נמשך כי כל בחי' הכלליות בשמים ובארץ וע\"י בחי' שמים וארץ נמשך הביטול גם בי\"ב בקר דבריאה כו'.\nד) <b>וזהו</b> ע\"ד מי עלה שמים וירד ופי' בזח\"ב ויקהל דקצ\"ז ע\"ב ששמים עולה לבחי' מי, וא\"כ בחי' מי הוא למעלה מבחי' שמים והיינו כמ\"ש מי יתן והיה לבבם זה להם ליראה אותי כל הימים וארז\"ל הכל בידי שמים חוץ מיראת שמים שאינו בידי שמים, ולכאורה הלא דהע\"ה ביקש יחד לבבי ליראה את שמך וכמו\"כ אנו מבקשים ויחד לבבינו ליראה, אך הענין דבחי' יראת שמים אינו בידי שמים כ\"א הוא תלוי בבחי' מי שלמעלה מבחי' שמים, שבחי' מי הוא בחי' שאינו"],[2000560267,"מושג כלל וכמ\"ש שאו מרום עיניכם וראו מי ברא אלה, אל\"ה הוא ו\"ק ופ\"ו גימט' אל\"ה, אבל מי הוא בחי' שאינו מושג כלל, וזהו מי יתן מציון ישועת ישראל כו' מי יתן טהור מטמא, ובבחי' מי זה תלוי ענין יראת שמים, כי אם הי' תלוי ענין יראת שמים בבחי' שמים לא הי' הבחירה חפשית שהי' מכריח את הבחירה, אבל כשתלוי בבחי' מי אין הידיעה מכריח את הבחירה כו' (וע' בת\"א בד\"ה ארדה נא).\n<b>והענין</b> הוא דכתיב כי אל דעות הוי' שיש ב' בחי' דעת ד\"ע וד\"ת, ד\"ת הוא מה שמתלבש בכלים דע\"ס דאבי\"ע, ולכן ידיעה זו הוא ע\"י בחי' עיני ה' שהם הכלים והמדות שעי\"ז נמשך ההתפעלות שכר ועונש שהפגם מגיע בהכלים דוקא, משא\"כ ע\"י הידיעה שבדעת עליון שלא ע\"י הכלים דע\"ס אע\"פ שהכל גלוי וידוע לא נמשך מזה התפעלות כו', ותדע שכן הוא מענין ידיעה ובחירה שאין הידיעה שהשי\"ת יודע שזה יהי' צדיק או רשע מכרחת את הבחירה כלל, שהרי משביעין אותו תהא צדיק ואיך הוא, אלא לפי שידיעה זו שהשי\"ת יודע הכל מקודם אשר עדיין לא נעשה זהו בבחי' דעת עליון שלא ע\"י הכלים דע\"ס כו', ולהיות ד\"ע זה בחי' מקיף אינו מכריח את הבחירה שאין האדם מתפעל מזה כמו שלא נמשך מדעת זה התפעלות אפי' במדות עליונות חו\"ג להיות מזה שכר ועונש ושיהי' שכר ועונש זהו ע\"י ד\"ת שע\"י הכלים כו'.\n<b>ולפי</b> פי' הזהר הנ\"ל מי עלה שמים ששמים עולים לבחי' מי היינו כמו לך ה' הגדולה ביטול המדות לבחי' אור א\"ס שלאו מכל אינון מדות כו' ועי\"ז נעשה אח\"כ וירד ע\"ד כי כל בשמים ובארץ. וזהו מ\"ש אליך נשאתי את עיני היושבי בשמים, שלכאו' אות יו\"ד שבתיבת היושבי מיותר דהל\"ל היושב בשמים אך הנה יו\"ד זה הוא בחי' ההמשכה שנמשך בשמים ובארץ הנעשה ע\"י עליית וביטול בחי' שמים לבחי' אוא\"ס שלאו מכל אינון מדות כו' וע' מזה בזח\"ג פ' ואתחנן דרס\"ה סע\"ב.\n<b>ועד\"ז</b> יובן מה שמבחי' הללו מן השמים נעשה אח\"כ הללוהו במרומים שהוא בחי' בריאה, כנודע ההפרש בין שמים למרום שמרום אינו עצם השמים כ\"א מה שנראה לנו גוון השמים שבאמת אינו בחי' השמים עצמם כי השמים לעוצם רוממותו"],[2000560268,"אינו נראה לנו כלל, ומה שנראה לנו הוא רק מה שנעשה באויר מגוון השמים וזהו הנק' מרום, ולמעלה הוא בחי' עולם הבריאה. הללוהו כל מלאכיו הוא בחי' היצי' כי מלאכים הם בחי' שלוחי ההשפעה והם המלאכים דיצי' כמ\"ש אלף אלפי' ישמשוני' ורבוי רבבן קדמוהי יקומון, פי' אלף אלפי' ישמשוני' הוא בחי' המלאכים דיצי' שהם שלוחים, אבל בחי' רבוי רבבן קדמוהי יקומון הם אינם שלוחי' כי הם בעולם הבריאה שהם למעלה מבחי' השפעה כי בורא חושך כתיב שעולם הבריאה נק' בשם חשך שהוא בחי' העלם שלמעלה מבחי' השפעה כו', ויצי' נק' אור כו'. הללוהו כל צבאיו הם מלאכים דעשי' שנק' צבאיו ע\"ש כי ע\"י נעשה הרצון עליון כי צבאיו הוא ל' רצון שעושים צביוני בעולם, פי' שעושים רצונו. הללוהו שמש וירח הוא בחי' התכללות עשי' ביצי' ונקראי' יצי' ועשי' בשם שמש וירח לפי ששמש הוא בחי' ז\"א וירח הוא בחי' מל' וז\"א מקננא ביצי' ומל' בעשיי'. הללוהו כל כוכבי אור הוא בחי' התכללות יצי' בבריאה ונק' בריאה ע\"ש כוכבי אור לפי שהכוכבים הם ברקיע תמינאה שהוא בינה אימא עילאה מלמטלמ\"ע, ואימא עילאה מקננא בבריאה כו' כנודע. ואח\"כ כתיב יהללו שם הוי' כי הוא צוה ונבראו, פי' נבראו ממילא כי אע\"פ שנאמר בראשית ברא אלקים שהבריאה היא משם אלקים אך זהו ברא לנוכח שהוא בחי' כח הפועל בנפעל אבל עיקר הבריאה הוא משם הוי' רק שהוא ע\"ד בחי' ונבראו ממילא בלתי התלבשות ע\"ד מי שאמר והי' העולם כו'. ויעמידם לעד לעולם שבחי' אלו הוא רק בחי' עמידה ועכ\"ז יש בזה ג\"כ הגדלה וריבוי וכמשי\"ת אי\"ה.\nה) <b>הללו</b> את ה' מן הארץ כו' אש כו' קחשיב בכאן ד' יסודות ארמ\"ע וד' מדרגות דצח\"מ, ומסיים הודו על ארץ ושמים וירם קרן לעמו כו' לבנ\"י עם קרובו, פי' הודו על ארץ ושמים בתחלה ארץ ואח\"כ שמים מפני כי מבחי' זו שמים מקבל מארץ, כי הודו קאי על התורה שזהו שביקשו המלאכים תנה הודך על השמים שביקשו שיתן להם התורה ולא ניתן להם כ\"א על הארץ ולכן בחי' זו מקבלים שמים דהיינו המלאכים מארץ דהיינו מנשמות, וזהו כמ\"ש היושבת בגנים חברים מקשיבים לקולך השמיעני, פי' היושבת בגנים קאי על הנשמות היושבים בג\"ע שלומדי' התורה"],[2000560269,"ברוחניות ומתענגי' מזיו השכינה חבירים מקשיבים לקולך קאי על מלאכי השרת שמקשיבים לשמוע מהם דברי תורה לכן בבחי' זו מקבלים שמים מארץ כו'.\n<b>וירם</b> קרן לעמו, הנה כתיב יראו את ה' קדושיו כי אין מחסור ליראיו, וצ\"ל מהו קדושיו דוקא, הלא כתיב יראו מה' כל הארץ, אך יראו מה' כל הארץ זהו מהוי' היינו בחי' יראה מרחוק, אבל את הוי' הוא קדושיו דוקא, כי פי' את הוי' שיהי' בטל וטפל לבחי' שם הוי' (כמ\"ש במ\"א בד\"ה וירא ישראל את היד הגדולה (תרח\"י)), זהו ע\"י קדושיו דוקא היינו ע\"י מעשה המצות שמברכין עליהם אשר קדשנו במצותיו וצונו, פי' וצונו יש בו ב' פי' הא' לשון ציווי, והב' לשון צוותא וחיבור, כי בחי' בריאת העולמות הוא רק מהארה בעלמא אבל ע\"י המצות נעשה צוותא וחיבור עם עצמיות אוא\"ס ב\"ה. וזהו כי אין מחסור ליראיו הנה אין הוא בחי' שאינו מושג כלל שהוא למעלה מבחי' סדר השתלשלות שסדר השתלשלות הוא מבחי' החכמה ואילך אבל אין הוא למעלה מן החכ' וכמ\"ש והחכ' מאין תמצא וע\"י בחי' היראה יכולים לבא לבחי' אין כמשי\"ת, כי אני הוא בחי' יראה הוא אותיות אין נעוץ סופן בתחלתן.\n<b>ובזה</b> יובן ענין וירם קרן, כי הנה נודע ממ\"ש בזהר על מארז\"ל ובא לו לקרן דרומית מזרחית כו' ובא לו לקרן בקדמיתא שמתחלה צ\"ל בחי' קרן ואח\"כ יוכל לבוא לבחי' דרומית שהוא בחי' אהבה הלוך ונסוע הנגבה. וענין הקרן הנה הקרן יש בו כמה פירושים, הא' לשון קרן זוית, הב' לשון מלוכה כמו קרן חזית בדניאל, הג' ל' קרן עור פני משה, והנה ענין הקרן זוית אינו מהות בפ\"ע כלל רק שהוא מחבר ב' הכתלים, כמו עד\"מ דרום ומזרח הנה כל הנמשך בדופן דרום הוא דרום והנמשך בדופן מזרח הוא מזרח והקרן נק' מקום חיבורם זל\"ז שאינו מהות בפ\"ע כלל, וכמו\"כ בחי' מלוכה נק' ג\"כ קרן כמ\"ש רמה קרני וארז\"ל דוד שנמשח בקרן נמשכה מלכותו כו', ששרש המלוכה והקרן הוא מבחי' רמה בחי' ע\"ק, וכן כתיב בדניאל (סי' ח' ה') והצפיר קרן חזית בין עיניו שקאי על מלוכה, והיינו מפני כי ענין המלוכה הוא ג\"כ אינו מהות בפ\"ע רק הוא בחי' חיבור המלך עם העם כי המלך הוא בפ\"ע והעם המה בפ\"ע וחיבורם הוא בחי' המלוכה ולכן נק' בשם קרן. ובנפש"],[2000560270,"האדם בעבודה בחי' קרן הוא בחי' קבעומ\"ש שהוא בחי' יראה. ולמעלה הוא בחי' מל' מלכותך מלכות כל עולמים. ופי' וירם קרן לעמו היינו שע\"י בחי' יראה יגיע לבחי' אין כי אין מחסור ליריאיו, ובאמת א\"א להגיע לבחי' אין כ\"א ע\"י יראה דוקא שהוא בחי' ביטול, כי אהבה הוא בחי' יש מי שאוהב, אבל יראה היא בחי' ביטול ולכן ע\"י יראה דוקא יכול להגיע לבחי' אין שלמעלה מן השגה. וז\"ע רוממות קרן והיינו כמו הפי' הג' בתיבת קרן שהוא מל' כי קרן עור פני משה והיינו ג\"כ כנ\"ל כי משה הי' בחי' מ\"ה ונחנו מה דהיינו בחי' חכמה וכתיב כי מן המים משיתיהו, ופי' קרן עור פני משה הנה ההארת פנים הוא בחי' שלמעלה מן משה בעצם והיינו בחי' אין שלמעלה מן החכ' כו', שזה זכה ע\"י התורה, לוחות העדות שקיבל בהר כמ\"ש בס\"פ כי תשא, וז\"ע רוממות קרן כו'.\n<b>והנה</b> בד\"כ ענין בחי' הביטול דשמים ומרומים ומלאכיו וצבאיו הוא להמשיך בחי' חיות העולמות בחי' ובטובו מחדש בכ\"י תמיד מע\"ב שצריך להיות אתעדל\"ת לזה והוא בחי' אתעדל\"ת דנבראים ומלאכים שהוא בחי' השירה שלהם כמשארז\"ל כל בעלי השיר יוצאין בשיר כו', וכמו\"כ נש\"י ע\"י עבודתם במו\"מ באמונה ממשיכים ג\"כ בחי' חידוש הישנות וכמ\"ש מזה בד\"ה זכור את יום השבת שע\"י העבודה במו\"מ באמונה שז\"ע מארז\"ל גדול הנהנה מיגיעו (ברכות דף ח'), עי\"ז ממשיכים בחי' ובטובו מחדש בכי\"ת מע\"ב, ע' בד\"ה זכור מקדשא וקיימא שבספר תרי\"ח בסופו, ובד\"ה זכור (ך\"ו). וע\"פ הקבלה הוא להמשיך זווג חיצוני דחו\"ב שזיווגייהו תדיר לצורך קיום העולמות כי בינה נק' יש כמ\"ש להנחיל אוהבי יש והחכ' נק' אין כמ\"ש והחכ' מאין תמצא וזיווגייהו תדיר שאל\"כ הי' חוזר העולם לתהו ובהו ואעפ\"כ צ\"ל אתעדל\"ת לזה והוא בחי' השיר והביטול של המלאכים כו'. וזהו ויעמידם לעד לעולם שבחי' זו נק' עומדים לפי שאין בה התחדשות כ\"א חידוש"],[2000560271,"הישנות והנה אף שנק' עומדים אעפ\"כ בבחי' עמידה גופא יש עליות וירידות וכמו שאנו רואים ששנה זו נשפע רוב טובות משא\"כ בשנה אחרת וכמו שבע שני השבע ושבע שני הרעב ובד\"כ נק' עמידה כנ\"ל לגבי הזווג פנימי דחו\"ב להמשיך בחי' אור חדש, אבל נש\"י ממשיכים אור חדש, וזהו וירם קרן שע\"י הרוממות קרן ממשיכים אור חדש מבחי' אין כו'."],[2000560272,"<h3>מגילה נקראת בי\"א כו'</h3>\n<b></b><b>בס\"ד, ויקרא ופ' זכור.</b>\nועשית ציץ - ה\"פ\nויקרא, פ' זכור\n<b>מגילה</b> נקראת באחד עשר כו' בחמשה עשר לא פחות ולא יותר, כרכים המוקפים חומה מימות יהושע בן נון קורין בחמשה עשר. וצ\"ל מפני מה לא פחות ולא יותר, וגם צ\"ל מה שבכרכים המוקפים חומה מימות יהושע בן נון קורין בט\"ו הלא הנס הי' בבבל דהיינו בשושן שהוא בעילם המדינה וא\"כ מה שייך לשנות הכרכים שמוקפות חומה שבא\"י.\n<b>הנה</b> כתי' ויקרא אל משה שהוא ל' חיבה כמ\"ש בזהר ל' אוקיר אנוש מפז (ישעי' י\"ג פסוק י\"ב) וכתיב ולא קם נביא עוד בישראל כמשה וארז\"ל במד\"ר ס\"פ במדבר ס\"פ י\"ד דרס\"ד ע\"ד (הוא דנ\"ה ע\"ד) תני ולא קם נביא כו' בישראל לא קם אבל באוה\"ע קם ומנו בלעם [וכ\"ה בזח\"ג בלק קצ\"ג ע\"ב, ובלק\"ת מהאריז\"ל פ' בלק כי משה הי' נבואתו מיסוד אבא שהוא דעת עליון שבז\"א, וכן בבלעם נא' ויודע דעת עליון, ובמאו\"א ב' סט\"ו בלעם קליפה מקבלת ליסו\"א דעת דז\"א, ומקבל אורו כנגד מקום גילוי דעת בין עקבי לאה עכ\"ל, ובי\"נ העיר מזח\"ב יתרו דע\"ט, ומלק\"ת פ' בלק הנ\"ל. וי\"ל כי בלעם הי' השגתו מאצי' דקליפה שנת' ענין אצי' דקליפה בד\"ה אם בהרת קדמה, ומעמד קלי' דאצי' הוא בבריאה], ובמד\"ר ע\"פ ויקרא אל משה מה"],[2000560273,"בין נביאי ישראל לנביאי אוה\"ע רב חמא בר חנינא אין הקב\"ה נגלה על נביאי אוה\"ע אלא בחצי דבור שנאמר ויקר אלקים אל בלעם, אבל נביאי ישראל בדבור שלם שנא' ויקרא אל משה, ר' ישכר דכפר מנדו אין ויקר אלא לשון טומאה כמ\"ד אשר לא יהי' טהור מקרה לילה, וצ\"ל מהו שייך לומר בנבואה לשון טומאה כו'.\n<b>והנה</b> בלעם ועמלק הוא בחי' אחת כמ\"ש בזהר [אפ\"ל כוונתו בזח\"ג בלק דקצ\"ד א'], והיינו כי אותיות עמל הוא בבלעם וגם בעמלק רק שעמלק הוא עמל קו\"ף ובלעם הוא עמל בי\"ת ולכן הם בחי' אחת, והנה כששלח ה' את שאול להחרים את עמלק אמר שאול לשמואל בבואו מן המלחמה הקימותי את דבר ה', ושמואל השיב לו מאסת את דבר ה' והיינו מפני שחמלו על מיטב הצאן, וצ\"ל מפני מה הי' גדול כ\"כ חטא שאול הלא ע\"פ הטעם הי' נכון מה שלא החרים את הצאן והבקר בכדי להקריב מהם קרבנות, ומפני מה הי' גדול עוונו מנשוא עד שאמר לו שמאול מאסת את דבר ה'. אך הענין הוא דהנה עמלק א\"א כלל שיתברר שנא' בו ואחריתו עדי אובד.\nב) <b>ויובן</b> כ\"ז בהקדים הפסוק ועשית ציץ זהב טהור כו', פי' ציץ יש בו ב' פירושים, הא' לשון הארה כמו נץ החמה, יציץ נזרו, יציץ ופרח ישראל, שהוא מלשון הארה כו'. הב' מלשון הבטה וראי' מלשון מציץ מן החרכים וכמו שפרש\"י על מציץ ל' הבטה ע\"ד מ\"ש ראה ראיתי את עני עמי כו'.\n<b>ולהבין</b> ב' הפירושי' צ\"ל תחלה פי' הא' שהוא לשון הארה, הנה הציץ הי' אהרן נושא אותו על מצחו, והנה אהרן הי' אחד מז' רועים שהיו מפרנסים נש\"י והיינו שאהרן המשיך בחי' אהבה רבה לנש\"י, והגם שארז\"ל [ברכות פ\"ה דל\"ג, מגילה פ\"ב דכ\"ה, נדה פ\"ב דט\"ז] הכל בידי שמים חוץ מיראת שמים א\"כ אהוי\"ר תלוי' הם בעבודת האדם מלמטלמ\"ע, אך הנה באמת יש שני בחי' אהוי\"ר, הא' הוא בחי' אהוי\"ר מלמטלמ\"ע, הב' הוא בחי' אהוי\"ר הבאה לאדם מלמעלה למטה (בבחי' מתנה), וכמ\"ש אהבתי אתכם אמר הוי', ובחי' אהוי\"ר שמלמעלמ\"ט זהו בחי' המשכת"],[2000560274,"אהרן כו'. וזהו מ\"ש בזהר שיש ד' בחי' דחילו ורחימו ורחימו ודחילו כנגד ד' אותיות הוי', והיינו כנ\"ל שבחי' דחילו ורחימו הוא בחי' אהוי\"ר הבאה בעבודת האדם מלמטלמ\"ע והוא בחי' ו\"ה של שם הוי', ובחי' רחימו ודחילו הוא בחי' אהוי\"ר הבאה מלמעלמ\"ט בחי' י\"ה של שם הוי', ובחי' אהבה זו הבאה מלמעלמ\"ט זהו בחי' אה\"ר שממשיך אהרן כה\"ג לנש\"י, אך א\"א לבוא לבחי' אה\"ר הבאה מלמעלה כ\"א שיהי' לו תחלה בחי' אהוי\"ר מלמטלמ\"ע ואז יוכל לקבל בחי' אהוי\"ר הבאה מלמעלה [ע\"ד מ\"ש בת\"א בד\"ה ויקהל שרצון התחתון הוא כלי לבחי' רצון העליון המאיר ומתגלה בשבת, וע\"ד בחי' חסד עולם דז\"א הוא כלי לבחי' רב חסד דא\"א כמ\"ש בכ\"ד, וע' בד\"ה יביאו לבוש מל' שלא נדפס], וזהו ציץ ל' הארה והיינו שהוא בחי' הארת אור האה\"ר הבאה מלמעלמ\"ט.\n<b>והפי'</b> הב' הוא ציץ מל' מציץ, מציץ מן החרכים ל' הבטה וראי', הנה כתיב כי עין בעין יראו (ישעי' נ\"ב ח') וכתי' כי עין בעין נראה (שלח י\"ד י\"ד) נראה אותיות אהרן, והיינו כי אהרן ממשיך בחי' כי עין בעין. והענין הוא דהנה הבריאה יש מאין והיינו לפי שמלכותך מלכות כל עולמים וכמ\"ש כי בי\"ה הוי' צור עולמים וארז\"ל במנחות ובמד\"ר ביו\"ד נברא העוה\"ב ובה' נברא העוה\"ז שהוא רק משני אותיות, וכמשל ענין המלוכה הוא רק מלך שמו נקרא עליהם, וזהו שאנו אומרים ישתבח שמך והיינו בחי' מל' כי המקור לכל התהוות הנבראים הוא מבחי' המל', וזהו מ\"ש לכו חזו מפעלות אלקים אשר שם שמות א\"ת שמות אלא שמות שהכל נברא רק מבחי' שם והארה, ולכן הוא בחי' יש מאין שנתהווה העולם ליש ודבר מבחי' אין. אך הנה כתיב כי אל דעות הוי' שיש ב' דעות ד\"ת וד\"ע והיינו כי ד\"ת הוא כנ\"ל שלמטה היש ולמעלה האין, וד\"ע הוא בהיפוך שלמעלה הוא היש האמיתי ולמטה הוא בחי' אין, ובאמת צ\"ל איך שייך לומר שהעולם וכל הנבראים המה בחי' אין הלא אנו רואים שלמטה הוא בחי' יש כו', אך הענין הוא מאחר ששרש ומקור בחי' הנבראי' הוא בחי' אין בחי' שם והארה כנ\"ל שאינו תופס מקום כלל דבאמת כולא קמי' כלא חשיב (רק שאינו מושג בד\"ת), א\"כ גם מה שנברא ונראה העולם ליש ודבר אינו שהוא באמת יש ודבר כי הלא גם מקור המהוה בחי' זו הוא ג\"כ רק בחי' אין, כ\"א המכוון כך הוא שהגם שנראה העולם לבחי' יש ודבר כו', מ\"מ יהי' בחי' ביטול היש לאין, והוא מחמת ההתבוננות זו עצמה מיני' ובי' איך שמקורה ושרשה הוא רק הארה בעלמא בחי' אין. [והרי הוא רק כמו ערך שם האדם לגבי עצמותו שאינו בערך"],[2000560275,"כלל, וממילא ההתהוות שנתהוה מבחי' הארה זו לא יתכן שיהי' בבחי' יש יותר מן בחי' זו עצמה המהוה אותה, ודי לבא מן הדין להיות כנדון, א\"כ אין זה אלא מחמת ההסתר שהוא ית' אל מסתתר להיות נראה ליש ודבר, אבל צריך להבין שבאמת בטל היש לאין, וכענין וכל צבא השמים לך משתחוים]. ואח\"כ יוכל לבוא ולהשיג בחי' דיעה עליונה איך דכולא קמי' כל\"ח וכל מה שהוא קמי' יותר כלא חשיב יותר בבחי' ביטול אמיתי, וזהו כי עין בעין נראה אותיות אהרן כי אהרן ממשיך שיומשך בחי' עין דלעילא בחי' ד\"ע בעין דלתתא בחי' ד\"ת. וזהו ציץ לשון הבטה וכמו שפירש\"י מציץ ל' ראה ראיתי כו' בחי' ראי' והיינו בחי' ראי' דדעת עליון.\n<b>ובאמת</b> ב' הפירושים של ציץ הוא אחד, דהיינו כשיש בחי' ד\"ת היינו בחי' ביטול היש לאין שהוא בחי' אהוי\"ר הבאה מלמטלמ\"ע בעבודת האדם כנ\"ל, אזי נמשך ע\"י אהרן כהנא רבא בחי' אה\"ר להיות עין בעין נראה, שיאיר בחי' עין דלעילא בעין דלתתא, וזהו בחי' אה\"ר הבאה מלמעלה בבחי' מתנה, וכמ\"ש עבודת מתנה אתן כו'.\nג) <b>והנה</b> כמו\"כ יש ב' בחי' אלו דד\"ת ודעת עליון בתפלה, כי הנה תחלה הוא בחי' שמע, שם עי\"ן, פי' עי\"ן הוא ז' מדות כשהם כלולים מיו\"ד, ושם עי\"ן הוא בחי' הארה מעי\"ן דהיינו בחי' מל' שהוא בחי' אין שממנו נברא העולם ליש כו', וזהו שמקדימין פסוד\"ז דהיינו איך שהמלאכים וכל צבא השמים אומרים שירה ובטלים לפניו ית' שזהו מ\"ש הללוי' הללו את ה' מן השמים יהללו את שם ה' כי הוא צוה ונבראו כו', וזהו שאומרים עשר פעמים הללויה נגד עשרה מאמרות בכדי להתבונן כנ\"ל שכל צבא השמים המה בטלים, ואזי גם הוא יוכל לבוא לבחי' ביטול היש שזהו ההתבוננות בבחי' שמע שם עי\"ן בחי' ביטול היש ד\"ת. ואח\"כ בחי' ישראל הוא למעלה מבחי' ד\"ת ע\"ד מ\"ש בן פורת יוסף בן פורת עלי עין למעלה מבחי' עי\"ן דדעת תחתון, וע\"י ההתבוננות בבחי' ה' אלקינו ה' אחד הוא בחי' ד\"ע להכיר איך דכולא קמי' כלא חשיב, וזהו בחי' אחד שהוא ז' רקיעים וארץ עכ\"ז כולא קמי' כלא חשיב ובטלים לגבי בחי' אל\"ף אלופו של עולם שהוא היש האמיתי כו', וכאשר מתחלה יש בחי' ד\"ת ביטול היש דהיינו בחי' יחו\"ת אזי יוכל לבא לבחי' ד\"ע בחי' יחו\"ע."],[2000560276,"<b>ועפי\"ז</b> יובן ענין חטא דור המדבר במה שאמרו היש הוי' בקרבנו אם אין, וארז\"ל במד\"ר ובילקוט רמז רס\"ב משל לבן מלך שהי' מורכב על כתיפו של אביו ושאל איה אבא כו' השליך האב את הבן בא הכלב ונשכו, כך הקב\"ה הוציא את בנ\"י ממצרים ושאלו היש הוי' השליך אותם מיד ויבא עמלק. ולהבין ענין החטא שלהם, הענין הוא דהחטא שלהם הי' מה שלא האמינו שנבואת משה הי' גבוה משאר הנביאים (כמו אפי' אברהם יצחק ויעקב) ובאמת כתיב וארא אל אברהם כו' באל שדי ושמי הוי' לא נודעתי, ופי' הרמב\"ן שם שדי הוא מקור לנסים מוסתרים אכן שם הוי' הוא מקור לנסים הנגלים ולהם הראו נסים נגלים יוצאים מדרכי הטבע לגמרי כמו יצ\"מ וקי\"ס שהם נסים בגלוי, א\"כ הי' להם להאמין שנבואת משה הי' הגבה מכל הנביאים, והם לא האמינו ואמרו היש הוי' כו'. וע\"פ הקבלה היש הוי' בחי' ז\"א אם אין הוא בחי' מל' והם לא ידעו אם נמשך מבחי' ז\"א ד\"ע או מד\"ת בחי' אין מל', וזהו החטא שלהם מיד ויבא עמלק כו' והיינו שקליפת עמלק היא מסתרת על בחי' ד\"ע שהוא הקליפה הלעו\"ז כו', שזהו ענין יודע את רבונו ומכוין למרוד בו, שהוא הלעו\"ז נגד בחי' ד\"ע כו'. וזהו מ\"ש הנה זה עומד אחר כתלינו משגיח מן החלונות מציץ מן החרכים, פי' כתלינו, הנה כתיב ביחזקאל (סי' ד' ג') ונתתה אותה קיר ברזל בינך ובין העיר ולמדו רז\"ל מזה בברכות פ' אין עומדין משחרב בהמ\"ק חומת של ברזל מפסיק בין ישראל לאביהם שבשמים, ולכאורה צ\"ל הלא מצינו קיר לשבח כמ\"ש גבי אלישע נעשה נא עלית קיר קטנה ונשים לו שם כסא ושולחן ומטה ומנורה, ואיתא בזהר שזהו בחי' ד' תקוני שכינתא, וגם ארז\"ל ע\"פ ויסב חזקיהו פניו אל הקיר מכאן למתפלל שלא יהי' דבר חוצץ בינו לבין הקיר כו'. והענין הוא דהנה איתא בזהר שקיר הוא בל' יון אדון, והיינו בחי' שם אדנ\"י שזהו ההפרש בין שם הוי' לשם אד', כי שם הוי' כשמו כן הוא בלא קץ ותכלה, ואם הי' בריאת העולמות משם הוי' לא הי' העולם בבחי' יש ודבר כ\"א בבחי' ביטול, וכדי שיהיו העולמות בבחי' יש זהו ע\"י שם אד' שמסתיר ומעלים על אור קדושת שם הוי' כדי שיהי' מקור לעולמות הנבראים ונפרדים כו' כנ\"ל. והנה זהו עבודת האדם להמשיך בחי' שם הוי' להיות יחוד הוי' ואלקי' (כי שם אד' ושם אלקים הכל אחד) כמ\"ש שמש ומגן הוי' אלקים, וזהו כותל דקדושה כי כותל הוא כ\"ו ת\"ל, כ\"ו הוא גימט' של שם הוי', ת\"ל גימט' ה\"פ אלקים להיות יחוד הוי' ואלקים. וזהו מ\"ש ויסב חזקי' פניו אל הקיר והיינו שהמשיך בחי' פניו שהוא מ\"ש יאר הוי' פניו בבחי' קיר בחי' אדון שם אד', וכמו\"כ המתפלל צריך שלא יהי' דבר חוצץ בינו לבין הקיר כו' כי המכוון הוא להמשיך בחי'"],[2000560277,"הוי' באמרו ברוך אתה הוי' ברוך לשון המשכה בשם אד' ולכן צריך שלא יהי' דבר חוצץ כו', וזהו כתלינו כותל דקדושה.\nד) <b>והנה</b> לעו\"ז הוא בחי' כותל דעמלק המסתיר ומעלים שלכן נק' קיר ברזל כי ברזל הוא ב\"פ ק\"ך והיינו נגד בחי' ק\"כ צירופי אלקים דקדושה ונגד ק\"כ צירופי אלקים אחרים, ולכן הוא מסתיר ומעלים לגמרי וזהו מ\"ש במד\"ר ס\"פ תרומה ע\"פ וזאת התרומה אשר תקחו מאתם זהב וכסף ונחושת, זהב זו בבל כסף זו מדי נחושת זו יון, אבל ברזל אין כתיב כאן והיינו כי ברזל הוא נגד מחריבי בהמק\"ד שא\"א לבררה כלל. וכמשארז\"ל במד\"ר שם שגם לע\"ל לא יקובל ממנה נדבה כו', והיינו כמ\"ש ראשית גוים עמלק ואחריתו עדי אובד, והיינו שאחרית של עמלק היינו מחריבי בהמק\"ד א\"א לברר אותה כלל כ\"א שברתו זהו תיקונו כמשי\"ת לקמן וזהו דכתי' (מ\"א וא\"ו ז') והבית בהבנותו אבן שלימה כו' והמקבת וכל כלי ברזל לא נשמע בבית בהבנותו וכמו שארז\"ל (מדות פ\"ג משנה ד') שהברזל פוסל בנגיעה והיינו מטעם הנ\"ל שמבחי' ברזל א\"א לברר כלל וזהו בחי' עמלק כי חושבנא דדין כחושבנא דדין שברזל עם הכולל גימ' עמלק, שזהו מ\"ש מלחמה להוי' בעמלק והיינו כמו שארז\"ל אין השם שלם ואין הכסא שלם עד שימחה זרעו של עמלק, פי' אין השם שלם שי\"ה אינו מאיר בו\"ה, פי' יו\"ד ה' של שם הוי' הוא בחי' סוכ\"ע כי בינה מקור המקיפים ועמלק מונע הגילוי מבחי' יו\"ד ה' בו\"ה וכמו\"כ אין הכסא שלם כי כסא הוא כס אל\"ף, פי' שמכוסה בחי' אלף אלופו ש\"ע כי הנה צריך להיות נכון כסאך מאז, פי' שכדי שיהי' נכון כסאך זהו מאז דוקא היינו כשמאיר מא' בז' ז' מדות [ובכסא זהו שית דרגין לכורסיא והכסא עצמה], ועמלק הוא היפך זה ונק' ע\"ש עמלק מפני שעמלק הוא ראשית גוים כמ\"ש ראשית גוים עמלק, פי' גוים הם ז' מדות הרעות בחי' ז' אומות הכנעני כו' והפריזי וראשית גוים אלו זהו עמלק דוקא, וזהו מארז\"ל הקנאה והתאוה והכבוד כו' הוא בחי' מדות רעות וכבוד הוא בחי' לבושי' שהוא היפך לבושי כה\"ג שהי' בקדושה, וזהו אין השם שלם ואין הכסא שלם עד שימחה זרעו של עמלק ולאחר שימחה זרעו של עמלק, אז אח\"כ יהי' הגילוי בחי' י\"ה בו\"ה, ובזה יובן מה שחטא שאול במה שרצה להקריב קרבנות משלל עמלק"],[2000560278,"והיינו כנ\"ל שעמלק הוא בחי' קיר ברזל היפך בחי' בהמ\"ק דקדושה שלכן לא הי' ברזל בבנין בהמ\"ק והברזל פוסל בנגיעה לכן א\"א להביא קרבנות ג\"כ משלל עמלק כי א\"א להעלות בחי' עמלק כלל, וזהו שאמר לו שמואל מאסת את דבר ה' שהוא היפך מבחי' בהמ\"ק, ולכן משחרב בהמ\"ק כותל של ברזל מפסיק בין ישראל לאביהם כו', כי כשזה נופל זה קם ופי' בין ישראל לאביהם שההפסקה היא מחמת ישראל כי לפניו ית' אין דבר חוצץ כי כחשכה כאורה אכן מחמת בחי' נש\"י הוא ההפסק שזהו מ\"ש עוונותיכם היו מבדילים שע\"י העון הוא מסך מבדיל בחי' עמלק קיר ברזל, והעצה לזה הוא בחי' תשובה שע\"י לב נשבר ונדכה עי\"ז שוברים הכותל להיות מציץ מן החרכים ומשגיח מן החלונות והיינו אף שאין שוברים כל הכותל עכ\"פ עושים עי\"ז חלונות וחרכים להיות מאיר אור א\"ס ב\"ה ע\"י חלונות וחרכים כנ\"ל וכמו שע\"י החלון מאיר בחי' השמש, כמו\"כ ע\"י חלונות אלו מאיר בחי' שמש הוי' כו', וכדי לשבר את הכותל של ברזל הנ\"ל להיות נעשה בה חלונות וחרכים זהו ע\"י בחי' משה, וזהו ועשית ציץ כו' שמשה הוא העושה ומשבר בחי' כותל דעמלק, ולכן תלוי מלחמת עמלק במשה כמ\"ש והי' כאשר ירים משה ידו וגבר ישראל וכאשר יניח כו', וביאור הענין הנה התורה נק' תורת משה כמ\"ש זכרו תורת משה עבדי וכמ\"ש תורה צוה לנו משה, וצ\"ל מפני מה נק' התורה תורת משה, הנה ארז\"ל במד\"ר פ' ויקרא ע\"פ גבורי כי עושי דברו לשמוע בקול דברו בנוהג שבעולם משאוי שקשה לאחד נוח לשנים לשנים נוח לארבעה שמא תאמר משאוי שקשה לס' רבוא נוח לאחד כך ס' רבוא ישראל לא יכלו לקבל הדבור מפי הקב\"ה שנאמר אם יוספים אנחנו ומשה שמע הדבור מפי הקב\"ה וחיה, וזהו גבורי כח כו' לשמוע בקול דברו, פי' שמע הדבור הוא בחי' דבר ה', והנה הדיבור הוא גילוי ההעלם שהוא גילוי המחשבה כו', ופי' בקול דברו היינו בפנימיות הקול דהיינו מה שמאיר בבחי' הקול ובחי' זו לא יכלו נש\"י לקבל כי זהו בחי' פנימיות דבר ה' הוא בחי' ד\"ע כ\"א משה שהי' מן המים משיתיהו, פי' בחי' מים עליונים שלמעלה מן הרקיע המבדיל ופרסא ראשונה לכן הי' יכול לקבל בחי' זו, ולכן נמשלה התורה ג\"כ ע\"י משה דוקא עד שנק' תורת משה עבדי כי הוא עלה שמים וירד כו', ומחמת שהי' בחי' גבוה מאד מן המים משיתיהו לכן הי' יכול ג\"כ להעביר קליפת עמלק, והיינו מחמת עוצם הגילוי שהמשיך משה ממילא נדחה הרע של עמלק, וכמו שע\"י האור ממילא נדחה החושך, ולכן תלוי מלחמת עמלק במשה דוקא, וזהו ועשית ציץ, פי' שמשה הוא"],[2000560279,"העושה הציץ לאהרן כהנא רבא להיות כי משה המשיך בחי' תורה עי\"ז ממילא נדחה החשך, זהב טהור הוא ע\"ד מ\"ש ממולח טהור קדש פי' מעורב טהור בקדש להיות נמשך בחי' קדש בטהור שבחי' זו היא שרש נש\"י כמ\"ש נשמה שנתת בי טהורה היא.\nה) <b>ופתחת</b> עליו פתוחי חותם, הנה ארז\"ל חותמו של הקב\"ה אמת אני ראשון ואני אחרון ומבלעדי אין אלקים, ואין אמת אלא תורה ונמשלה לחוצתם כמו החותם כאשר היא חקוקה על האבן טוב הנה מחמת רוב בהירות האבן אין יכולים לקרות האותיות כ\"א עד שיחתום בהחותם על השעוה הנה מחמת גסות השעוה ניכרים האותיות היטב, אך עכ\"פ הנה האותיות שעל השעוה הם האותיות ממש שעל האבן טוב, כך יובן בנמשל למעלה שהתורה הגם שירדה למטה ונתלבשה בדברים גשמיים הנה עכ\"ז שורש התורה היא היא ממש כמו שהיא הגבה למעלה רק שנתלבשה בדברים גשמי' כו', ולכן ע\"י בחי' התורה נדחה הרע של עמלק, וזהו חותם אותיות חומת והיינו שע\"י החותם דתורה נדחה בחי' החומת בחי' קיר ברזל דעמלק, אך הנה כ\"ז הוא כשהתורה הוא בחי' תורת משה דהיינו כשלומד התורה בבחי' ביטול כמו משה שהי' בבחי' ביטול כמ\"ש ונחנו מה, כמו\"כ צ\"ל לימוד התורה ג\"כ בבחי' ביטול, קדש להוי' פי' בפרדס שהוא בחי' המשכת קדש להוי'. וביאור הענין הנה יש קדש וקדוש, קדוש הוא בחי' קדש ו', המשכת בחי' הוא\"ו כדי שיהי' אחריו בחי' ה' אחרונה שזהו מה שאומרים קדוש ק\"ק ה' צבאות, והיינו שכדי שיהי' בחי' ה' צבאות זהו ע\"י בחי' וא\"ו, וזהו קדש וא\"ו היינו המשכת הוא\"ו, משא\"כ בחי' קדש הוא מובדל, והנה כתיב שאו ידיכם קדש וברכו את הוי', וזהו בחי' קדש להוי' המשכת בחי' קדש להוי' בבחי' ברכה כמ\"ש וברכו את הוי' שזהו בחי' ברכה והמשכה בשם הוי', ועוי\"ל בפי' קדש להוי' ע\"ד משארז\"ל קדש למד מלמטה והוי' מלמעלה א\"כ שם הוי' גבוה מבחי' קדש, אך באמת שניהם אמת, כי הנה כתיב ויקרא הוי' הוי' שיש ב' שמות הוי' שם הוי' דלעילא ושם הוי' דלתתא, והנה לגבי בחי' שם הוי' דלתתא שהוא מקור להתהוות העולמות כנ\"ל א\"כ קדש להוי' הוא בחי' המשכה בשם הוי', אך לגבי שם הוי' דלעילא הנה בחי' קדש למטה במדרגה ולכן קדש למד מלמטה והוי' מלמעלה כו', והי' על מצח אהרן כו' תמיד לרצון, פי' מצח חופה על המוחין פי' להיות כי אף כשמתבונן היטב ומוליד בנפשו בחי' אהוי\"ר אשר עי\"ז מאיר בחי' אה\"ר הנה הוא רק בשעת התפלה אבל אחר התפלה החולפת ועוברת האה\"ר לזה הוא בחי' המצח בחי' נצחון, והיינו שמחמת ההתבוננות יהי' נעשה אצלו ההסכם חזק להיות יתד תקוע במקום נאמן וזהו תמיד לרצון שההסכם שנעשה הוא תמיד כו', שגם לאחר התפלה שחולף ועובר ההתבוננות מ\"מ ישאר ההסכם הנעשה ע\"י התבוננות התפילה כו'.\nוא\"ו) <b>ומעתה</b> יובן מ\"ש ויקרא אל משה, ובבלעם נאמר ויקר אלקים כו' לשון טומאה כמ\"ש אשר לא יהי' טהור מקרה לילה, שלכאו' צ\"ל איך נופל הלשון מקרה על נבואה, שבלעם הי' נביא בלעו\"ז נגד בחי' משה בקדושה, הנה על עמלק אמרו שהוא כקוף בפני אדם [והיינו כמ\"ש במאו\"א אות קו\"ף סי' א' הובא"],[2000560280,"בערה\"כ של הסה\"ד שס\"א נגד הקדושה הם כקוף בפני האדם, והוא היפך ה\"א דקדושה], פי' קוף בפני האדם כי הנה איתא בספרים שהקוף הוא היפך בחי' הה\"א, כי הה\"א הוא בחי' ג' קוין ב' קוין מחוברים רומזים לבחי' מחשבה ודבור דקדושה והקו הנפסק רומז לבחי' המעשה דקדושה, ועמלק הוא היפך זה ממש שזהו פי' כקוף כמו תמונת קו\"ף הוא ג\"כ ב' קוין מחוברים אכן קו השלישי נמשך למטה, והיינו שממשיך המחשבה דיבור ומעשה בקליפות וזהו כקוף בפני האדם כי אדם הוא ג\"כ מחדו\"מ אל\"ף בחי' מחשבה, ד' מ' הוא דבור ומעשה, ועמלק הוא בחי' קו\"ף שממשיך בחי' מחדו\"מ בקליפות, וזהו עמלק עמל קו\"ף, פי' שהעמל שלו להמשיך בחי' הקו\"ף דהיינו להיות רגליה יורדות מות, וזהו עיקר העמל שלו שזהו מ\"ש ורהבם עמל ואון כו'.\n<b>ולכן</b> נק' נבואה שלו ע\"ד מקרה כו', כי הנה איתא בס\"י ברית כרותה בין עשר אצבעות ידיו ובין עשר אצבעות רגליו ברית הלשון מכוון כנגד ברית המעור, והיינו שכמו שיש פגם בברית המעור כן יש פגם בברית הלשון, ולכן איתא בספרים שכאשר פוגם בברית הלשון אזי יוכל לבא ח\"ו לפגם ברית המעור, והיינו כמו שפגם ברית המעור הוא כאשר יוצא השפע פנימית לחיצוני', כן הוא ממש ברית הלשון כאשר מדבר דברים בטלים אשר לא לה' המה וכ\"ש רכילות ולה\"ר, שנמשך ג\"כ בחי' הדיבור שלו לבטלה שהדבור הוא ג\"כ שפע פנימיות שנלקחה מן עצם הנפש כמ\"ש ויהי האדם לנפש חי' ות\"י לרוח ממללא כו', כך יובן למעלה ג\"כ שכאשר נמשך השפעת בחי' דבר נבואה לבלעם הוא כדוגמת מקרה כו' והיינו שנמשך הארת הדיבור למקום הקליפות, ויקר אלקים שבחי' זו נמשך מחמת בחי' אלקים כי יש ק\"כ צירופי אלקים דקדושה, ולעו\"ז יש ק\"כ צירופי אלקים אחרים דקליפה, והנה מבחי' מ\"ח צירופים אחרונים יכול בלעם ג\"כ לקבל ולכן נק' בחי' מקרה כו', משא\"כ גבי משה כתי' ויקרא ל' חיבה וכמ\"ש בזהר ל' אוקיר אנוש מפז ל' יקר, והנה יקר וקיר דקדושה גימט' כתר, ולעו\"ז קרי דעמלק ובלעם וקיר ברזל"],[2000560281,"גימט' כרת כתר דקליפה, והיינו שע\"י בחי' משה כתר דקדושה נדחה בחי' כרת כתר דקליפה בחי' עמלק.\n<b>וזהו</b> מגילה נקראת באחד עשר כו' בחמשה עשר לא פחות ולא יותר, כי הנה אחד עשר הוא בחי' ו\"ה וחמשה עשר הוא בחי' יו\"ד ה\"א, והנה כתי' מלחמה להוי' בעמלק וארז\"ל אין השם שלם כו', ולכן ע\"י נס דפורים כשנהרג המן שהי' מעמלק הי' חיבור בחי' ו\"ה בי\"ה, וזהו כרכים המוקפים חומה קורים בט\"ו, והיינו כי הקפת החומה תלוי ביהושע בן נון שיהושע הי' לעומת בחי' קיר ברזל, כי יהושע הי' מל' דקדושה בחי' לבנה כי ארז\"ל פני יהושע כפני לבנה, ולכן תלוי מלחמת עמלק גם ביהושע כמ\"ש ויחלוש יהושע את עמלק [וכמ\"ש בזח\"ב דס\"ה ע\"ב שמשה הי' לקרבא דלעילא ויהושע לקרבא דלתתא], ולכן כרכים המוקפים חומה קורים בט\"ו זהו ע\"ד בן כרך שראה את המלך, שנבואת ישעי' הי' בבריאה שראה השרפים שאומרים קדוש ורוצים ליבטל כו' כי אימא מקננא בכורסייא ולכן קורים בט\"ו בחי' י\"ה, משא\"כ כפרים ועיירות גדולות קורים בי\"ד ע\"ד והכפרים מקדימי' ליום הכניסה, זהו ע\"ד בן כפר שראה את המלך כו'."],[2000560282,"<h3>ויהי אומן את הדסה כו'</h3>\n<b>בס\"ד.</b>\nויהי אומן את הדסה היא אסתר, וכתי' ותיטב הנערה בעיניו ותשא חסד לפניו, ותהי אסתר נושאת חן בעיני כל רואיה, וארז\"ל במגילה די\"ג ע\"א ודט\"ו ע\"א ר' יהושע בן קרחה אמר אסתר ירקרוקת היתה וחוט של חסד משוך עליה.\n<b>והענין</b> הוא דהנה כתיב שקר החן והבל היופי אשה יראת ה' היא תתהלל וארז\"ל בסנהדרין פ\"ב דף ך' ע\"א, ובילקוט ש\"א רמז קל\"ו, שקר החן זה דורו של משה, והבל היופי זה דורו של יהושע, אשה יראת ה' היא תתהלל זה דורו של חזקי' שהיו יושבין ועוסקין בתורה, איכא דאמרי שקר החן זה דורו של משה ויהושע, והבל היופי זה דורו של חזקי', אשה יראת ה' היא תתהלל זה דורו של ר' יהודה בר' אלעאי שהיו ששה מתכסין בטלית א' ויושבין ועוסקין בתורה. ולהבין זה הנה כתיב אם לא תדעי לך היפה בנשים, והנה היפה בנשים גימ' ארור המן, וגם גימ' ברוך מרדכי."],[2000560283,"<b>ולהבין</b> כ\"ז צריך להבין מקודם מה שכנס\"י נק' בשם רחל וגם בשם אסתר כו', והענין הוא דהנה כתי' ורחל היתה יפת תואר ויפת מראה, והנה תואר נק' חיתוך האברים שהם לפי ערך, שכל אבר ואבר לפי ערכו ותמונתו נק' תואר, ומראה נק' קלסתר פנים שהיא שופרי' וזיוו, ורחל היתה יפת תואר ויפת מראה שהי' לה ב' המעלות בציור תמונת האברים וגם בבחי' זיו וקלסתר פנים כו'. והענין הוא בעבודה דהנה תואר שהוא בחי' ציור האברים זהו ענין רמ\"ח פקודין שהוא רמ\"ח אברים דמלכא, ויפת מראה הוא בחי' שס\"ה ל\"ת כי שרש השס\"ה ל\"ת הם בבחי' י\"ה שהוא בחי' חכ', וכתיב חכמת אדם תאיר פניו כו' שהוא בחי' זיו והארת פנים כו'. [וע' בלק\"ת בביאור שחורה אני המתחיל הנה בין המאציל פ\"ו, שבחי' הארת פנים הוא מבחי' תיקון הז' די\"ג ת\"ד דא\"א בחי' ואמת שפנוי משערות והיינו מבחי' עצמיות חכ' שבכתר שלמעלה מבחי' צומח (היינו השערות בחי' ושער רישי' דא\"א הנמשך ע\"י מצות עשה) ושהרמ\"ז ר\"פ ויקרא כ' שבתיקון ואמת מאיר דעת דעתיק המאיר ברישא דאריך דדעת אסהיד באנפין, היינו בחי' תרין תפוחין בחי' הארת פנים שמעצמיות ח\"ס מאיר ומתגלה בתיקון ואמת המתגלה בפנים, אך גילוי בחי' זה יהי' לע\"ל דוקא כמ\"ש בביאור הנ\"ל בפ\"ג באריכות ושזהו פי' ונאוה לע\"ל ע\"י קיום מצות ל\"ת, ועיין מענין הארת פנים ומענין ואמת בביאור אלה מסעי הג' המתחיל הנה גבי המסעות פ\"ד דצ\"ג ע\"ב].\n<b></b>[המשך המאמר נמצא לקמן בהמאמר שלאח\"ז ד\"ה ויהי אומן (הב') פרק א' פיסקא: והנה פי' יפת תואר]."],[2000560284,"<h3>ויהי אומן את הדסה</h3>\n<b>בס\"ד. (פורים, רכ\"ז).</b>\n<b>ויהי</b> אומן את הדסה היא אסתר, וארז\"ל מגילה די\"ג א', קרי לה הדסה וקרי לה אסתר, תניא ר\"מ אומר אסתר שמה ולמה נק' שמה הדסה ע\"ש הצדיקי' שנקראו הדסים שנא' והוא עומד בין ההדסים (זכרי' א'), ר' נחמי' אומר הדסה שמה ונק' אסתר שהיו עכו\"ם קורי' אותה אסתהר ופי' רש\"י ירח יפה כלבנה, ר\"י בן קרחה אומר אסתר ירקרוקת היתה, ופי' רש\"י כהדסה, וחוט של חסד משוך עלי' ופי' רש\"י מאת הקב\"ה ולכן נראית יפה לאומות ולאחשורוש.\n<b>והענין</b> הוא דהנה ארז\"ל בסנהדרין פ\"ב ד\"ך ע\"א ובילקוט בש\"א רמז קל\"ו ע\"פ שקר החן והבל היופי אשה יראת ה' היא תתהלל (משלי ל\"א) שקר החן זה דורו של משה והבל היופי דורו של יהושע, אשה יראת ה' זה דורו של חזקי' שהיו יושבין ועוסקי' בתורה, איכא דאמרי שקר החן זה דורו של משה ויהושע, והבל היופי זה דורו של חזקי', אשה יראת ה' זה דורו של ר' יהודה ב\"ר אלעאי שהיו ששה מתכסין בטלית א' ויושבין ועוסקי' בתורה, ופי' רש\"י עניים היו. ולהבין זה הנה כתי' אם לא תדעי לך היפה בנשים, פי' ענין היפה בנשים גימ' ארור המן, וגם גימ' ברוך מרדכי.\n<b>ויובן</b> כ\"ז בהקדם מה שפעם נק' כנס\"י בשם רחל ופעם בשם אסתר, ושרש ההפרש הוא כמו ההפרש שבין צדיקי' לבע\"ת, ע' בד\"ה ויהיו כל הפקודי' (בס' ך\"ו), דהנה כתי' ורחל היתה יפת תואר ויפת מראה, פי' תואר הוא בציור תמונת האברים שהם לפי ערך שכל אבר הי' לפי ערכו ותמונתו וזהו הנק' תואר, ומראה הוא בחי' הזיו וקלסתר פנים שה\"ע שופרי' וזיוו, ורחל היתה יפת תואר ויפת מראה שהיו לה ב'"],[2000560285,"המעלות בציור תמונת האברים וגם בזיו וקלסתר פנים ג\"כ, והענין בעבודה בכנס\"י שנק' רחל, הנה תואר שהוא בחי' ציור האברים היינו ז\"א רמ\"ח פקודין שהם רמ\"ח אברין דמלכא, ומראה הוא בחי' שס\"ה מל\"ת כי שרש השס\"ה ל\"ת הם מבחי' י\"ה שהוא בחי' חכ', וכתיב חכמת אדם תאיר פניו שהוא בחי' הזיו וההארת פנים (ע' בלק\"ת בשה\"ש בביאור ע\"פ שחורה המתחיל הנה בין המאציל פ\"ו, וס\"פ ג', ובביאור ע\"פ אלה מסעי הג' המתחיל הנה גבי המסעות פ\"ד, דצ\"ג ע\"ב).\n<b>והנה</b> פי' יפת תואר בעבודה בנש\"י היינו שצ\"ל שיהי' בחי' יופי, דהנה ענין היופי הוא דוקא מהתכללות הגוונים ביחד משא\"כ גוון אחד אינו נק' יופי כו', וזהו ענין על שלשה דברים העולם עומד על התורה ועל העבודה ועל גמ\"ח, שהם בחי' ג' קוין, והנה בכל אחד מהג' בחי' תורה ועבודה וגמ\"ח צ\"ל העבודה בבחי' שמחה וכמ\"ש תחת אשר לא עבדת כו' בשמחה, ובגמ\"ח כתיב ואל ירע לבבך בתתך לו, וכן בת\"ת ארז\"ל בשבת ד\"ל ע\"ב גבי אין שכינה שורה לא מתוך עצבות ולא מתוך עצלות כו' אלא מתוך שמחה של מצוה, אמר רב יהודה וכן לדבר הלכה, וכ\"ה בפסחים דקי\"ז ע\"א, וע' בת\"א בד\"ה לסוסתי בפ' בשלח מענין שמחה של מצוה שהוא בחי' אתעדל\"ע שלמעלה מבחי' אתעדל\"ע הנמשך ע\"י אתעדל\"ת, ושזהו כמו קרי\"ס שבעתיקא תליא, לכן נא' בקרי\"ס מה תצעק אלי כו'. וע' בד\"ה ויתן אל משה שזהו המשכה מבחי' תר\"ך עמודי אור כו', ושבחי' זו ניתן בבחי' מתנה שכאשר איש ישראל יעשה המצות בבחי' שמחה אזי יומשך בחי' אלו, ועי\"ז נק' יופי כו'.\nב) <b>ולהבין</b> מהו ענין ב' בחי' יופי דיפת תואר ויפת מראה, הענין הוא שהגם שע\"י שנמשך הארת המוחין במדות עי\"ז הם מתכללי' שזהו ג\"כ יופי, מ\"מ"],[2000560286,"שרש המדות הם למעלה מבחי' המוחין כמ\"ש במ\"א מענין תשר\"ק ומענין קדושת כתר דמוסף, והגם שהמדות מתנהגי' ע\"פ השכל מ\"מ שרש המדות בעצם הם למעלה מהשכל, וע\"י שמאיר בחי' גילוי שלמעלה מן השכל במדות עי\"ז נעשה בחי' יפת תואר שהוא בחי' היופי בתמונת האברים הם רמ\"ח מצות עשה ויפת מראה בחי' שס\"ה ל\"ת, שבחי' זו נמשכת ע\"י שמחה של מצוה, וזהו מ\"ש ב\"פ הנך יפה, הנך יפה רעייתי הנך יפה עינייך יונים, היינו ב' בחי' היופי דיפת תואר ע\"י מצות עשה ויפת מראה ע\"י מצות ל\"ת. וזהו ג\"כ היפה בנשים בגימ' ארור המן וגם ברוך מרדכי שהוא בחי' רמ\"ח מ\"ע בחי' יפת תואר ושס\"ה מל\"ת בחי' יפת מראה, וזהו היפה בנשים גימ' שני האבות תק\"ב שאברהם חי קע\"ה שנה ויצחק ק\"פ ויעקב קמ\"ז שהוא תק\"ב, והיינו שהוא התכללות ג' אבות בחי' ג' מדות כו' [וע' בלק\"ת מהאריז\"ל בפ' חיי ד\"מ ע\"א בד\"ה ענין שני חיי אברהם, שיופי דיוסף נמשך ע\"י התפשטות ה' חסדים דאברהם ביסוד ז\"א, ושורש היופי נמשך מבחי' ש\"ע נהורין יעו\"ש].\n<b>והנה</b> כתיב (ויצא ך\"ט י\"ח ופסוק למ\"ד) ויאהב יעקב את רחל וכתי' ויאהב גם את רחל מלאה, דהנה רחל היא בחי' עלמא דאתגליא וכמ\"ש ושם הקטנה רחל ופי' בזהר ובמד\"ר שם ה' קטנה רחל שהוא בחי' עלמא דאתגליא וע\"כ ויאהב יעקב את רחל, לפי שיעקב הוא בחי' בריח התיכון המבריח מן הקצה אל הקצה שהוא הממשיך בחי' גילוי אלקות למטה דוקא ע\"כ אהב את רחל שהיא עלמא דאתגלי', הגם שלאה היא למעלה מבחי' רחל וכמ\"ש ושם הגדולה לאה ה' גדולה לאה, אך כ\"ז הוא רק בבחי' עלמא דאתכסי' שאינו מאיר בגילוי, אבל כדי שיהי' גילוי אלקות למטה דוקא זהו ע\"י בחי' רחל, וזהו שנק' כנס\"י בשם רחל, דהיינו בזמן שבהמ\"ק הי' קיים שהי' מאיר גילוי אלקות בעולם וכמו ביצ\"מ וקרי\"ס, וכן כ\"ז שבהמ\"ק הי' קיים הי' בחי' גילוי אלקות לעיני כל, וע\"כ נק' רחל. וזהו מי יתנך כאח לי וארז\"ל כיוסף לבנימין והיינו בחי' הנשמות שנק' אחים וריעים כמ\"ש למען אחיי וריעיי, שקאי על זמן בהמ\"ק כמ\"ש בהגהות לד\"ה מי יתנך באורך."],[2000560287,"<b>אך</b> הנה בגלות נקראו בשם אסתר ע\"ש שאינו מאיר אלקות בבחי' גילוי, וזהו שלא נזכר שם הוי' בפירוש בכל מגילת אסתר, הגם שברמז יש שם ג\"כ שם הוי' כמו יבא המלך והמן היום אל המשתה ר\"ת הוי' ואח\"כ כתיב ויבא המלך והמן לבד שהוא ר\"ת יה\"ו, והיינו שאסתר רצתה להגביה את המן למעלה מאד כדי שאח\"כ תהי' הירידה גדולה, וכמו פרי החג שמתמעטין והולכין מתחלה י\"ג פרים ואח\"כ י\"ב כו' מתמעט והולך, וכך אסתר רצתה להגביה את המן למעלה בבחי' שם הוי' וכתי' משם אורידך נאום הוי' כו', וכן מרדכי הוא מירא דכיא [שהוא בחי' גבוה מאד כמ\"ש התרגום על מר דרור מירא דכיא שז\"ע מרדכי מן התורה כו', והיינו שהוא בחי' ריח דבר שהנשמה נהנית ממנה ולא הגוף, גוף הוא בחי' רמ\"ח פקודין רמ\"ח אברין דמלכא מצות הוי', ועמ\"ש מזה ע\"פ כי המצוה הזאת כו' לא נפלאת היא כו', משא\"כ הריח הנשמה עצמה נהנית ממנה כמו שמעוררי' מי שנתעלף ע\"י ריח החזק שעולה דרך נקבי החוטם למעלה מן המוח, וז\"ע התשובה שנק' ריח כמ\"ש ע\"פ וירח את ריח בגדיו, ריח בוגדיו כו', ועמ\"ש בזה בד\"ה ראה ריח בני ובד\"ה באתי לגני בענין אריתי מורי עם בשמי שעי\"ז מעוררי' בחי' סוכ\"ע מה שאין אתעדל\"ת של המצות מגיע לשם, כי ע\"י המצות נמשך מבחי' אדם אבל ע\"י מס\"נ ממשיכי' מבחי' כי לא אדם כו'], ושבע הנערות הוא בחי' ז' היכלות, אך מ\"מ לא נאמר זה בפירוש רק ברמז בבחי' הסתר כו' וכמו מרדכי גימ' רב חסד, והיינו לפי שבגלות אינו מאיר בבחי' גילוי ש' הוי' רק שמתלבש בכינוים והיינו ע\"י לבושים וצמצומים כו'. וזהו אם לא תדעי לך היפה בנשים שאין שם בחי' יופי כו' שהוא בחי' ארור המן וברוך מרדכי וכמארז\"ל עד דלא ידעי בין ארור המן לברוך מרדכי דהיינו בחי' רמ\"ח מ\"ע ושס\"ה ל\"ת, אך מ\"מ ע\"י הסתר מגיעין למעלה מבחי' ארור המן וברוך מרדכי והיינו ע\"י מס\"נ שהי' להם מגיעין עי\"ז למעלה מבחי' י\"ה ו\"ה.\n<b></b>[וזהו וקבל היהודים את אשר החלו לעשות, וארז\"ל פ\"ח דשבת דפ\"ח ע\"א את אשר החלו לעשות במ\"ת שע\"י מס\"נ דפורים הוא הקיום והקיבול על מ\"ת"],[2000560288,"שלגבי בחי' זו מ\"ת הוא רק ההתחלה לבד, ולכן יוהכ\"פ שבו היו לוחות אחרונות הוא כפורים לפי שבפורים הי' גמר הקבלה והיינו ע\"י המס\"נ שלהם ולכן נא' וקיבל לשון יחיד, כי מחכ' ולמטה הוא בחי' ההתחלקות, וזהו\"ע נודע בשערים כל חד לפום שיעורא דילי', שז\"ע העבודה שע\"פ השכל המושג הנה הוא נמשך בבחי' התחלקות המדריגות, אבל בחי' רעו\"ד שהוא בחי' הרצון שלמעלה מן השכל לגמרי, והו\"ע המס\"נ שהי' בימי המן שנתדבקו בו ית' בבחי' רצון פשוט שלמעלה מן השכל וההשגה הנה בבחי' זו משתווים כל נש\"י יחד כאלו אינו אלא רצון אחד מכולם יחד ולכן נא' וקבל ל' יחיד, ועמ\"ש מזה בסוף הביאור שע\"פ וקבל שבת\"א].\nג) <b>וזהו</b> אסתר ירקרוקת היתה, דהיינו לפי שבגלות אין לה בחי' יופי שהוא בחי' יפת תואר יפת מראה, אלא שחוט של חסד משוך עליה, והיינו שנמשך לה מבחי' רב חסד. וזהו מ\"ש שקר החן זה דורו של משה שהי' בבחי' חן אתעדל\"ע מצד עצמו כמו שהי' יצ\"מ וקרי\"ס מצד אתעדל\"ע. והבל היופי זה דורו של יהושע אף שהי' להם בחי' יופי בחי' יפת תואר ויפת מראה, מ\"מ הוא רק בחי' הבל, דהנה קהלת אמר ז' הבלים הבל הבלים אמר קהלת, והיינו שז' הבלים הם כנגד ז' ימי בראשית"],[2000560289,"שהוא בחי' ז' מדות עליונות ואף שהוא בחי' גבוה מאד, אך מ\"מ נק' רק הבל לבד לגבי אוא\"ס שהוא בחי' הבל הלב שהוא רק הארה בעלמא, וזהו והבל היופי שהיופי אינו רק מבחי' הבל. אשה יראת ה' היא תתהלל זה דורו של ר\"י ב\"ר אלעאי שהיו יושבין ועוסקין בתורה, דהנה בדורו של ריב\"א הי' כל ההיפוכים וגזירות ואעפ\"כ עסקו בתורה שזהו בחי' מס\"נ, ועי\"ז מגיעין למעלה מבחי' ורחל היתה יפ\"ת ויפ\"מ שהי' מאיר בזמן בהמ\"ק. וזהו משארז\"ל כל הנביאים בטלים לע\"ל חוץ ממגילת אסתר, והענין הוא דהנה ארז\"ל אסתר מן התורה מנין דכתי' ואנכי הסתר אסתיר פני ביום ההוא, והנה כתי' ועבד הלוי הוא, שעבודת הלוים הי' כדי להמשיך מבחי' הוא, והנה הוא הוא בחי' עלמא דאתכסיא וזה הוא עלמא דאתגליא, ועבודת הלוים הי' כדי להמשיך מבחי' הוא בבחי' זה וכמ\"ש לע\"ל ואמר ביום ההוא הנה אלקינו זה, שלע\"ל יהי' מאיר גילוי בחי' הוא בבחי' זה, אך הנה מגילת אסתר הוא בחי' אסתיר פני ביום ההוא שאפי' בבחי' הוא הוא ג\"כ בחי' הסתר אסתיר פני ביום ההוא, דהיינו שאפילו בעלמא דאתכסיא הוא ג\"כ מוסתר ונעלם כו'. וזהו כל הנביאים בטלים חוץ ממגלת אסתר והיינו לפי שכל הנביאים הוא שממשיכים מבחי' עלמא דאתכסי' בעלמא דאתגליא, ולע\"ל שיהי' התגלות בחי' הוא עלמא דאתכסי' עצמו ממילא יהי' כנגדה כנר בפני אבוקה חוץ ממגלת אסתר לפי שהיא למעלה גם מבחי' עלמא דאתכסיא כו'. והנה רז\"ל למדו זה ממ\"ש וזכרם לא יסוף מזרעם, דהנה כתי' קול גדול ולא יסף ותרגומו לא פסק, והיינו שכשנמשך המשכה מבחי' קול גדול אזי ולא יסף, וכך מגלת אסתר שרשה נמשך מבחי' קול גדול הנ\"ל ע\"כ לא יסוף מזרעם כנ\"ל וד\"ל.\n<b>אשה</b> יראת ה' זה דורו של ר\"י ב\"ר אלעאי, שהי' להם מס\"נ על התורה, וכמו בנס דפורים שע\"י המס\"נ שלהם עי\"ז הי' וקיבל את אשר החלו במ\"ת כנ\"ל."],[2000560290,"<b>ויש</b> להעיר מענין מ\"ש (ש\"ב רסי' ך\"ג) ונאום הגבר הוקם על וארז\"ל פ\"ג דמ\"ק דט\"ז סע\"ב ארשב\"נ א\"ר יונתן מ\"ד נאום דוד בן ישי ונאום הגבר הוקם על שהקים עולה של תשובה, ופי' רש\"י שהוא שב תחלה ונתן דרך לשבים כדאמרינן פ\"ק דע\"ז דף ד' ע\"ב, לא הי' דוד ראוי לאותה מעשה (דבת שבע שהרי אמר ולבי חלל בקרבי) אלא שאם חטא יחיד אומרים לו כלך אצל דוד שמחל לו הקב\"ה אף אתה חזור בתשובה. והנה בתשובה יש כמה מדריגות כמ\"ש בלק\"ת בד\"ה מה טובו, ודוד עשה תשובה עילאה ע\"כ נק' שהקים עולה של תשובה, וכענין והחזירנו בתשובה שלימה לפניך, וכמ\"ש בד\"ה שובה עד הוי' אלקיך היינו עד שיהי' הוי' בבחי' אלקיך כו', וזהו פי' כל ימיו בתשובה שאין התשובה על העוונות ח\"ו כ\"א להיות והרוח תשוב, כמ\"ש בד\"ה מה טובו הנ\"ל. והנה עיקר ההפרש בין תשו\"ע לתשו\"ת, כי תשובה תתאה היא בבחי' ממכ\"ע ע\"פ השכל והמדות, ותשובה עילאה היא בבחי' סוכ\"ע ע\"י בחי' בכל מאדך, וזהו הנק' עולה של תשובה. ולכן נקרא דוד בן ישי כי ישי הוא ש\"י עולמות שבבינה בחי' תשובה, ובמאו\"א בן ישי יסוד דז\"א בן לבינה שבה ש\"י עלמין.\n<b>והנה</b> ע\"י בחי' תשו\"ע הוא בא לבחי' לפני הוי' תטהרו בגימ' כתר כי בינה נק' על הוי' כמ\"ש במאו\"א אות ע' סעי' ל\"ה על הוי' נק' בינה אימא שהיא על ז\"א הנק' הוי' וכ\"ש עתיקא שהוא על הוי', והנה עתיק הוא ל' המעתיק הרים שנעתק ונבדל כו', וכמו\"כ ע\"י שהאדם מעתיק א\"ע ממדות נפש הבהמי' ונבדל מהם ע\"ד ואבדיל אתכם כו' הרי הוא בבחי' על, ועי\"ז זוכה לתשובה שלימה שהיא ג\"כ בבחי' על"],[2000560291,"הוי' כמ\"ש לפני הוי', כי פתחי לי כחודה של מחט ואני אפתח לך כפתחו של אולם, וכמו מארז\"ל באיזהו זכות נכנס אהרן לקה\"ק בזכות המילה, שע\"י העברת הערלה עי\"ז זכה ליכנס לקדה\"ק והעביר הפרוכת המבדיל בין הקדש לקה\"ק, וכמ\"ש ה' צלך, וכמ\"ש בתניא. והנה ע\"י המס\"נ שהי' להם כל השנה עי\"ז הגיעו לבחי' על הוי', לכן שקר החן בחי' אתעדל\"ע מצ\"ע, והבל היופי ההמשכה מבחי' שפת אמת, כי ע\"י המס\"נ בחי' תשובה הגיעו לבחי' על הוי' להשלים כל הפגמי' שנעשו בבחי' היופי הנ\"ל.\n<b>וזהו</b> אסתר ירקרוקת היתה וחוט של חסד, ופי' בעה\"מ שער אק\"ס פ\"ח דמ\"ו ע\"ג כי אסתר המלכה היא מל' דאצי' המקבלת הארה מן חוט הנמשך מא\"ס ומקבלת אותו ע\"י אריך ואו\"א וז\"א, ובזה נעשית לבנה, וזהו כדעת ר' נחמי' ע\"ש אסתהר שפי' רש\"י ל' ירח יפה כלבנה, וא\"ל היא נשארת ירקרקות כמארז\"ל הנ\"ל, והחוט פי' שם שנמשך מאוא\"ס ממש והוא נשמה לא\"ק, ואפ\"ל עד\"ז פי' אומן את הדסה שממשיך עלי' חוט של חסד הנ\"ל."],[2000560292,"<h3>[ע' בלק\"ת מהאריז\"ל]</h3>\n<b>ע'</b> בלק\"ת מהאריז\"ל פ' חיי ד\"מ ע\"א בד\"ה ענין שני חיי אברהם, שיפה תואר ויפה מראה דיוסף זהו מבחי' ש\"ע נהורין דפנים, ע\"י שמתפשטים ה\"ח ביסוד ז\"א, וע\"ש בדף מ' ע\"ב בד\"ה ענין ש\"ע נהורין בסופו כ' שיו\"ד פעמים המילוי דשם ס\"ג הם ש\"ע, וא\"כ מ\"ש והבל היופי שהיופי הוא מבחי' הבל היינו המילוי דשם ס\"ג שעולה מספר ל\"ז כמספר הבל, אבל ע\"י אשה יראת ה' מס\"נ כמו דורו של ריב\"א ובימי אסתר זכו לבחי' גילוי שם ס\"ג עצמו, בחי' ואמת, ז\"פ ס\"ג גימ' ואמת כמ\"ש בלק\"ת הנ\"ל, וע\"י המס\"נ בכל הז' מדות זכו לבחי' ואמת."],[2000560293,"<b>לכאו'</b> צ\"ל הלא נת\"ל בהג\"ה על ענין יפ\"מ שענין חכמת אדם זהו הארת תיקון ואמת, וא\"כ איך נא' והבל היופי.\n<b>וי\"ל</b> ב' תירוצי', הא' שהיופי זהו מבחי' ש\"ע נהורין, שזהו מבחי' הבל כי י\"פ הבל זהו ש\"ע, וכמ\"ש לעיל בשם הלק\"ת מהאריז\"ל, וא\"כ זהו שפת אמת, משא\"כ ש' ס\"ג ז\"פ ס\"ג בגימ' אמת (אך אפ\"ל שזהו יופי דיוסף, שאפשר שזהו קודם מ\"ת, והי' הכנה למ\"ת כי מעשה אבות סימן לבנים, ורחל נק' כנס\"י בזמן בהמ\"ק, מ\"מ זה אינו דהלא מי יתנך כאח לי שקאי על בהמ\"ק, וארז\"ל כיוסף לבנימין).\n<b>והתירוץ</b> הב', שבהג\"ה מדבר כמו קיום המצות עשה ול\"ת לאחר נס דאסתר שקיבלו מה שכבר קיימו ונמצא כי מה שאמרו והבל היופי היינו בחי' דורו של יהושע עד שקיבלו ישראל התורה ברצון גמור מעצמם, אך לפ\"ז יקשה האיכא דאמרי זהו דורו של חזקי', אך חזקי' הי' בשנת ג\"א קצ\"ט עד שנת רך\"ח והיינו שמלך ך\"ט שנים, וא\"כ הוא הרבה קודם אסתר, כי יהויכין מלך בשנת ג\"א שך\"ז, וכתי' עם הגולה אשר הגלתה עם יכני' מלך יהודה, לכן גם להאיכא דאמרי שקאי על חזקי' שייך לומר הבל, שכ\"ז הוא מבחי' ההבל היינו המילוי דס\"ג, ועז\"נ הבלים דקהלת. אך ע\"י נס דאסתר שקיבלו מה שכבר קיימו עי\"ז המשיכו בחי' אמת ע\"י המס\"נ שלהם ולכן לע\"ל שיתגלה בחי' העבודה ע\"י מצות ל\"ת דעכשיו כמ\"ש בביאור שחורה אני פ\"ב הנ\"ל יתגלה בחי' אמת הוי' לעולם."],[2000560294,"<h3>יביאו לבוש מלכות כו'</h3>\n<b>בס\"ד, ש\"פ צו, ך\"ז.</b>\n<b>יביאו</b> לבוש מלכות כו' וסוס אשר רכב עליו המלך כו' והלבישו את האיש כו' וקראו לפניו ככה יעשה. הנה צ\"ל איך ביכולת הנשמה לקבל בחי' אלו שענין הסוס הוא בחי' שם ס\"ג בחי' גיאות, כי סוס עולה ב\"פ ס\"ג, והנה למעלה"],[2000560295,"ניחא הגיאות שהוא ית' מתגאה כמ\"ש ה' מלך גיאות לבש, אך איך ביכולת הנשמות לקבל בחי' אלו. גם להבין ענין מ\"ש (מיכה סי' ה' פ\"ו) והי' שארית יעקב כו' כטל מאת ה', אשר לא יקוה לאיש ולא ייחל לבני אדם, שזהו מדריגה גבוה מאד, איך יוכלו הנשמות לקבל בחי' זו. גם צ\"ל ענין שאיתא במד\"ר פ' מקץ ע\"פ רק הכסא אגדל, גדולתי למעלה מגדולתכם וענין קדושתי למעלה מקדושתכם.\n<b>ויובן</b> בהקדים ענין מ\"ש מי אל כמוך נושא עון כו' לשארית נחלתו וארז\"ל למי שמשים עצמו כשיריים, ולכאו' אינו מובן מפני מה דוקא למי שמשים עצמו כשיריים הלא הסליחה נמשך ממקום גבוה מאד שהוא למעלה ממקום הדקדוק ולמה דוקא למי שמשים עצמו כשיריים כו', ובאמת יש ד' חילוקי כפרה שהי' ר\"י דורש, א\"ל שלשה הן ותשובה עם כל אחד מהן (יומא דפ\"ו ע\"א), שזה ג\"כ אינו מובן כנ\"ל שהסליחה נמשך ממקום גבוה מאד כמ\"ש במ\"א.\n<b>והענין</b> הוא דהנה המקובלים הראשונים שלפני האריז\"ל קראו למדת החסד בשם גדולה, והאריז\"ל והנמשכים אחריו קורים מדת החסד בשם חסד. והענין הוא דהנה חסד הוא בחי' חסד דאברהם, שהחסד הוא מחמת הביטול כמ\"ש ואנכי עפר ואפר, והיינו שהחסד שלו הי' מצד שהי' בבחי' ביטול מאד לכן הי' נותן כל"],[2000560296,"הטוב לזולתו ואינו משייר לעצמו כ\"א ניזון מהשיריים מחמת שהוא בעצמו אינו תופס אצלו מקום כלל, לכן אומר לעצמו מה אני שאשייר לעצמי הטוב הלזה ובאמת פחות ערכי מזולתי שהוא יותר חשוב ממני, לכן הוא נותן לזולתו ולעצמו אינו משייר כ\"א השיריים מחמת פחיתות ערכו, וזהו נק' חסד שמחמת הביטול. משא\"כ מי שאינו מחשב פחיתות ערכו והוא מחזיק עצמו ליש לכן נדמה לו שצריך זאת לעצמו, רק המותרות יתן לצדקה, וגם ע\"פ הדין אינו צריך ליתן לצדקה יותר מחומש, ומי שהוא יותר יש נדמה לו שהכל צריך ואינו יכול ליתן לצדקה כלל. אבל מצד מדת החסד שהוא מחמת הביטול שמחשב פחיתות ערכו יכול ליתן הכל לצדקה ואינו משייר לעצמו כ\"א המותרות כו', שזהו חסד דאברהם שהי' בבחי' ביטול מאד והוא בחי' חסד דמ\"ה.\n<b>ולכן</b> ארז\"ל (ספ\"ד דסוכה דמ\"ט) בת נדיב בתו של אברהם שנק' נדיב שהוא מדריגה גבוה מאד, וכמ\"ש בספר אורחות צדיקים בשער י\"ז הוא שער הנדיבות, שיש נדיב בממונו ויש נדיב בגופו ויש נדיב בחכמה, וכולם היו באברהם שנדב ממונו וגופו ונפשו מחמת אהבת ה', וכמ\"ש בפרדס בערך הכינויים פ\"ד בשם ספר הבהיר אמרה מדת החסד כל ימי היות אברהם על הארץ לא עשיתי מלאכתי שאברהם עומד שם במקומי וישמור משמרתי עכ\"ל. ולכן נחשב מדת החסד דאברהם בלי גבול נגד חסד דשאר אנשים, אך באמת הוא בבחי' גבול מפני כי אברהם הי' ג\"כ נברא כו'.\n<b>והנה</b> חסד דאברהם נק' חסד זוטא, ולכאו' צ\"ל מפני מה נק' חסד זוטא הלא החסד דאברהם [הי'] בריבוי מאד עד שלא הי' משייר לעצמו כ\"א המותרות כו'. אך הענין הוא דמה שנק' חסד זוטא [הוא] לא מפני שהחסד הוא חסד קטן, כ\"א שהחסד בא מחמת קטנות, דהיינו מה שמשפיל א\"ע שאינו נחשב כלל שיצטרך לכל הטוב כ\"א שזולתו יותר טוב ממנו לכן נותן כל הטוב לזולתו כו', ולזה נק' חסד זוטא דהיינו שבא מבחי' שמקטין ומשפיל א\"ע. ולכן החסד דאברהם הוא מרכבה לבחי' חסד דאצי' שהוא ג\"כ בבחי' קטנות, והיינו שאינו קטנות ח\"ו שהרי אפי' בחי' הדבור שלמעלה הוא בבחי' פרצוף וכ\"ש המדות, ובפרט מדת החסד שהוא יומא דאזיל עם כולא יומין שזהו בחי' עננא דאהרן כמ\"ש במ\"א בענין יומם יצוה, יומם במ\"ם, ע'"],[2000560297,"בלק\"ת פ' צו בד\"ה מצה זו, אלא מפני שהמדות הם בבחי' ביטול כמ\"ש בס\"י ולפני כסאו הם משתחוים, שהמדות דאצי' הם בטלים לאוא\"ס לכן נק' חסד דאצי' בבחי' קטנות דהיינו מפני שהשפעת החסד דאצי' הוא מחמת ביטול מדת החסד לעצמותו ית' עי\"ז נשפע החסד למטה (דוגמת כמו אברהם שמחמת שהי' שפל בעיניו שז\"ע עפר ואפר לכן הי' משפיע כל הטוב והחסד לזולתו, ככה במדות דאצי' הנה השפעת מדת החסד הוא מחמת הביטול שלהם, ואברהם הי' מרכבה לבחי' חסד זה כו'. וכמו\"כ הו\"ע קטנתי מכל החסדים שאמר יעקב כמ\"ש באג\"ה סי' ב').\n<b>אכן</b> יש בחי' רב חסד שהוא בחי' חסד הבא מחמת עוצם הגדלות וההתנשאות שמחמת עוצם גדלותו עי\"ז משפיע בחי' הטוב והחסד לזולתו. ויובן זה ממלך בו\"ד, הנה אנו רואים שמתנת והשפעת החסד של המלך הוא בלי שיעור, שמה שנחשב אצל אחר לדבר גדול ועושר מופלג, נשפע מהמלך במתנה לאחד ואינו נחשב אצל המלך כלל המתנה לדבר גדול כ\"כ, והיינו מפני עוצם גדלות המלך אינו נחשב בחי' השפעה זו אצלו לדבר חשוב מחמת עוצם גדלותו, והמלך אשר הוא יותר גדול מתנתו יותר בשפע רב ואינו נחשב ג\"כ לדבר חשוב. או יובן ממ\"ש במ\"א בד\"ה עבדים היינו שפירורי הפקר של המלך עולה יותר מרכוש של שר חשוב, הנה זהו מחמת עוצם מעלת המלך לכן רכוש גדול כזה נחשב אצלו לדבר קטן עד שהם פירורי הפקר כו'. וככה יובן למעלה שהוא יש האמיתי ולגדולתו אין חקר כתיב שלגדולתו העצמי אין חקר וא\"א להעריך כלל גדולתו לכן מחמת עוצם גדולתו ית' נמשך השפעת החסד בלי שיעור כלל.\n<b>והנה</b> חסד זה נק' בשם גדולה שבחי' חסד זה הוא בחי' רב חסד שלמעלה באין ערוך מחסד דאצי' שנק' חסד זוטא מחמת שנמשך מבחי' הביטול שאינו נחשב בעיני עצמו כנ\"ל, משא\"כ בחי' חסד זה הוא מחמת עוצם הגדלות כו'.\n<b>והנה</b> לכאורה צ\"ל הלא נתבאר בכ\"מ בת\"א ובלק\"ת בכ\"ד בענין גדול הוי' כו' אימתי הוא גדול כשהוא בעיר אלקינו, וכמ\"ש בזח\"ג ד\"ה ע\"א ובמק\"מ שם"],[2000560298,"יעו\"ש, א\"כ הרי אדרבה החסד דאצי' נק' גדול, משא\"כ לרוממות עצמותו אינו שייך לקרותו בשם גדול כלל. אך הענין הוא דהנה הכלי לגילוי בחי' הגדולה דרב חסד הוא דוקא בחי' חסד דאצי', והיינו מפני כי בחי' רב חסד נמשך מצד רוממות גדולתו העצמית והוא היש האמיתי וכולם בטלים ממש, לכן מצד רוממות גדולתו נמשך השפעת הטוב והחסד, וזה א\"א להיות נמשך כ\"א בבחי' חסד דאצי' דוקא שהוא בחי' חסד זוטא, פי' חסד זוטא שבא מחמת בחי' הקטנות שמקטין ומשפיל א\"ע עד שאינו נחשב לכלום לכן משפיע לזולתו הנה מצד טעם זה גופא הוא כלי לקבל השפעת בחי' רב חסד שבא מחמת הגדלת עצמותו ית' וכולם בטלים ממש כו', וזהו החסד דאצי' שנק' חסד זוטא מחמת שאינו בבחי' מציאות כלל כ\"א בבחי' ביטול, וזהו כמ\"ש מרום וקדוש אשכון את דכא כו', וזהו כענין גדלות ראשון וגדלות שני לקבל מבחי' מוחין דגדלות, ולא מבחי' מוחין דיניקה כו'.\n<b>ובאמת</b> יש ב' פירושי' בפי' לך ה' הגדולה, הא' הוא כי מדת הגדולה בטל וטפל לך לעצמותו ית', כמ\"ש בתו\"א בד\"ה ויושט, ובד\"ה וארא, ובלק\"ת בד\"ה בשעה שהקדימו פ\"א. והב' לך ה' הגדולה שנמשך בבחי' הגדולה כו' [ע' בד\"ה משה ידבר, וכמ\"ש במד\"ר במדבר פ\"א כשם שיש לי תלוי ראש על כל העולם שנא' לך ה'"],[2000560299,"הגדולה, ובגמ' פ\"ט דברכות דנ\"ח ע\"פ לך ה' הגדולה זו מע\"ב והגבורה זו יצ\"מ כו', והיינו כענין מ\"ש (בישעי' סי' נ\"ב יו\"ד) חשף ה' את זרוע קדשו כו' כי הולך לפניכם ה', והו\"ע ולא יכנף וכמ\"ש בסידור בד\"ה שימני כחותם שלא יסתתר עוד בבחי' לבושי', אלא יבוא אורו למטה בבחי' גילוי ממש כו', וזהו חשף ה' את זרוע כו' פי' חשף בבחי' גילוי, וזהו לך ה' הגדולה. ושני הפי' אמת], וכ\"ז בקדושה.\n<span data-k=\"ks\"><b>קיצור.</b> שבקדושה יש ב' בחי' חסד, הא' בחי' חסד דאצי' בחי' חסד זוטא, שבא מחמת הקטנות שמקטין א\"ע והוא בחי' חסד דאברהם שהי' שפל בעיני עצמו כעפר ואפר, הב' בחי' חסד הבא מחמת רוממות גדולתו העצמית כו'.</span>\n<b>והנה</b> כתיב וחסד לאומים חטאת, וצריך להבין בחי' חסד זה שהוא חטאת, ולכאו' צ\"ל למה נק' חטאת הלא הוא בחי' השפעת החסד, אך הענין הוא דהנה החסד שעושין העכומ\"ז אינו כ\"א להתייהר, והיינו שהחסד הוא מחמת בחי' הגסות וגדלות ואינו מחמת בחי' הביטול כמו חסד דאברהם שבא מחמת הביטול ושפלות כו', וגם אינו בחי' החסד שמחמת רוממות גדולת עצמותו ית', כ\"א החסד דלאומים הוא בחי' חסד הבא מחמת גסות הרוח כו'. ולהבין זה הנה שרש בחי' החסד הלזה הוא מבחי' מדת החסד דתהו, ששם נק' החסד בשם גדולה והיינו שהוא בחוזק מאד, אך כאשר נפל למטה בשבה\"כ מחמת ריבוי תגבורת החסד נפל למטה בחסד דלאומים שהוא חטאת כו', ונעשה מזה למטה חסד הבא מחמת גסות שהוא משבה\"כ [דז\"ת] דשם ס\"ג כו' כנודע ממ\"ש במ\"א. משא\"כ חסד דאצי' הוא בחי' חסד דתיקון כו'. וזהו שכינו המקובלי' הראשונים שלפני האריז\"ל בשם מדת גדולה כוונתם על בחי' החסד דתהו שהוא בחי' גדולה, היינו בבחי' תגבורת אנא אמלוך (שלכן היו נקודות זת\"ז כמ\"ש וימלוך תחתיו כו' שכ\"א הי' בבחי' תגבורת כו'), אבל האריז\"ל מדבר בבחי' חסד דאצי' ולכן קורא זה חסד סתם.\n<b>ובזה</b> יובן ג\"כ מ\"ש ואיש כי יקח את אחותו חסד הוא, ופירשו בזהר ויקרא ד\"ז ע\"ב אחותו דא כנס\"י כו' יעו\"ש, ולפי פי' הפשוט פי' חסד הוא ל' זמה וחרפה כו' כמו שפרש\"י ז\"ל. אך הענין הוא דהנה כשנצטוו ישראל על פרשת עריות בכו, והיינו"],[2000560300,"מפני שהשיגו שלמעלה היחוד דעריות גבוה מאד וכמ\"ש ואיש כי יקח את אחותו חסד הוא כפי' הזהר וכמ\"ש באברהם אחותי בת אבי היא, וידוע הפי' בת אבי מבחי' חכ' כמ\"ש בבה\"ז, ולכן רצו להמשיך למטה ג\"כ מבחי' יחוד זה, אך באמת א\"א למטה להמשיך בחי' יחוד זה כי לפי שיחוד זה מבחי' גבוה מאד, וכשנפל בשבה\"כ הנה הוא נמשך במקום הקליפות דוקא כמשל הארי' שהוא למעלה בחי' חסד פני ארי' אל הימין הנה למטה הוא חי' טמאה דוקא כו' לכן א\"א להיות יחוד זה למטה (ועמ\"ש מזה בבה\"ז פ' תרומה על מאה\"ז דקכ\"ו, ושם בד\"ה יעקב דהוה שלים), וכפי' הפשוט בפי' חסד הוא כו', וכנ\"ל שמחמת תגבורת החסד דתהו נעשה מזה בשבה\"כ למטה בחי' חסד לאומים.\n<b>וזהו</b> לשארית נחלתו למי שמשים עצמו כשיריים דוקא, פי' שהמשכת בחי' רב חסד שבא מחמת גדולתו העצמיות אינו יכול להיות נמשך כ\"א למי שמשים עצמו כשיריים, משא\"כ בחי' חסד דלאומים שהוא בחי' חסד דבחי' גיאות א\"א להיות נמשך בו בחי' רב חסד שבא מחמת גדולתו העצמית כו', שזהו מ\"ש כי גאה גאה ותרגומו גאה על גיוותניא, פי' שמתגאה עצמו לבלי הגלות על בחי' גיוותניא בחי' חסד דגסות, ור\"ל לשבר אותם, וע\"ד מ\"ש (באיוב) ואם זרוע כאל לך עדה נא כל גובה וגאון, כ\"א למי שמשים עצמו כשיריים בחי' חסד דמ\"ה בחי' ביטול, הנה בבחי' חסד זה יכול להיות התלבשות בחי' חסד הבא מחמת עוצם גדולתו ית', וכמ\"ש מרום וקדוש אשכון ואת דכא ושפל רוח וכמשנ\"ת לעיל.\n<b>וזהו</b> מי אל כמוך נושא עון כו', ועכ\"ז לשארית נחלתו היינו למי שמשים עצמו כשיריים דוקא מבחי' ביטול, והיינו אף שנמשך מבחי' גבוה מאד שמשם"],[2000560301,"נושא עון כו', עכ\"ז זהו דוקא למי שהוא בבחי' ביטול דוקא, כי בחי' הביטול הוא כלי לקבל גילוי אור המשכה זו, משא\"כ חסד דלאומים אין אני והוא יכולים לדור. וזהו שיכולים הנשמות שמבחי' ביטול לקבל בחי' סוס שרכב עליו המלך שהוא בחי' גדלות כו', והיינו לפי שהם בבחי' שיריים כו' וכנ\"ל שהתלבשות בחי' רב חסד הוא דוקא בבחי' חסד זוטא כו'. אך הנה כ\"ז הוא עכשיו כשבחי' מ\"ה מברר ב\"ן, לכן עיקר ההמשכה הוא בבחי' חסד דמ\"ה, אבל לע\"ל כשיבורר בחי' ב\"ן אז יהי' עיקר הגילוי בבחי' ב\"ן דוקא, שזהו מ\"ש והי' שארית יעקב היינו השארית הנשאר אחר הבירור, כטל כו' אשר לא יקוה לאיש ולא ייחל לבנ\"א שלא יהי' המל' בחי' ב\"ן מקבל מבחי' איש חסד דמ\"ה כ\"א תוכל לקבל בעצמו מבחי' טל כו' בחי' כתר.\n<b>ומעתה</b> יובן ענין רק הכסא אגדל ממך גדולתי למעלה מגדולתכם, פי' אף שנש\"י שהם בבחי' ביטול יכולים לקבל בחי' רב חסד וכנ\"ל בפי' שמשים עצמו כשיריים, עכ\"ז גדולתי למעלה מגדולתכם. והענין יובן ע\"פ מ\"ש במ\"א בענין כרוב גודלו שיש ריבוי בחי' גדול, והיינו שבבחי' גדול גופא יש ריבוי מדריגות, וא\"כ אף שלע\"ל יהי' בחי' א\"א במדרגת ז\"א דהיינו שיאיר בחי' וגדל חסד כמו חסד זוטא, אעפ\"כ גדולתי למעלה מגדולתכם כו' כמ\"ש בע\"ח בענין ואמר ביום ההוא הנה אלקינו זה שיהי' בחי' א\"א במדרגת ז\"א וא\"א יהי' מדריגה היותר נעלה כו'. וענין קדושתי למעלה מקדושתכם הוא בבחי' המוחין כי גדולתי למעלה מגדולתכם הוא בבחי' המדות מדות דז\"א יהי' במעלת ומדריגת מדות דא\"א ומדות דא\"א יהיו במדרגה היותר נעלה, וקדושתי למעלה מקדושתכם הוא במוחין כי קדוש רומז לבחי' המוחין כמ\"ש במ\"א, ולכן הגם כי לע\"ל ארז\"ל עתידים צדיקי' שיאמרו לפניהם קדוש, מ\"מ כי קדוש אני קדושתי למעלה מקדושתכם כו'."],[2000560302,"<h3>ביום השני הקריב כו'</h3>\n<b>בס\"ד. ש\"פ פרה, ך\"ז.</b>\n<b>ביום</b> השני הקריב נתנאל כו' נשיא יששכר הקרב כו'. וארז\"ל במד\"ר פ' נשא פי\"ג אמר רפב\"י למה הוסיף הקרב וחסר יו\"ד אלא כנגד פרה אדומה שעשו באותו היום לכך הוסיף הקרב וחסר יו\"ד והעמיד התיבה על ד' אותיות כנגד ד' דברים שהיתה פרה צריכה, אדומה, תמימה, בלא מום, בלא נשיאות עול כד\"א ויקחו אליך פרה אדומה כו'. וצ\"ל מהו שייך ענין פרה אדומה לנתנאל נשיא יששכר. ועוד נת' במד\"ר שבפרה מרומז ד' מלכיות, אדומה זו בבל שנאמר אנת הוא רישא דדהבא, תמימה זו מדי כו', וצ\"ל מה שייך תמימה למדי דהתינח אדומה זו בבל כי נאמר אנת כו' דדהבא שהזהב הוא אדום, אבל תמימה זו מדי מה שייך תמימה למדי. אך הענין הוא דהנה מדי הוא גלות אחשורש.\n<b>ויובן</b> בהקדים ענין שם אחשורש ואסתר, דהנה כתיב בשה\"ש (סי' ב' ט\"ז) עד שיפוח היום ונסו הצללים סוב דמה לך דודי לצבי או לעופר האילים על הרי בתר, פי' הרי בתר פי' במדרש ע\"ד ברית בין הבתרים שנאמר ויבתר אותם בתווך שהוא ל' פירוד, כמו\"כ הרי בתר הוא בחי' פירוד ונקראים בלשון הזהר טורי דפרודא, דהנה כתיב ונהר כו' ומשם יפרד שהוא מקור לבחי' טורי דפרודא, כי ד' מחנות שכינה הגם כי הם בבחי' ביטול כמ\"ש וצבא השמים לך משתחוים שהם בבחי'"],[2000560303,"ביטול, עכ\"ז הנה ביטול זה הוא בחי' ביטול היש, ונק' וכנפיהם פרודות לגבי הביטול שלמעלה מהם שהוא בחי' ביטול במציאות, ובהשתלשלות נשתלשל מזה ד' נהרות שהם ד' מלכיות כמו שארז\"ל פישון זה בבל גיחון זה מדי כו', וה\"ז כמו השתלשלות הנה\"ב מפני שור שבמרכבה שהגם שהוא בבחי' ביטול עכ\"ז ע\"י ריבוי ההשתל' נשתלשל עד שנעשה למטה הנה\"ב שהוא בחי' רוח הבהמה היורדת למטה להתאוות לדברים גשמי' כו', ועד\"ז מבחי' ד' מחנות שבקדושה הגם שהם בבחי' ביטול היש עכ\"ז בהשתלשלות נשתלשל עד שנתהוו ד' מלכיות טורי דפרודא. וזהו מ\"ש (תלים ס\"ח י\"ז) למה תרצדון הרים גבנונים ההר חמד כו', שהרים גבנונים קאי על הר תבור וכרמל שהם בעלי מומין בחי' טורי דפרודא, אבל ההר חמד אלקים לשבתו הוא בחי' הר סיני.\n<b>והנה</b> על זמן הגלות נאמר ושמתי כסאי בעילם שארז\"ל גלו לעילם שכינה עמהם שקאי על הגלות דשושן כמ\"ש שושן הבירה אשר בעילם המדינה, שהוא בחי' התלבשות השכינה בגלות בע' שרים, וזהו מ\"ש כשושנה בין החוחים כו', ואעפ\"כ נק' שושן עמק איומה שאעפ\"י שהשושן היא בחי' מל' היא בין החוחים בגלות אעפ\"כ היא איומה, והענין הוא דהנה התלבשות השכינה בגלות היא לאגנא עלייהו על ישראל שלא יפלו ח\"ו ברע כו' לכן הוא גלות השכינה בע' שרים להגן עליהם בבחי' מקיף היינו ליתן כח לדחות הרע, ולא עוד כי גם בחי' דודי מאיר ג\"כ בגלות כי יש בחי' קוב\"ה ושכינתי', שכינתי' בחי' ממכ\"ע, וקוב\"ה הוא בחי' מה שהוא קדוש ומובדל בחי' סוכ\"ע הנה גם בחי' זה נמשך ג\"כ בגלות (בבחי' מל' לאגנא עלייהו) וזהו סב דמה לך דודי כו'.\nב) <b>והנה</b> במ\"ת נאמר כי תרכב על סוסיך, דהנה אנו רואים שהסוס הוא מרכבה להאדם שהסוס מוליך את האדם למקום נמוך אשר האדם בעצמו לא הי' יכול להגיע שמה, וכמו\"כ הוא מעלה אותו בהר כו', כמו\"כ עד\"ז יובן למעלה שכדי שיוכל להיות התגלות השכינה למטה על הר סיני כמ\"ש וירד ה' על הר סיני זהו ע\"י מרכבה דסוסים דוקא, שכמו השכל א\"א להבין כ\"א ע\"י אותיות דוקא, כמו\"כ א\"א להיות הגילוי מבחי' אדם הוא בחי' על הכסא דמות כמראה אדם שהוא בחי' תורה רמ\"ח פקודין רמ\"ח אברין דמלכא כ\"א ע\"י אותיות הנק' סוסים שהם יכולים להוליך את בחי' אדם למקום נמוך היינו שיהי' גילוי אלקותו ית' גם למטה בעולם העשי' הגשמי, ומה שיחזקאל ראה את המרכבה בחיות זהו בחי' המרכבה שיהי' גילוי אלקותו ית' בעולמות עליונים, אבל כדי שיומשך גם למטה בעולם העשי' על הר סיני זהו ע\"י סוסים דוקא כנ\"ל שהסוס יכול להוליך מטה מטה, וכמו\"כ להעלות ביותר הוא בחי' אותיות התפלה כו'. והנה כ\"ז הוא כדי שיהי' הגילוי על הר סיני"],[2000560304,"שהוא בקדושה, וכמשארז\"ל שהר סיני הוא הר נמוך והיינו הגם שהוא הר מ\"מ הוא הר נמוך בחי' ביטול ושפלות כי על הרים גבנונים הנ\"ל לא ניתן התורה כ\"א על הר סיני שהוא בחי' ביטול כי השראת השכינה היא במקום הביטול דוקא.\n<b>אך</b> הנה כדי שיהי' גילוי אלקות גם על הרי בתר הם טורי דפרודא הנ\"ל זהו ע\"י צבי ועופר האילים, כי הנה הצבי הוא קל ברגליו כמ\"ש רז\"ל ורץ כצבי, וכתי' (ש\"ב ב' י\"ח) ועשהאל קל ברגליו כאחד הצביים אשר בשדה, ועופר האילים הוא איל בחור שהם קלים ברגליהם מאד שרצים מהר לבקעה ומבקעה להר, והנה לרוב קלותם אינם מרכבה לאדם שהאדם אינו יכול לרכוב עליהם כו', כמו\"כ עד\"ז יובן בנמשל למעלה שיש בחי' אדם ואוא\"ס ב\"ה הוא למעלה מבחי' אדם וכמ\"ש כי לא אדם הוא, וזהו אדם אדמה לעליון היינו לבחי' כי לא אדם כו', וכדי שיומשך גילוי אלקותו ית' גם בהרי בתר טורי דפרודא צ\"ל נמשך מבחי' הגבוה ביותר כי כל הגבוה ביותר יכול להשפיל א\"ע ביותר. וזהו סב דמה לך דודי לצבי כו' על הרי בתר, שכדי שיהי' הגילוי גם בהרי בתר טורי דפרודא, צ\"ל דמה לך היינו לעצמותו ית' שלמעלה מבחי' אדם שזהו אדם אדמה לעליון בחי' כי לא אדם כו', ובחי' זו נמשך ע\"י הצבי ועופר האיילים שהם קלים ברגליהם להוליך למטה מטה גם בבחי' הרי בתר טורי דפרודא כו'.\n<b>וזהו</b> מ\"ש בזהר איהי עפר בקמץ ואיהו עופר בחולם, דהנה עפר ועפר אתוון דדין הם כאתוון דדין, והנה ישראל בגלות נמשלים לעפר כמשרז\"ל כתיב ושמתי את זרעך כעפר הארץ, וכתי' ככוכבי השמים, כשהם עולין עולים עד לכוכבים וכשהם יורדין יורדי' עד לעפר, נמצא ישראל בגלות הם כעפר הארץ ואזי איהו עפר שנמשך ע\"י עופר האילים להיות מקימי מעפר דל. וזהו מ\"ש ואף גם זאת בהיותם בארץ אויביהם לא מאסתים, שארז\"ל לא מאסתים בגלות בבל כו' שקחשיב כאן ד' מלכיות וכדי שיהי' הגילוי גם בד' מלכיות גלו לעילם כו', נאמר ואף גם זאת, פי' זאת היא בחי' שכינה בחי' מל' המקבל מבחי' זה, גם הוא ריבוי ואף הוא ריבוי שני, והיינו שריבוי הגם רומז לבחי' דודי, ואף רומז עוד לבחי' עליונה יותר, היינו בחי' דמה לך כנ\"ל לבחי' כי לא אדם הוא כו', והיינו שכדי שיהי' הגילוי גם בגלות בהרי בתר זהו ע\"י צבי ועופר האילים שנמשך מלמעלה מבחי' אדם כו'."],[2000560305,"<b>והנה</b> בסוף שה\"ש נאמר ברח דודי ודמה לך לצבי או לעופר האילים על הרי בשמים והיינו שהירידה היא בשביל העלי' אח\"כ, שכמו הירידה הוא ע\"י צבי כו' ממקום גבוה מאד לבחי' היותר נמוך, כמו\"כ אח\"כ העלי' היא ממקום נמוך ע\"י הצבי שקל ברגליו למקום גבוה מאד הוא בחי' הרי בשמים שהוא בחי' ריח בחי' מקיף. וזהו ענין ששה חדשים בבשמים שהוא בחי' ריח שהוא בחי' גבוה מאד [וע' בהגהות לד\"ה וקבל היהודים מענין מרדכי מה\"ת מר דרור, שהריח מגיע למעלה מן המוחין, שגם בחי' המוחין הם בכלל בחי' אדם, משא\"כ הריח מגיע לבחי' סוכ\"ע בחי' כי לא אדם הוא], ולכן הקטרת הי' על מזבח הפנימי משא\"כ קרבנות היו על מזבח החיצון, והיינו מפני כי הקטורת היו בחי' ריח [וי\"א סממני הקטרת בירור בחי' י\"א כתרין, א\"כ בעבודה זהו בחי' ריח בוגדיו, בחי' בע\"ת, וכמארז\"ל מקום שבע\"ת עומדין צד\"ג אין יכולי' כו'], ולכן אנו רואים שבדבר מאכל כאשר לועסין אותו מתבטל הטעם שלו, משא\"כ בבחי' הריח כו', כי הריח הוא בחי' גבוה מאד, וכמ\"ש במשיח והריחו ביראת ה' דמורח ודאין, שהוא ג\"כ בחי' ריח [וצ\"ל לפי הנ\"ל שזהו בחי' לאתבא צדיקייא בתיובתא כמ\"ש במ\"א].\nג) <b>והנה</b> הגורם בחי' עלי' זו זהו ע\"י הרי בתר שפי' במד\"ר ע\"ד ברית בין הבתרים, וכנודע ממ\"ש במ\"א שענין הכריתות ברית הוא שני אנשים העוברים בברית הם נעשי' כמו שני חצאי' שהא' בלא השני אין לו שלימות כו', כמו\"כ כבי' התקשרות אוא\"ס ב\"ה עם עולמות ונש\"י שהם כמו שני חצאי' וכמ\"ש כי חלק הוי' עמו כמ\"ש במ\"א בד\"ה הנה אנכי כורת (דשנת י\"ט), וע\"י שמבררי' טורי דפרודא עי\"ז נעשה העלי' ביותר כי יתרון האור מתוך החשך דוקא, וכמו שארז\"ל"],[2000560306,"מקום שבע\"ת עומדין צד\"ג אינם יכולים כו' ועי\"ז נעשה ריח בגדיו ריח בוגדיו כמ\"ש במ\"א. ולכן על הר סיני נאמר פ\"א אנכי ה' אלקיך אבל על הרי גבנונים הם הר תבור וכרמל נאמר על הר תבור ב\"פ אנכי כמ\"ש דבורה אנכי לה' אנכי אשירה, ובכרמל נא' ב\"פ ה' הוא האלקים כו', כמו שפי' רש\"י ז\"ל רסי' ה' דשופטי' בשם מדרש אגדה, והיינו כי יתרון האור כו', והב' פעמים אנכי שאמרה דבורה זהו ב' בחי' שבכתר, וכמ\"ש אנכי אנכי הוא מוחה פשעיך כו'. וזהו ג\"כ ענין אתה גבור לעולם אד', פי' אד' הוא ל' אדון וכדי שיהי' בחי' אדון נמשך מבחי' אתה גבור שם אגל\"א כו', בחי' אשרי משכיל אל דל כמ\"ש בסידור בכוונת המקוה, להיות מחיה מתים בירור הניצוצות (שז\"ע לא גלו ישראל אלא כדי להוסיף כו') ורב להושיע שבחי' רב הוא כמו כל רב מבבל שהוא רבוי טורי דפרודא, ומבחי' רב יהי' להושיע כו' (בחי' שע\"ה נהורין כו').\n<b>ובכ\"ז</b> יובן ענין אחשורש דתיבת אחשורש הוא אחש ורוש פי' אחש ל' מהירות כמו וחש עתידות למו, וכמו חושה לעזרתי, וכמו בעתה אחישנה, והיינו כי ענין המהירות הוא כמו ריצת הצבי היא במהירות מאד שהוא קל ברגליו, והיינו כי בגלות צריך להיות נמשך ממקום גבוה מאד כנ\"ל ונמשך ע\"י הצבי דוקא שהוא קל ברגליו, וזהו אחש ל' מהירות כו' (ופי' בעתה אחישנה היא הריצה מלמטלמ\"ע כמו ברח דודי). ורוש יש בו ב' פי', הא' הוא מלשון ענבימו ענבי רוש אשכלות מרורות למו, שהוא בחי' מרירות על ריחוק השכינה בגלות שהיא מלובשת בע\"ש, וזהו בשמן המור שמן הוא בחי' חכ', המור כשהוא במרירות על ההתלבשות בע\"ש. וגם פי' רוש מל' רש ועושר וכמו ולרש אין כל. וזהו ההפרש בין אות רי\"ש לאות דל\"ת שהדל\"ת הוא ג\"כ לשון דל מלשון דלותי ולי יהושיע, אך הנה בדלות יש מדרגות כמו בקרבנות שיש קרבן דלים ויש קרבן דלי דלות שהוא בחי' דלות ביותר וזהו בחי' רי\"ש, כי תמונת הדל\"ת יש לה יו\"ד מאחרי' משא\"כ הרי\"ש הוא עגולי, והיינו כי היו\"ד רומז לבחי' יו\"ד זעירא דפינחס, שהוא בחי' כל בשמים ובארץ שהוא בחי' השפעת היסוד למל', ואזי היא נק' דל (משא\"כ כשמקבלת מת\"ת שנק' עשיר), אבל הרי\"ש הוא עגולי שאין בו יו\"ד כלל, והיינו כאשר המל' מלובשת בע\"ש בגלות, וזהו ולרי\"ש אין כל שהוא בחי' חוסר כל שחסר בחי' כי כל בשמים ובארץ הנ\"ל, וזהו כענין ונהר יחרב ויבש, שארז\"ל יחרב בבית ראשון ויבש"],[2000560307,"בבית שני, שפי' יחרב כשיש עדיין מים רק שאינו כמו שהי' קודם ואעפ\"כ נשאר רשימה כו', אבל יבש הוא שנתייבש לגמרי כו', וע' בזח\"א ד\"ו דיבש הוא יותר מיחרב, וכמו\"כ יובן ההפרש בין רי\"ש לדלי\"ת, והגם שאחשורש הי' קודם בית שני, מ\"מ זהו רק לדוגמא שכמו ההפרש בין יחרב ליבש כמו\"כ ההפרש בין דלי\"ת לרי\"ש, וזהו ענין אחש ורש כו'.\n<b>היוצא</b> מזה שענין אחשורש הוא שכאשר נמשך מבחי' היותר גבוה למקום היותר נמוך הנה זה נמשך במהירות דוקא, וזהו ההפרש כמ\"ש השולח אמרתו ארץ עד מהרה ירוץ דברו, שהשולח הנה השליחות הוא בבחי' סדר השתלשלו' אבל בגלות הוא בחי' עד מהרה ירוץ דברו. ואחשורש גדל את המן שהי' מזרע עמלק, ואמר ישנו עם אחד פי' הגם שהם עם אחד עכ\"ז ישנו שהם בבחי' שינה כו', מפוזר ומפורד בין העמים במח\"ז הטורדות, והנס הי' מפני שהיו ישראל במס\"נ כל השנה. וזהו מה ראו על ככה ומה הגיע אליהם, פי' ככה, כי כה הוא בחי' כדמותנו, וככה בב' כפי\"ן הוא כאשר המל' מלובשת בבי\"ע, ואעפ\"כ מ\"ה בחי' ביטול במציאות הגיע אליהם לכאו\"א שהי' במס\"נ כל השנה שהיו בבחי' ביטול דמ\"ה הוא בחי' ביטול במציאות שהוא גבוה יותר מבחי' הביטול דכנפיהם פרודות שהוא בחי' ביטול היש, אבל הם הגיעו לבחי' ביטול דמ\"ה עד שבמ\"ת הי' רק החלו לעשות, שמפני שבמ\"ת הי' הביטול מצד גילוי אלקותו ית' על הר סיני וגם כפה עליהם הר כגיגית שהי' בבחי' אתעדל\"ע ולכן אמרו כל אשר דיבר הוי' נעשה שהוא בחי' ביטול הרצון מכל וכל, ולכן ארז\"ל במדרש גם על מ\"ת תמימה הי' עמדי, אבל בפורים נאמר קיימו וקבלו, וקבל היהודים את אשר החלו לעשות במ\"ת, שבפורים היו במס\"נ כל השנה בבחי' אתעדל\"ת מצד עצמם, והגם כי הי' אז בחי' הסתר והעלם כמ\"ש רז\"ל אסתר מן התורה מנין שנא' ואנכי הסתר אסתיר פני כו', ולכן נק' מלכות מדי תמימה שהביאו את ישראל שיהיו בבחי' תמימה כמ\"ש אחותי רעייתי תמתי שבאו לבחי' תמימות כו'."],[2000560308,"ד) <b>ומעתה</b> יובן מה שבהמגילה נאמר לא יסוף שלמדו בירושלמי בגז\"ש מלא יסף הנא' במ\"ת קול גדול ולא יסף שפי' לא פסק. כי הנה ארז\"ל במדרש שוחר טוב פי\"ט ע\"פ מלא קרנך שמן וכ\"ה במד\"ר ויקרא פ\"ב, כ\"מ שנא' לי אינו זז לא בעוה\"ב ולא בעוה\"ז, כמו כי לי בנ\"י עבדים, וכמו בדוד שנאמר כי ראיתי בבניו לי מלך, שפי' לי הוא ל' נצחיות והיינו כי נמשך מבחי' אוא\"ס שלמעלה מבחי' השתל' כי בהשתלשלות המדות יש חו\"ג שמדת הגבורה הוא בחי' דין מנגד לבחי' החסד שמצד זה נמשך גלות כו', אבל כ\"מ שנאמר לי אינו זז שנמשך מבחי' אני הוי' לא שניתי שנמשך בחי' זו על תמידית ואין בזה שינוים, ועד\"ז הוא בחי' התורה שהוא בחי' קול גדול בחי' פנימיות בינה ולא יסף שלא פסק שתמיד נמשך בחי' זו (כמו מהמעין שנמשך תמיד בלי הפסק כו', ע' בלק\"ת בד\"ה ושאבתם מים בששון מענין ממעייני הישועה). וזהו ההפרש בין אכלו רעים לשתו ושכרו דודים שבחי' זיווג בחי' דודים יכול להיות נפסק כמו בגלות שרחל מבכה על בניה כי איננו, שקאי על הוא\"ו שמסתלק לעילא ולעילא בגלותא, אבל רעים הם בחי' חו\"ב זיווגייהו תדיר שנמשך מבחי' אוא\"ס שלא שניתי כו', וזהו קול גדול ע\"ד גדול הוי' ולגדולתו אין חקר, וכמו באברהם שנאמר משתה גדול וארז\"ל גדול עולמים הי' שם כו'.\n<b>והנה</b> במד\"ר פ' יתרו ס\"פ ך\"ח ארז\"ל ע\"פ קול גדול שממנו נתנבאו כל הנביאים שעמדו, ולא כל הנביאים בלבד קבלו נבואתם מסיני אלא אף כל החכמים כו', רבנן אמרי שלא הי' לו בת קול, ובמד\"ר ס\"פ בלק קול גדול שהי' הולך מסוף העולם ועד סופו, והענין הוא דהנה כתיב קול דודי הנה זה בא לשון הוה שנמשך תמיד בחי' קול גדול זה, רק שנמשך בבחי' דילוג כמ\"ש בלק\"ת בד\"ה קול דודי ושם פ\"ג, ובהביאור ע\"פ הנ\"ל שקאי על קול התורה. וזהו משארז\"ל כל הקורא בתורה הקב\"ה קורא ושונה כנגדו, פי' כי קול הוא בחי' המשכה כמו שאנו רואים באדם שהקול הוא בחי' המשכה פנימיות, ועד\"ז יובן בקול דתורה שכאשר האדם קורא בתורה בפסוק ושא\"ד הנה נמשך בו בחי' קול גדול ממש שהי' בסיני, וזהו כל הנביאים קבלו נבואתם מסיני אפילו הנביאים שהיו אלף שנים אחר מ\"ת כי כל נבואה הוא מאצי', רק שנביאים מקבלים ע\"י נו\"ה דאצי', אבל מ\"מ הוא מאצי', ולא עוד"],[2000560309,"אלא אף כל החכמים כו', כי קול דתורה הוא בחי' קול גדול שאין לו הפסק שנמשך תמיד, ולכן כל הקורא בתורה הקב\"ה קורא ושונה כנגדו שנמשך בו בחי' קול גדול הנ\"ל הקל קול יעקב כו'. וזהו שאמרו שהולך מסוף העולם ועד סופו כו', כי לכאו' צ\"ל מהו מסוף העולם כו' דהל\"ל מתחלת העולם, אך ע\"פ פשוט הוא לפי שהעולם הוא כדורי ולא נמצא בו ראש וסוף, ובזהר ויצא דקנ\"ח ע\"ב נת' ע\"פ ברוך ה' כו' מן העולם ועד העולם מסוף עלמא דאתכסיא עד סוף עלמא דאתגליא, וזהו מסוף העולם ועד סופו. וע\"פ פשוט הפי' כאן שקאי על הזמן, שמתחלת הזמן של מ\"ת עד סוף הזמן נמשך בחי' הקול גדול דתורה שכל החכמים הלומדים תורה מקבלים מבחי' הקול גדול. ופי' המדרש שלא הי' לו בת קול הוא ע\"ד שנת' בלק\"ת סד\"ה והי' מספר בענין איש מזריע תחלה יולדת נקבה, בחי' בת קול שהקול נמשך בבחי' מל' והמל' משנת את הקול ומאיר בחי' הקול דמל', וזהו כמו הלבנה שמקבלת הארה מהשמש ומשנת את אור השמש ומאיר את אורה שהוא בחי' אור של תולדה ולא כמו אור השמש כו', ועד\"ז הוא ענין בת קול שהוא בחי' בת של הקול כו', אבל קול גדול דתורה לא הי' לו בת קול שהקול גדול כמו שהוא הי' נמשך כו', ולכן הוא בחי' קול גדול ולא יסף שלא פסק כו'.\n<b>ועד\"ז</b> יובן בענין מגילת אסתר שלא תבטל כי המגילה נק' אגרת וספר, שנקראת אגרת ע\"ש שהוא לפי שעה כו' כמ\"ש בדרוש, ואעפ\"כ היא נק' ספר כי מגילת אסתר לא תבטל שהיא ג\"כ מבחי' קול גדול ולא יסף שפי' לא פסק. וזהו משארז\"ל אסתר מן התורה מנין שצ\"ל מהו ענין אסתר מן התורה, ומה חסר לי אסתר כמו שהיא ולא מן התורה, אלא שפי' אסתר מה\"ת שהיא בחי' ומדרגה אחת דתורה כו', שנא' ואנכי הסתר אסתיר פני ביום ההוא שמוסתר אפי' מבחי' יום ההוא כו' כמ\"ש בדרוש. וגם הלכות אינם בטלים שהם הליכות עולם, פי' עולם ל' נצחית (ומ\"מ הנביאים בטלים לע\"ל כי הנביאים הם רק מקבלים מבחי' קול גדול ואינם מבחי' קול גדול עצמו, וי\"ל הנביאי' הם כמו ב\"ק שמשתנה אצלם הקול, וזהו כדמותנו כל הנביאים נתנבאו בכה, ומ\"ש לעיל שזהו מנו\"ה דאצי' י\"ל שורש נבואתם, אבל מ\"מ משתנה מעולם ועד עולם, ולכן ישעי' בן כרך בבריאה יחזקאל ביצי', זכרי' בסוסי', אבל מ\"מ השגתם הוא בבחי' השגת המהות, או שהנביא הוא כלי להגילוי שמתגלה לו, ולכן נאמר בשאול ויפשוט את בגדיו ויתנבא גם הוא, שלנבואה צ\"ל התפשטות הגשמיות, ע' בהגהות לד\"ה להבין ענין הסוכות בענין בגדי כה\"ג,"],[2000560310,"משא\"כ מגילת אסתר והלכות הם בחי' קול גדול עצמו כו', וצ\"ל שזהו ע\"ד חכם עדיף מנביא).\nה) <b>ומעתה</b> יובן ענין הפרה שהיתה מחוץ למחנה היינו חוץ לג' מחנות מחנה שכינה ומחנה לוי' ומחנה ישראל, וה\"ז כמו בגלות שהוא מחוץ כו' ולכן מרומז בה ד' מלכיות כנ\"ל. והענין הוא דהנה הפרה מטהר טומאת מת שהיא טומאה חמורה מאד שהיא אבי אבות הטומאה כי שרש בחי' המיתה הוא מז' מלכים קדמאין שנפלו בשבירה ומאן דנפל מדרגי' אקרי מית ונעשה מזה למטה ז' מדות רעות והרשעים בחייהן קרויין מתים, שנמשכים אחר תאוות גשמיות, אבל הפרה מטהר טומאת מת כמ\"ש באגה\"ק סי' ך\"ח בד\"ה למה נסמכה, שהפרה מברר ממה שנפל למטה מטה מנוגה, וזהו כענין אתה גבור לעולם מחי' מתים בירור הניצוצות ורב להושיע שמבחי' רב היינו בחי' ריבוי ופירוד נפשות עשו יש לי רב, יהי' להושיע כמשנת\"ל כו'. וזהו כל רב מבבל טורי דפרודא משא\"כ רבי מא\"י בתוס' יו\"ד שבא\"י מאיר בחי' ח\"ס ולכן נא' הקרב בלא יו\"ד לרמז על הפרה שמבררת מבחי' רב טורי דפרודא.\n<b>וכ\"ז</b> הוא ענין אפר הפרה שהיא בחי' הבירור מלמטלמ\"ע שהג' יסודות אש מים רוח יוצאין בעשן ונשאר האפר כו'. ויש בחי' מים חיים כמ\"ש ונתן עליו מים חיים אל כלי שז\"ע מה ששייך ענין הפרה לבני ישכר דוקא כי בני ישכר יודעי בינה לעתים, כמ\"ש (בדה\"א י\"ב ל\"ג) ומבני יששכר יודעי בינה לעתים לדעת כו' שהיו בעלי תורה שאפי' בדורו של משה לא אשתכח כוותייהו, כמארז\"ל ואילו נבונים אפי' בימי משה לא אשתכח, ונשיא שלהם נתנאל בחי' נתן אל שהוא בחי' התורה שניתנה מיד ליד כו', ופי' בס' בינה לעתים כי יש כ\"ח עתים י\"ד לטובה וי\"ד כו' שהם ב' ידות חו\"ג שמדת הגבו' מנגד למדת החסד, אבל בני ישכר יודעי בינה לעתים שממשיכי' בחי' בינה בהעתים, שבחי' בינה הוא דרור עלמא דחירו, וזהו שאנו"],[2000560311,"מבקשי' ותן בלבינו בינה כו', וזהו לדעת מה יעשה ישראל שממשיכי' ע\"י בחי' התו' בחי' מ\"ה בחי' ביטול בישראל, וזהו מי יתן טהור מטמא שקאי על פרה אדומה, טמא הוא מ\"ט אל\"ף, בחי' נו\"ן שערי טומאה וע\"י מי שער החמשים דבינה נעשה מטמא טהור כו', ולכן שייך זה לישכר שהיו בעלי תורה יודעי בינה שהוא בחי' המים חיים כו', וזהו מ\"ש בתורה או יחזיק במעוזי יעשה שלום לי שלום יעשה כו' ב\"פ שלום שלום לרחוק ולקרוב היינו לרחוק שנתרחק במ\"ט שע\"ט שנעשה קרוב ע\"י הפרה מי יתן טהור מטמא כו'."],[2000560312,"<h3>ולקחתם אגודת אזוב כו'</h3>\n<b></b><b>בס\"ד. (ש\"פ תזריע פ' החודש ר\"ח ניסן, רכ\"ז).</b>\nואגודתו על ארץ - ג\"פ\n[תזריע - ר\"ח ניסן]\n<b>ולקחתם</b> אגודת אזוב וטבלתם מן הדם אשר בסף והגעתם אל המשקוף כו'. והנה איתא במדרש שה\"ש בפסוק כתפוח בעצי היער משל ע\"ז לאדם שלקה ברגליו חזר על כל הרופאים כו' ובא א' ואמר לו בדבר קל אתה מתרפא כו', כך אמר להם משה אם אתם רוצים ליגאל ולקחתם לכם אגודת אזוב כו', והנה להבין המשל הזה מהו שלקה ברגליו, י\"ל מקודם מ\"ש (עמוס ט' ו') הבונה בשמים מעלותיו ואגודתו על ארץ יסדה, ופי' בזח\"ג פ' צו דל\"ה א' ר' יצחק א' ואגודתו כד\"א ולקחתם אגודת אזוב, שמשוה בחי' אגודתו לבחי' ולקחתם אגודת אזוב. והנה ע\"י ואגודתו נמשך הבונה בשמים מעלותיו, וצ\"ל מהו לשון הבונה בשמים עליות מהו שייך למעלה בנין עליות כו'. והענין הוא דהנה כתי' ואשים דברי בפיך ובצל ידי כסיתיך לנטוע שמים כו', ואשים דברי הוא בחי' תורה, ובצל ידי הוא בחי' מצות בצל החכ' בצל הכסף, לנטוע שמים כו' הוא בחי' קרבנות תפלה כו', ולכאורה אינו מובן מה שייך לומר לנטוע שמים שהלא השמים כבר נברא כו'.\n<b>הנה</b> כתיב (ישעי' מ' י\"ב) מי מדד בשעלו מים ושמים בזרת תכן, ולמדו מזה בגמ' עירובין דכ\"א ע\"א שהשמים היא רק א' משלשת אלפים ומאתים בתורה, וכמו שפרש\"י שם שהזרת הוא חצי אמה ע\"ש. ולהבין כ\"ז הענין הוא דהנה הבריאה נק' יש מאין כי אני הוי' לא שניתי לא כמו שהנשמה מחיה את הגוף שמתלבשת ומתפעלת כו' כי מלכותך כו' יהללו את שם הוי' כי הוא צוה ונבראו. ומעתה יש להבין כיון שהבריאה נעשה רק מזיו והארה שאינו נוגע אל עצמותו, א\"כ אינו מובן מהו ענין השבת כי שבת הוא בחי' שביתה כי בו שבת, ומה שייך שביתה כיון שלא הי' עבודה כלל וכמ\"ש רז\"ל במדרש לא בעמל ולא ביגיעה ברא כו' כ\"א במאמר פיו, ומהו ענין השבת שהוא בחי' שביתה ממלאכה. והענין הוא דהנה איתא בזהר שעשרה מאמרות נק' מילין דהדיוטא ולאו אורחא דמלכא כו',"],[2000560313,"וגם זה לכאו' אינו מובן איך נק' הע\"מ מילין דהדיוטא, אך שרש ענין הדיוט נמצא בתרגום אונקלוס ע\"פ אין זה כ\"א בית אלקים, ומתרגם לית דין אתר הדיוט, וי\"ל מהו ענין הדיוט.\n<b>והענין</b> הוא, דהנה כתיב נער הייתי גם זקנתי וארז\"ל שרו של עולם אמרו שמט\"ט נק' נער, והיינו לפי שכדי שיומשך ההשפעה מעולם האצי' למטה שיהי' עולם שהוא בחי' גבול וכמארז\"ל מהארץ לרקיע מהלך ת\"ק שנה, וגם שנעשה העולם בבחי' יש ודבר נפרד לגמרי, וגם שיש שם בחי' עה\"ד טו\"ר, הוצרך להתצמצם השפעה זו בעולם היצי' בבחי' מט\"ט, וע' בלק\"ת בשה\"ש בד\"ה מה יפו פעמיך בנעלים. וזהו שנק' נער אנפי זוטרי קטנות וצמצום, וע\"כ נק' הדיוט וכמ\"ש בזהר שמט\"ט נק' הדיוט לגבי מארי' (וזהו משארז\"ל אל תהי ברכת הדיוט קלה בעיניך), וזהו כמו כהן הדיוט לגבי כה\"ג שלגבי כה\"ג נק' הדיוט. ועד\"ז ענין שעשרה מאמרות נק' מילין דהדיוטא שאע\"פ שע\"מ הם גבוהים מאד למעלה, אך מ\"מ כיון שע\"י נעשה מקור לעולמות שהם בחי' גבול ויש כו', וגם שנעשה מקור לעה\"ד טו\"ר שייך לאמר לשון מילי דהדיוטא. ויובן זה ממה שאנו רואים שע\"י שיש באדם חצר הכבד המפסיק שהוא בחי' הקרומא דפסיק במעי דבר נש שעי\"ז נעשה ההבדל בין אברי הנשימה שהם בתכלית הדקות לאברי המזון כמו המעיים שהם מבררים את המאכל עד שיצא הפרש לחוץ, וכך עד\"מ זה יובן שע\"י מאמר יהי רקיע המבדיל בין מים למים נעשה הבדלה עד שמים תחתוני' נעשי' מקור לתענוגי' גשמיי' בחי' עה\"ד טו\"ר, והרי זה נעשה ע\"י המאמר יהי רקיע שע\"י המאמר נעשה ההבדלה כו', וע\"כ נק' מילין דהדיוטא. וזהו מה שתרגם אונקלוס לית דין אתר הדיוט, כי אתר הדיוט הוא בחי' השייך לעולמות, והיינו בחי' ע\"מ כו', משא\"כ בבהמ\"ק הי' מאיר למעלה מבחי' עולמות שהי' מאיר בו גילוי ש' הוי', וכמ\"ש אכן יש הוי' במקום כו', ע\"כ אינו אתר הדיוט.\n<b>וזהו</b> ג\"כ ענין השבת שהוא בחי' שביתה, שאע\"פ שאינו שביתה ממלאכה, מ\"מ הוא בחי' שביתה מהירידה, לפי שהע\"מ הם בחי' ירידה והשפלה נגדו, וכמו למשל חכם גדול כשמדבר דברים פשוטים בעלמא הוא ירידה גדולה אצלו וכששבת מהדיבורים אזי היא בחי' שביתה אצלו, וכך שבת הוא בחי' שביתה עליות העולמות למעלה מבחי' ע\"מ כי בו שבת מבחי' מאמר דע\"מ כו'."],[2000560314,"ב) <b>ועפ\"ז</b> יובן מ\"ש (איוב ד' י\"ח) הן בעבדיו לא יאמין ובמלאכיו ישים תהלה, והיינו לפי ששרש המלאכים הוא מבחי' ל' כלים דז\"א ויש להם נשמה וגוף וע\"כ הגוף שלהם מסתיר ג\"כ, ואף שאין שייך שם בחי' חטא ועון, אעפ\"כ הביטול אינו כדבעי מפני שהגוף מסתיר, וכן כתי' (איוב ט\"ו ט\"ו) הן בקדושיו לא יאמין ושמים לא זכו בעיניו, ג\"כ מהאי טעמא שהביטול אינו כדבעי, לפי ששרש השמים הוא מבחי' ע\"מ מילין דהדיוטא. ובזהר ויגש דר\"ז ע\"א מפרש הן שמים לא זכו בעיניו למעליותא שמפני חביבותן ע\"כ לא זכו בעיניו כמו למשל אדם כשיש לו כלי נאה או בנין נאה שכל מה שהכלי חביב עליו יותר הוא מתקנה יותר ודומה לו שעדיין לא ניתקנה היטב וצריכה תיקון עדיין, וכך שמים לא זכו בעיניו.\n<b>וזהו</b> לנטוע שמים כו' שצריך לנטוע ולתקן את השמים כי כל מה שנברא בשימ\"ב צריכין תיקון ואפי' שמים, והמכוון מזה הי' כדי שיהי' עבודה כו'. וע\"י מה עושין הנטיעה והתיקון זהו ע\"י תפלה, כי תפלה נק' סולם מוצב ארצה וראשו מגיע השמימה, לפי שהתפלה מתחלת מדברים תחתונים פסוד\"ז הללו את ה' מן הארץ כו', ואח\"כ יוצר אור התבוננות מהמלאכים, ואח\"כ ק\"ש שמע ישראל עלו במחשבה, וכשיתבונן בכל זה ששרש הכל הוא מבחי' ע\"מ מילין דהדיוטא עי\"ז נעשה ואהבת את הוי' אלקיך אהבה ורצון לעצמותו ומהותו ית', ואח\"כ הוא בחי' שמו\"ע ברוך אתה הוי' המשכה למטה, כי בסולם עולים ויורדים כו' [וע\"י העלי' בק\"ש לבחי' אליו ולא למדותיו בבחי' מס\"נ אחד ואהבת, נמשך אח\"כ בשמו\"ע בחי' שם הוי' שזהו ענין הירידה וההמשכה בסולם דתפלה (וע' בד\"ה דרשו ה' בהמצאו בס' טו\"ב שיש כמה פי' בפי' אליו ולא למדותיו)], ועי\"ז נעשה לנטוע שמים שממשיכים ומתקנים את השמים, וכמ\"ש היושבי בשמים שהיו\"ד שבתיבת היושבי הוא מיותר, אלא שלכן נאמר היושבי היושב יו\"ד שממשיכים בחי' י' דש' הוי' בהשמים שהוא בחי' המשכת החכמה [ע' בזח\"א ויחי דרך\"ט ע\"א], והשמים כסאי שהשמים נעשה כסא ומכון לשבתו ית'. וזהו ג\"כ מ\"ש כונן שמים בתבונה, שממשיכים בשמים מבחי' תבונה, כי שמים הוא אש ומים בחי' מדות, משא\"כ תבונה הוא למעלה מבחי' מדות וכמ\"ש לתבונתו אין"],[2000560315,"מספר, כי מתחלה כתי' גדול אדונינו ורב כח שהוא בחי' שיעור קומה של יוצר בראשית ששרשו מבחי' מדות דאצי' שהוא מקור בחי' גבול, משא\"כ לתבונתו אין מספר, וזהו כי אמרתי עולם חסד יבנה, יבנה הוא בחי' בינה שממשיכים בעולם מבחי' בינה, וזהו ע\"י בחי' תפלה בחי' התבוננות ועי\"ז נמשך ההמשכה אח\"כ מבחי' בינה.\n<b>והנה</b> כמו\"כ ע\"י התורה ממשיכים בהשמים ואשים דברי בפיך, דהנה ושמים בזרת תכן חצי אמה, והנה חצי אמה הוא בחי' ה' תתאה ג' קוין שנעשה מקור לעולמות בי\"ע, והאמה הוא בחי' ה' עילאה, וזה שהשמים הוא רק א' משלשת אלפים ומאתים מהתורה, דהנה אורייתא מח\"ע נפקת, והנה בחכמה יש ל\"ב נתיבות חכ' שהוא כנגד ך\"ב אותיות וע\"ס, והנה יו\"ד כלול מיו\"ד ויו\"ד מיו\"ד וזהו שלשת אלפים ומאתים, וכמו שיש ל\"ב נתיבות חכ' תתאה, כמו\"כ יש ל\"ב פעמים אלקים שבמע\"ב שהוא ל\"ב נתיבות ח\"ת, וזהו חצי אמה ה' תתאה שהוא רק חלק א' משלשת אלפים ומאתים, וזהו שע\"י התורה ממשיכים בהשמים שהיא רק בזרת תכן חכ' תתאה [ונק' חלק א' י\"ל לפי שיחידות במל'], משא\"כ אורייתא הוא חכ' עילאה כו'. [ובצל ידי גמ\"ח כמארז\"ל בירושלמי דתענית ללמדך שכל מי שעוסק בתורה ובגמ\"ח זוכה לישב בצלו של הקב\"ה, וזהו בצל החכ' בצל הכסף, והיינו כי גמ\"ח טוב לשמים וטוב לבריות, ועי\"ז ממשיך בשמים מבחי' על השמים כו' ע' בד\"ה ציון במשפט בס' פ', וע' בד\"ה פדה בשלום נפשי]. וזהו הבונה בשמים מעלותיו שממשיכים בהשמים מבחי' מעלותיו שהוא בחי' על סוכ\"ע וכמ\"ש בחנה ותתפלל חנה על הוי' למעלה משם הוי' כי גדול מעל שמים חסדך כו', וע' מענין על הוי' בד\"ה ויהי אומן את הדסה מענין הוקם על עולה של תורה ועולה של תשובה.\nג) <b>אך</b> הנה כ\"ז כשואגודתו על ארץ יסדה שיש בחי' אגודה אחת, כי הנה אגודה הוא כשיש התכללות דוקא, והיינו ע\"י שיש להם בחי' ביטול וכמ\"ש ביעקב ע' נפש יוצאי ירך יעקב ובעשו נאמר נפשות ל' רבים והיינו לפי שע' נפש הם יוצאי ירך יעקב שנמשך היו\"ד בבחי' עקביים ויש להם ביטול כו', ע\"כ יכולים הם להתכלל, משא\"כ כשהם בבחי' יש אינם יכולים להתאחד ולהתכלל. והנה כשיש בחי' אגודה בחי' התכללות אז יכולים להמשים מבחי' מעלותיו, וכמו במ\"ת נאמר ויחן ישראל שנתאחדו אז ניתן להם התורה, ברכנו אבינו כולנו כאחד באור פניך, כאחד דוקא,"],[2000560316,"וזהו שקדושה אין אומרים כ\"א בעשרה דוקא, אבל אחד אעפ\"י שהוא אדם גדול מאד אינו יכול לומר קדושה, וכן ברכת הזימון הוא דוקא בשלשה, בשלשה אומר נברך שעושין בריכה, משא\"כ אחד כו', אבל עשרה או ג' אע\"פ שהם פחותי ערך יכולים לומר קדושה או ברכו כו'. וזהו ואגודתו על ארץ יסדה אז הבונה בשמים מעלותיו, אליך נשאתי את עיני כו' בבחי' ביטול והתכללות אז היושבי בשמים כו', וזהו ולקחתם אגודת אזוב אגודה דוקא.\n<b>ולהבין</b> למה אזוב דוקא, הענין הוא דהנה אזוב הוא בחי' ביטול, וכמ\"ש מלכים א' ה' י\"ג מן הארז אשר בלבנון ועד האזוב אשר יצא בקיר, שהוא בחי' ביטול ושפלות, וע\"י בחי' הביטול ושפלות עי\"ז יכול להתכלל עם זולתו, דמאחר שאינו תופס מקום כ\"כ בעיני עצמו יוכל להתכלל עם חבירו, וזהו אגודת אזוב דבכדי להיות בבחי' אגודה זהו ע\"י אזוב בחי' ביטול ושפלות. ועוי\"ל בפי' אזוב דהנה בספר פ\"י פי' אזוב וסף הוא בגימט' יוסף, והענין הוא דהנה כתי' אלה תולדות יעקב יוסף, ולהבין למה יוסף דוקא, הענין הוא דהנה ידוע שיעקב הי' בחיר שבאבות בריח התיכון המבריח מן הקצה אל הקצה [וזהו בחי' ארז וא\"ו רברבא], אך הנה כ\"ז הוא רק למעלה מקצה השמים דלעילא עד קצה השמים דלתתא, אבל למטה אינו נמשך בגילוי, וכדי שיהי' תולדות יעקב שיהי' נמשך למטה זהו ע\"י יוסף שהוא בחי' יסוד כי כל בשמים ובארץ דאחיד בשמיא בחי' ת\"ת וארעא בחי' מל', ואפ\"ל שזהו ההשפעה שצ\"ל ע\"י לצמצם א\"ע כו', וידוע שכדי להיות השפעה זו נמשך כח זה מלמעלה, כענין והנורא אל עליון כו' קונה הכל כו' ומביא גואל, וע\"כ האזוב חשוב כמו הארז אשר בלבנון כו' במד\"ר פ' בא, וזהו שיוסף הי' השליט במצרים, וע\"כ ע\"י יוסף ירדו למצרים ועל ידו עלו כו' [ע' בזהר ויחי דרך\"ו ע\"א], וזהו אגודת אזוב דוקא שעי\"ז יומשך למטה ג\"כ.\n<b>ובזה</b> יובן המשל של המדרש משל לא' שלקה ברגליו, דהנה נש\"י נקראו בחי' רגל כמ\"ש בנים אתם כו' ברא כרעא דאבוה, דכמו שהרגל בטל לגבי הראש כך נש\"י הם בטלים לאלקות, ובדרך פרט יש בכל נשמה ראש ורגל, ראש הוא בחי' מוחין חב\"ד, חג\"ת הוא בחי' ידים, ורגל נה\"י הוא בחי' מעשה, והנה אע\"פ שהרגל"],[2000560317,"הוא למטה מהראש, מ\"מ יש מעלה ברגל שהוא מוליך את הראש, שהילוך היא מעלה גדולה וכמ\"ש ונתתי לך מהלכים בין העומדים האלה שההילוך הוא בלי גבול ממש. וזהו שהמועדים נק' שלש רגלים, והיינו לפי שבכל יו\"ט הוא בחי' עליית העולמות וכמ\"ש מי זאת עולה מן המדבר שהוא כמו בחי' שבת שביתה מע\"מ מילין דהדיוטא, וכך יו\"ט הוא בחי' שביתה אפי' כשחל יו\"ט ביומין דחול. והנה כ\"ז כשהרגל הוא בשלימות, משא\"כ כשחלה ברגליו שפגם באיזה מעשה ואפילו בדקדוקי סופרים נק' חולה, וכמ\"ש סומך ה' לכל הנופלים כו', ואז נק' חולה [וע' מענין חולה בד\"ה כתפוח בעצי היער בס' פ' מענין חולה שיש בו סכנה וחולה שאין בו סכנה, וחולה שחסר שער הנו\"ן, וע' בלק\"ת בד\"ה והי' מדי חדש מענין חולת אהבה, וע' בד\"ה ולא זכר שר המשקים ך\"ו].\n<b>ואמר</b> לו בדבר קל אתה מתרפא שהוא בחי' תשובה שנק' רפואה וכמשארז\"ל גדולה תשובה שמביאה רפואה לעולם. ולהבין מהו ענין בחי' רפואה הנה כתי' באליהו וירפא את מזבח ה' ההרוס, ולהבין מה שייך במזבח ענין רפואה, הענין הוא דהנה על המזבח הי' אש שלמטה ואש שלמעלה, ואש שלמטה מצוה להביא מן ההדיוט. והנה בעבודה אש בחי' אהבה כרשפי אש, ויש ב' מיני אהבה היינו אהבה ממילין דהדיוטא מהתבוננות של עולמות איך שהם רק זיו והארה בעלמא ועי\"ז נעשה לו אהבה ותשוקה לאלקות, זהו הנק' אש של הדיוט. ויש אהבה הבאה מלמעלה ונק' אש שלמעלה [וע' בד\"ה ועשית ציץ ובד\"ה מגילה נקראת מענין ב' בחי' אהבה, אה\"ע ואה\"ר הבאה מלמעלה ע\"י אהרן כהנא רבא, בחי' אהבתי אתכם אמר ה']. אך הנה יש בחי' אש זרה דהיינו רשפי אש בבחי' מילי דעלמא, ויש אש זרה ממש דהיינו תאוות רעות ואפי' בהיתר, ואז נק' חולה כמו למשל האדם צריך שיהי' לו חום הטבעי, אבל כשנעשה לו אש זרה אז נעשה חולה וצריך לרפואה, וזהו שאמר להם בדבר קל אתם מתרפאין לפי שנש\"י היו אז בחי' חולה ברגליהם לפי שהיו מושקעים במ\"ט שערי טומאה והיו צריכים לרפואה, וא' להם בדבר קל היינו באזוב שהוא בחי' ביטול ושפלות, כי בעל תשובה הוא בחי' שפלות לב נשבר ונדכה כו'."],[2000560318,"<b>וטבלתם</b> מן הדם אשר בסף, הוא בחי' תושב\"כ ותושבע\"פ, כי סף הוא בחי' סמ\"ך מסכתות וכמ\"ש ששים המה מלכות ושמונים פלגשים וארז\"ל ששים המה מלכות ס' מסכתות ושמונים פלגשים אלו ברייתות שהוא בחי' תושבע\"פ, ודם הוא בחי' תושב\"כ לפי שרמ\"ח פקודין הם רמ\"ח אברין, והתורה היא בחי' דם בחי' פנימיות החיות של האברים כמ\"ש כי הדם הוא הנפש, ולכן נק' התורה אדם כמ\"ש זאת התורה אדם, אדם ר\"ת א' דם כמ\"ש בלק\"ת בד\"ה בשעה שהקדימו פ\"ב. ועי\"ז והגעתם אל המשקוף ואל שתי המזוזות בחי' ג' אבות חח\"ן קו הימין בג\"ה קו השמאל וקו האמצעי המחברן, והיינו שכל אחד יכול לומר מתי יגיע מעשי למעשה אבותי. ועוי\"ל אל המשקוף ע\"ד השקיפה ממעון קדשך כו' וברך שגם מבחי' השקפה יומשך שיהי' וברך את עמך ישראל, וע\"ד שארז\"ל גדולי'. והיינו ואשים דברי כו' ובצל ידי כו' לנטוע שמים כו' ע\"י ג' בחי' תורה ועבודה וגמ\"ח עי\"ז ממשיכי' בהשמים מבחי' על השמים כנ\"ל והיינו ע\"י ואגודתו על ארץ, עי\"ז נמשך הבונה בשמים מעליותיו וכנ\"ל.\n<b>וזהו</b> שא' ר' יצחק בזח\"ג הנ\"ל ואגודתו כד\"א ולקחתם אגודת אזוב, והיינו שכמו ע\"י האגודה נמשך להיות הבונה בשמים מעלותיו כנ\"ל, כמו\"כ זהו\"ע שע\"י האזוב וע\"י הדם אשר בסף בחי' תומ\"צ עי\"ז והגעתם אל המשקוף כו', דהנה אזוב הוא א\"ז ו\"ב, והיינו שהאל\"ף מאיר ונמשך בזיי\"ן זהו כענין הבונה בשמים מעלותיו, ו\"ב היינו שאח\"כ וא\"ו זעירא נמשך בבי\"ת היינו בחי' המל' בחי' ברכה, וזהו אזוב וסף זהו גימ' יוסף בחי' השפעת יסוד למל'. ומה שעל הזיי\"ן נמשך אל\"ף ובבי\"ת וא\"ו זהו כענין אחד בחילופי אתוון ועד שמתחלף האל\"ף על וא\"ו, וכמו לא צר, ולא אנחנו קרי בוא\"ו וכתי' באל\"ף, וזהו ע\"ד כגוונא דאינון מתייחדין לעילא באחד אוף הכי איהי אתייחדת לתתא ברזא דאחד, ע\"כ צ\"ל אגודה אחת, ואז הבונה בשמים מעלותיו למהוי אחד באחד. ויובן זה ע\"ד מ\"ש בסידור ענין כגוונא דאינון מתייחדין שהמדות עליונות כשבאין למטה הן בבחי' הפירוד והתחלקות זמ\"ז, אך בעודן כלולים בהשכל שם הם ביחוד ויוכל להמתיק הדין כו', ועד\"ז בבי\"ע כי מיכאל שר של מים וגבריאל שר של אש, אך ע\"י המשל ופחד עושה שלום במרומיו נעשה לאחדים כו', אך מ\"מ למעלה יחו\"ע ביטול אמיתי ולמטה יש ובטל, ואח\"כ למהוי אחד באחד יחוד יחודא עילאה ביחו\"ת, והיינו כמ\"ש בזהר ויקהל דקצ\"ז ע\"ב ליחדא רתיכא עילאה ברתיכא תתאה, ומזה יובן ענין ולקחתם אגודת אזוב יחוד ב' בחי' ביטול הנ\"ל, ועי\"ז נמשך להיות והגעתם אל המשקוף השקיפה כו'"],[2000560319,"מן השמים וברך כו' שיומשך מבחי' על השמים בשמים, ואז וברך את עמך ישראל דוקא."],[2000560320,"<h3>דודי לי ואני לו כו'</h3>\n<b></b><b>בס\"ד. שבת הגדול, מצורע, ך\"ז.</b>\nעיבור ולידה - ו\"פ\nמצורע שה\"ג\n<b>דודי</b> לי ואני לו הרועה בשושנים. הנה פי' רש\"י ובמד\"ר שקאי על יצ\"מ שהי' דודי לי תחלה, כי פעם כתיב אני לדודי ודודי לי שר\"ת אלול כי אלול ור\"ה הוא זמן התשובה שהיא מלמטלמ\"ע לכן אני לדודי תחלה, אבל בפסח ויצ\"מ הי' דודי לי תחלה שהי' בבחי' מלמעלמ\"ט כמ\"ש קול דודי הנה זה בא מדלג בבחי' דילוג מלמעלמ\"ט כו'.\n<b>הנה</b> ארז\"ל במד\"ר ע\"פ דודי לי, הוא לי לאב ואני לו לבן, הוא לי לאב שנאמר כי אתה אבינו, כי הייתי לישראל לאב, ואני לו לבן בני בכורי ישראל, בנים אתם להוי' אלקיכם, הוא לי לרועה רועה ישראל האזינה, ואני לו לצאן שנא' (יחזקאל סס\"י ל\"ד) ואתן צאני צאן מרעיתי. וצ\"ל הדמיון דאב ובן לצאן ורועה, שאינו בערך החביבות בין צאן ורועה לאב ובן. אך הענין הוא דאב ובן זהו בזמן הגאולה שאז נש\"י והקב\"ה כמו אב ובן, ולכן הביאו פסוק כי הייתי לישראל שרישי' דקרא הוא בבכי יבואו (בירמי' סי' ל\"א), שקאי על גאולה דלע\"ל שבבכי יבואו ואז כי הייתי לישראל לאב, וגם פסוק בני בכורי ישראל נא' למשה בתחלת שליחותו אל פרעה לגאול את ישראל בשמות פ\"ג, אבל בזמן הגלות נמשלי' נש\"י לבחי' צאן והקב\"ה כביכול לבחי' רועה.\n<b>ולהבין</b> מהו ענין המשל מצאן ורועה יובן בהקדם מה שנתבאר שם עוד במד\"ר ע\"פ זה, שפי' דודי לי הוא לכשיהי' לו דבר לא תבע אלא ממני, הגם כי יש"]]});
